const list=value=>Array.isArray(value)?value:typeof value==='string'?value.split(',').map(item=>item.trim()).filter(Boolean):undefined;
const bodySchema=z.object({sourceIds:z.array(z.string()).max(32).optional(),products:z.array(z.string()).max(30).optional(),formats:z.array(z.string()).max(30).optional(),collectionIds:z.array(z.string()).max(100).optional(),
  resolution:z.union([z.enum(['best','all','native']),z.number().positive()]).optional(),bufferMeters:z.number().min(0).max(10000).optional(),scope:z.enum(['area','source']).optional(),
  storageRoot:z.string().refine(value=>path.isAbsolute(value)&&!/[\r\n\0]/.test(value),'Use an absolute storage path').optional(),assetIds:z.array(z.string()).max(100000).optional(),
  courseId:z.string().optional(),planId:z.string().optional(),allowPartial:z.boolean().optional(),processAfterDownload:z.boolean().optional(),resolutionMeters:z.number().positive().optional(),
  contourIntervals:z.array(z.number().positive()).min(1).max(20).optional(),resampling:z.enum(['near','bilinear','cubic','cubicspline','lanczos','average','mode']).optional(),
  groundOnly:z.boolean().optional(),preferPointCloud:z.boolean().optional(),zScale:z.number().positive().optional(),hillshadeStyle:z.enum(['classic','multidirectional']).optional(),slopeUnits:z.enum(['degrees','percent']).optional()}).passthrough();

export async function createService(overrides={}) {
  const config=loadConfig(overrides);await mkdir(config.storageRoot,{recursive:true});
  const catalog=new Catalog(config.catalogPath);catalog.registerRoot(config.storageRoot);
  const network=new Network(config);const gis=new Gis(config);const indexes=new VectorIndexes(config,network,gis);const registry=new SourceRegistry(config,catalog,network,indexes);
  const processor=new TerrainProcessor(config,catalog,gis);const jobs=new JobManager(config,catalog,network,registry,processor);const reader=new TerrainReader(catalog,gis);
  const app=express();const tickets=new Map();
  app.disable('x-powered-by');
  app.use(helmet({contentSecurityPolicy:{directives:{'default-src':["'self'"],'script-src':["'self'"],'style-src':["'self'","'unsafe-inline'"],'font-src':["'self'"],'img-src':["'self'",'data:','blob:','https://*.tile.openstreetmap.org'],
    'connect-src':["'self'"],'object-src':["'none'"],'upgrade-insecure-requests':null}},crossOriginResourcePolicy:{policy:'cross-origin'}}));
  app.use((request,response,next)=>{
    if(['localhost','127.0.0.1','::1'].includes(config.host)&&!['localhost','127.0.0.1','::1','[::1]'].includes(request.hostname))return next(new HttpError(403,'Untrusted Host header.'));
    const origin=request.get('origin');if(origin&&!config.corsOrigins.includes(origin))return next(new HttpError(403,'Origin is not allowed. Add the consumer origin to CORS_ORIGINS in .env.'));next();
  });
  app.use(cors({origin:config.corsOrigins,exposedHeaders:['Content-Length','Content-Range','ETag','Accept-Ranges']}));
  app.use(express.json({limit:'5mb'}));
  app.get('/api/health',(request,response)=>response.json({status:'ok',service:'TerrainServer',version:'1.0.0',port:config.port,localTerrainOnly:true}));
  app.use('/api',(request,response,next)=>{
    if(!config.apiKey||request.method==='OPTIONS'||request.path==='/openapi.json'||/^\/downloads\/[a-f0-9]{48}\//.test(request.path))return next();
    const supplied=(request.get('authorization')||'').replace(/^Bearer\s+/i,'');const expected=Buffer.from(config.apiKey);const actual=Buffer.from(supplied);
    if(actual.length!==expected.length||!timingSafeEqual(actual,expected))return next(new HttpError(401,'API key required. Send Authorization: Bearer <API_KEY>.'));next();
  });
  const base=request=>`${request.protocol}://${request.get('host')}`;
  const urlFor=(request,asset)=>`${base(request)}/api/assets/${asset.id}/download.${asset.extension||'bin'}`;
  const publicAsset=(request,asset)=>{
    if(!asset)return null;const {path:filename,...data}=asset;
    return {...data,url:asset.downloaded?urlFor(request,asset):null,downloadUrl:asset.downloaded?urlFor(request,asset):null,source:asset.sourceId,
      bounds:asset.bbox,bbox:{minLng:asset.bbox[0],minLat:asset.bbox[1],maxLng:asset.bbox[2],maxLat:asset.bbox[3]},cellSizeMeters:asset.effectiveCellSizeMeters||asset.resolutionMeters,
      previewUrl:asset.downloaded&&['tif','tiff'].includes(asset.extension)?`${base(request)}/api/assets/${asset.id}/preview.png`:null};
  };
  const optionsFor=request=>{
    const input=request.method==='GET'?request.query:request.body;const result={...input,sourceIds:list(input.sourceIds||input.sources),products:list(input.products),formats:list(input.formats),collectionIds:list(input.collectionIds),localOnly:true};
    if(result.sourceIds)result.sourceIds=result.sourceIds.map(id=>registry.get(id).id);
    if(input.bufferMeters!=null)result.bufferMeters=Number(input.bufferMeters);
    if(input.boundary||input.bbox)normalizeBoundary(result);
    return result;
  };
  const page=(assets,input={})=>{const offset=Number(input.offset||input.token||0);const limit=Number(input.limit||100);
    if(!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1||limit>1000)throw new HttpError(400,'offset must be nonnegative and limit must be between 1 and 1000.');
    return {total:assets.length,offset,limit,nextOffset:offset+limit<assets.length?offset+limit:null,assets:assets.slice(offset,offset+limit)};};
  const queue=(type,request,response,payload=request.body)=>{const parsed=bodySchema.parse(payload||{});if(parsed.sourceIds)parsed.sourceIds=parsed.sourceIds.map(id=>registry.get(id).id);const job=jobs.enqueue(type,parsed);response.status(202).json({...job,statusUrl:`${base(request)}/api/jobs/${job.id}`});};
  const courseFor=id=>{const course=catalog.course(id);if(!course)throw new HttpError(404,'Course not found.');return course;};
  const terrainFor=(request,id)=>{
    const course=courseFor(id);const assets=catalog.queryAssets({courseId:id,localOnly:true,resolution:'all'}).sort((left,right)=>(left.sourceId==='derived'?0:1)-(right.sourceId==='derived'?0:1)||String(right.generatedAt||right.downloadedAt||'').localeCompare(String(left.generatedAt||left.downloadedAt||'')));
    const first=product=>assets.find(asset=>asset.product===product);const dem=first('dtm')||first('dem');const contours=assets.find(asset=>asset.product==='contours'&&asset.contourIntervalMeters===1)||first('contours');
    return {course,dem:dem?urlFor(request,dem):null,dtm:first('dtm')?urlFor(request,first('dtm')):null,dsm:first('dsm')?urlFor(request,first('dsm')):null,
      contours:contours?urlFor(request,contours):null,hillshade:first('hillshade')?urlFor(request,first('hillshade')):null,slope:first('slope')?urlFor(request,first('slope')):null,
      assets:assets.map(asset=>publicAsset(request,asset)),localOnly:true};
  };

  app.get('/api/settings',async(request,response)=>{const disk=await statfs(config.storageRoot).catch(()=>null);response.json({storageRoot:config.storageRoot,storageRoots:catalog.roots(),catalogPath:config.catalogPath,port:config.port,
