        const extracted = this.catalog.saveAsset({ ...asset, id: hash, remoteUrl: null, url: null, parentAssetId: asset.id, path: filename,
          bbox: extent, geometry: null, extension, title: path.basename(filename), product: /dsm|mns/i.test(filename) ? 'dsm' : /las|laz/.test(extension) ? 'point-cloud' : extension === 'geojson' ? 'contours' : asset.product,
