.pagination { min-height: 48px; display: flex; align-items: center; justify-content: space-between; gap: 12px; color: var(--muted); font-size: 11px; }
.pagination > div { display: flex; gap: 5px; }
.page-view { padding: 30px 32px 35px; min-height: calc(100dvh - 164px); background: var(--paper); }
.page-heading { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-bottom: 26px; }
.page-heading h2 { font-size: 25px; margin-top: 5px; }
.repository-stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); margin-bottom: 26px; padding: 18px 0; gap: 22px; }
.repository-stats > div { padding-left: 22px; border-left: 1px solid var(--line); min-width: 0; }
.repository-stats > div:first-child { border-left: 0; padding-left: 0; }
.repository-stats span { display: block; font-size: 10px; color: var(--muted); }
.repository-stats strong { display: block; font-weight: 500; font-size: 25px; margin-top: 4px; overflow-wrap: anywhere; }
.filter-bar { display: grid; grid-template-columns: minmax(140px, 1.3fr) repeat(4, minmax(110px, 1fr)) auto; gap: 12px; align-items: end; margin-bottom: 22px; }
.filter-bar .field { margin: 0; }
.badge { display: inline-flex; align-items: center; gap: 5px; border: 1px solid var(--line); padding: 3px 7px; border-radius: 3px; font-size: 10px; text-transform: capitalize; }
.badge.completed { background: var(--green-tint); color: var(--green); border-color: #cadfd5; }
.badge.failed, .badge.cancelled { color: var(--red); background: #f9eae9; border-color: #e7c8c5; }
.badge.running, .badge.queued { color: #8b6b21; background: var(--gold-tint); border-color: #ebdcae; }
progress { display: block; width: 145px; height: 5px; border: 0; border-radius: 2px; margin-top: 6px; accent-color: var(--green); background: var(--line); }
progress::-webkit-progress-bar { background: var(--line); border-radius: 2px; }
progress::-webkit-progress-value { background: var(--green); border-radius: 2px; }
.progress-label { font-size: 11px; max-width: 240px; overflow-wrap: anywhere; }
.footer { display: flex; align-items: center; justify-content: space-between; min-height: 34px; padding: 9px 26px; border-top: 1px solid var(--line); font-size: 10px; color: var(--muted); gap: 15px; }
.footer > span { display: flex; align-items: center; gap: 6px; }
.toast { position: fixed; bottom: 25px; left: 50%; transform: translateX(-50%); z-index: 1500; background: #253a32; color: white; padding: 13px 18px; border-radius: var(--radius); max-width: min(560px, calc(100% - 32px)); font-size: 12px; box-shadow: 0 5px 22px #18251f25; overflow-wrap: anywhere; }
.toast.error { background: #8d302c; }
dialog { width: min(580px, calc(100% - 28px)); max-height: calc(100dvh - 40px); padding: 24px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink); box-shadow: 0 15px 80px #1f322540; overflow: auto; }
dialog::backdrop { background: #172d2866; }
dialog.compact-dialog { width: min(440px, calc(100% - 28px)); }
dialog.asset-dialog { width: min(760px, calc(100% - 28px)); }
dialog.job-dialog { width: min(850px, calc(100% - 28px)); }
.dialog-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; margin-bottom: 23px; }
.dialog-heading h2 { font-size: 20px; overflow-wrap: anywhere; min-width: 0; }
.dialog-heading .icon-button { margin-top: -5px; }
.dialog-actions { justify-content: flex-end; padding-top: 19px; margin-top: 14px; border-top: 1px solid var(--line); }
.detail-list { display: grid; grid-template-columns: 150px minmax(0, 1fr); gap: 9px 14px; margin: 0 0 22px; font-size: 12px; }
.detail-list dt { color: var(--muted); }
.detail-list dd { margin: 0; overflow-wrap: anywhere; }
.tool-list { display: grid; gap: 8px; }
.tool-row { display: flex; justify-content: space-between; gap: 15px; font-size: 11px; padding: 7px 0; border-bottom: 1px solid var(--line); }
.tool-row > span { min-width: 0; overflow-wrap: anywhere; }
.tool-row strong { font-weight: 500; }
.folder-path { display: flex; gap: 7px; margin-bottom: 12px; }
.folder-path select { width: 75px; }
.folder-path input { flex: 1; }
.folder-parent { display: flex; align-items: center; gap: 14px; margin-bottom: 12px; }
.folder-list { height: 255px; overflow: auto; border: 1px solid var(--line); border-radius: var(--radius); }
.folder-item { display: flex; align-items: center; gap: 10px; padding: 11px 13px; width: 100%; text-align: left; background: white; border: 0; border-bottom: 1px solid var(--line); font-size: 12px; color: var(--ink); overflow-wrap: anywhere; }
.folder-item:hover { background: var(--green-tint); }
.folder-item svg { color: var(--muted); }
.error-text { color: var(--red); font-size: 11px; overflow-wrap: anywhere; }
.processing-checks { display: flex; flex-wrap: wrap; gap: 10px 20px; margin-bottom: 15px; }
.custom-interval input[type='number'] { width: 70px !important; }
.asset-preview { background: #edf0ec; margin-bottom: 20px; min-height: 180px; display: grid; place-items: center; border: 1px solid var(--line); border-radius: var(--radius); }
.asset-preview img { width: 100%; max-height: 360px; object-fit: contain; display: block; }
.asset-preview .metadata-note { padding: 18px; }
.json-output, .job-logs { white-space: pre-wrap; overflow-wrap: anywhere; font-size: 11px; background: #f1f4f2; border: 1px solid var(--line); padding: 15px; line-height: 1.7; }
.job-logs { min-height: 170px; max-height: 350px; overflow: auto; }
.job-error { color: var(--red); font-size: 12px; margin: 14px 0; overflow-wrap: anywhere; }
