import { area, bbox, bboxPolygon, booleanIntersects, buffer, feature, featureCollection } from '@turf/turf';

export class HttpError extends Error {
  constructor(status, message, details) {
    super(message);
    this.status = status;
    this.details = details;
  }
}

export function parseBbox(input) {
  const values = typeof input === 'string' ? input.split(',').map(Number)
    : Array.isArray(input) ? input.map(Number)
      : input && [input.minLng ?? input.west, input.minLat ?? input.south, input.maxLng ?? input.east, input.maxLat ?? input.north].map(Number);
  if (!values || values.length !== 4 || !values.every(Number.isFinite)) {
    throw new HttpError(400, 'bbox must contain west,south,east,north in WGS84 longitude/latitude.');
  }
  const [west, south, east, north] = values;
  if (west < -180 || east > 180 || south < -90 || north > 90 || west >= east || south >= north) {
    throw new HttpError(400, 'Invalid bbox. Split antimeridian-crossing requests into separate boundaries.');
  }
  return values;
}

export function normalizeBoundary(input, defaultBuffer = 0) {
  let boundary;
  if (input.boundary) {
    boundary = input.boundary.type === 'Feature' ? structuredClone(input.boundary) : feature(input.boundary);
    if (!['Polygon', 'MultiPolygon'].includes(boundary.geometry?.type)) {
      throw new HttpError(400, 'boundary must be a WGS84 GeoJSON Polygon or MultiPolygon.');
    }
    const rings = boundary.geometry.type === 'Polygon' ? boundary.geometry.coordinates : boundary.geometry.coordinates.flat();
    let points = 0;
    for (const ring of rings) {
      if (!Array.isArray(ring) || ring.length < 4 || JSON.stringify(ring[0]) !== JSON.stringify(ring.at(-1))) {
        throw new HttpError(400, 'GeoJSON polygon rings must be closed and contain at least four coordinates.');
      }
      for (const coordinate of ring) {
        if (!Array.isArray(coordinate) || coordinate.length < 2 || !coordinate.slice(0, 2).every(Number.isFinite)
          || Math.abs(coordinate[0]) > 180 || Math.abs(coordinate[1]) > 90) {
          throw new HttpError(400, 'GeoJSON coordinates must be numeric WGS84 longitude/latitude.');
        }
        if (++points > 100000) throw new HttpError(400, 'Boundary exceeds 100,000 coordinates.');
      }
    }
  } else {
    boundary = bboxPolygon(parseBbox(input.bbox));
  }
  const bufferMeters = Number(input.bufferMeters ?? defaultBuffer);
  if (!Number.isFinite(bufferMeters) || bufferMeters < 0 || bufferMeters > 10000) {
    throw new HttpError(400, 'bufferMeters must be between 0 and 10,000.');
  }
  const queryBoundary = bufferMeters ? buffer(boundary, bufferMeters, { units: 'meters' }) : boundary;
  const extent = parseBbox(bbox(queryBoundary));
  return { boundary, queryBoundary, bbox: extent, bufferMeters, areaKm2: area(queryBoundary) / 1000000 };
}

export function intersectsBoundary(asset, query) {
  if (!asset.bbox && !asset.geometry) return false;
  const geometry = asset.geometry ? feature(asset.geometry) : bboxPolygon(parseBbox(asset.bbox));
  return booleanIntersects(geometry, query.queryBoundary);
}

export function selectAssets(assets, query, options = {}) {
  const products = options.products?.length ? options.products : null;
  const filtered = assets.filter((asset) => intersectsBoundary(asset, query)
    && (!products || products.includes(asset.product))
    && (!options.formats?.length || options.formats.includes(asset.extension))
    && (!options.collectionIds?.length || options.collectionIds.includes(asset.collectionId)));
  const resolution = options.resolution ?? 'all';
  if (resolution === 'best') {
    const best = new Map();
    for (const asset of filtered) {
      const key = `${asset.sourceId}:${asset.product}`;
      if (asset.resolutionMeters > 0) best.set(key, Math.min(best.get(key) ?? Infinity, asset.resolutionMeters));
    }
    return filtered.filter((asset) => !asset.resolutionMeters || asset.resolutionMeters === best.get(`${asset.sourceId}:${asset.product}`));
  }
  if (resolution === 'all' || resolution === 'native') return filtered;
  const numeric = Number(resolution);
  if (!(numeric > 0) || !Number.isFinite(numeric)) throw new HttpError(400, 'resolution must be best, all, native, or a positive number in meters.');
  return filtered.filter((asset) => asset.resolutionMeters === numeric || asset.requestedResolutionMeters === numeric);
}

export function metricCrs(extent) {
  const [west, south, east, north] = parseBbox(extent);
  const longitude = (west + east) / 2;
  const latitude = (south + north) / 2;
  if (latitude < -80 || latitude > 84) return latitude >= 0 ? 'EPSG:3413' : 'EPSG:3031';
  const zone = Math.max(1, Math.min(60, Math.floor((longitude + 180) / 6) + 1));
  return `EPSG:${(latitude >= 0 ? 32600 : 32700) + zone}`;
}

export function assetsGeojson(assets) {
  return featureCollection(assets.filter((asset) => asset.geometry || asset.bbox).map((asset) => {
    const shape = asset.geometry ? feature(asset.geometry) : bboxPolygon(asset.bbox);
    shape.properties = { id: asset.id, sourceId: asset.sourceId, product: asset.product, resolutionMeters: asset.resolutionMeters, downloaded: asset.downloaded };
    return shape;
  }));
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { normalizeBoundary, parseBbox, selectAssets, metricCrs } from '../src/spatial.js';

test('accepts Scorecarder bbox objects and rejects invalid boundaries', () => {
  assert.deepEqual(parseBbox({ minLng: -79.5, minLat: 43.5, maxLng: -79.4, maxLat: 43.6 }), [-79.5, 43.5, -79.4, 43.6]);
  assert.throws(() => parseBbox('170,-10,-170,10'), /antimeridian/);
  assert.throws(() => parseBbox('0,0,0,1'), /Invalid bbox/);
  assert.throws(() => normalizeBoundary({ boundary: { type: 'Point', coordinates: [0, 0] } }), /Polygon/);
  assert.throws(() => normalizeBoundary({ bbox: [0, 0, 1, 1], bufferMeters: -1 }), /bufferMeters/);
});

test('polygon selection excludes tiles inside a boundary hole', () => {
  const query = normalizeBoundary({ boundary: { type: 'Polygon', coordinates: [
    [[0, 0], [3, 0], [3, 3], [0, 3], [0, 0]],
    [[1, 1], [1, 2], [2, 2], [2, 1], [1, 1]]
  ] } });
  const assets = [
    { id: 'outside', bbox: [4, 4, 5, 5] },
    { id: 'hole', bbox: [1.2, 1.2, 1.8, 1.8] },
    { id: 'hit', bbox: [0.2, 0.2, 0.8, 0.8] }
  ];
  assert.deepEqual(selectAssets(assets, query).map((asset) => asset.id), ['hit']);
});

test('best and all preserve source-native precision and unknown point-cloud density', () => {
  const query = normalizeBoundary({ bbox: [-80, 43, -79, 44] });
  const common = { bbox: [-79.8, 43.2, -79.2, 43.8], sourceId: 'ontario', product: 'dtm' };
  const assets = [
    { ...common, id: 'fine', resolutionMeters: 0.5 },
    { ...common, id: 'coarse', resolutionMeters: 1 },
    { ...common, id: 'cloud', product: 'point-cloud', resolutionMeters: null },
    { ...common, id: 'other', sourceId: 'nrcan', resolutionMeters: 2 }
  ];
  assert.deepEqual(selectAssets(assets, query, { resolution: 'best' }).map((asset) => asset.id), ['fine', 'cloud', 'other']);
  assert.equal(selectAssets(assets, query, { resolution: 'all' }).length, 4);
  assert.deepEqual(selectAssets(assets, query, { resolution: 0.5 }).map((asset) => asset.id), ['fine']);
  assert.throws(() => selectAssets(assets, query, { resolution: 'invalid' }), /resolution/);
});

test('meter buffers expand boundaries and processing uses local metric projections', () => {
  const original = [-79.5, 43.5, -79.4, 43.6];
  const query = normalizeBoundary({ bbox: original, bufferMeters: 500 });
  assert.ok(query.bbox[0] < original[0] && query.bbox[3] > original[3]);
  assert.ok(query.areaKm2 > 0);
  assert.equal(metricCrs(original), 'EPSG:32617');
  assert.equal(metricCrs([-65, 45, -62, 47]), 'EPSG:32620');
});

import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { normalizeBoundary, parseBbox, selectAssets, HttpError } from './spatial.js';
import { safeSegment } from './config.js';

const now = () => new Date().toISOString();
export const assetId = (sourceId, url, revision = '') => createHash('sha256').update(`${sourceId}\n${url}\n${revision}`).digest('hex').slice(0, 32);

export class Catalog {
  constructor(filename) {
    if (filename !== ':memory:') mkdirSync(path.dirname(filename), { recursive: true });
    this.db = new DatabaseSync(filename);
    this.db.exec(`
      PRAGMA journal_mode=WAL;
      PRAGMA foreign_keys=ON;
      PRAGMA busy_timeout=5000;
      CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, metadata TEXT NOT NULL, refreshed_at TEXT);
      CREATE TABLE IF NOT EXISTS storage_roots (path TEXT PRIMARY KEY, created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS courses (id TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL, province TEXT, latitude REAL, longitude REAL, metadata TEXT NOT NULL, updated_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS assets (
        rowid INTEGER PRIMARY KEY, id TEXT UNIQUE NOT NULL, source_id TEXT NOT NULL, product TEXT NOT NULL,
        resolution REAL, collection_id TEXT, remote_url TEXT, revision TEXT, path TEXT, bytes INTEGER DEFAULT 0,
        sha256 TEXT, status TEXT NOT NULL DEFAULT 'remote', metadata TEXT NOT NULL, created_at TEXT NOT NULL, downloaded_at TEXT
      );
      CREATE INDEX IF NOT EXISTS assets_source ON assets(source_id, product, status, resolution);
      CREATE INDEX IF NOT EXISTS assets_remote ON assets(remote_url);
      CREATE VIRTUAL TABLE IF NOT EXISTS asset_bounds USING rtree(rowid, west, east, south, north);
      CREATE TABLE IF NOT EXISTS course_assets (course_id TEXT NOT NULL REFERENCES courses(id), asset_id TEXT NOT NULL REFERENCES assets(id), PRIMARY KEY(course_id,asset_id));
      CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, type TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL, progress TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS job_events (id INTEGER PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), time TEXT NOT NULL, level TEXT NOT NULL, message TEXT NOT NULL);
      CREATE INDEX IF NOT EXISTS job_events_job ON job_events(job_id, id);
      CREATE TABLE IF NOT EXISTS discovery_plans (id TEXT PRIMARY KEY, metadata TEXT NOT NULL, created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS packages (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), metadata TEXT NOT NULL, created_at TEXT NOT NULL);
    `);
  }

  close() { this.db.close(); }

  registerRoot(root) {
    this.db.prepare('INSERT OR IGNORE INTO storage_roots VALUES (?,?)').run(path.resolve(root), now());
  }

  roots() { return this.db.prepare('SELECT path FROM storage_roots ORDER BY created_at').all().map((row) => row.path); }

  saveSource(source) {
    this.db.prepare('INSERT INTO sources VALUES (?,?,?) ON CONFLICT(id) DO UPDATE SET metadata=excluded.metadata,refreshed_at=excluded.refreshed_at')
      .run(source.id, JSON.stringify(source), source.refreshedAt || null);
  }

  sources() { return this.db.prepare('SELECT metadata FROM sources ORDER BY id').all().map((row) => JSON.parse(row.metadata)); }
  source(id) { const row = this.db.prepare('SELECT metadata FROM sources WHERE id=?').get(id); return row ? JSON.parse(row.metadata) : null; }

  saveAsset(input) {
    const asset = { ...input, id: input.id || assetId(input.sourceId, input.remoteUrl || input.url || input.path, input.revision) };
    const extent = parseBbox(asset.bbox);
    this.db.prepare(`INSERT INTO assets (id,source_id,product,resolution,collection_id,remote_url,revision,path,bytes,sha256,status,metadata,created_at,downloaded_at)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET metadata=excluded.metadata,
      resolution=excluded.resolution,collection_id=excluded.collection_id,
      path=COALESCE(excluded.path,assets.path),bytes=CASE WHEN excluded.path IS NOT NULL THEN excluded.bytes ELSE assets.bytes END,
      sha256=COALESCE(excluded.sha256,assets.sha256),status=CASE WHEN excluded.path IS NOT NULL THEN excluded.status ELSE assets.status END,
      downloaded_at=COALESCE(excluded.downloaded_at,assets.downloaded_at)`)
      .run(asset.id, asset.sourceId, asset.product, asset.resolutionMeters || null, asset.collectionId || null,
        asset.remoteUrl || asset.url || null, asset.revision || '', asset.path || null, asset.bytes || 0, asset.sha256 || null,
        asset.path ? 'ready' : 'remote', JSON.stringify(asset), now(), asset.path ? now() : null);
    const row = this.db.prepare('SELECT rowid FROM assets WHERE id=?').get(asset.id);
    this.db.prepare('INSERT OR REPLACE INTO asset_bounds VALUES (?,?,?,?,?)').run(row.rowid, extent[0], extent[2], extent[1], extent[3]);
    return this.asset(asset.id);
  }

  decodeAsset(row) {
    return row && { ...JSON.parse(row.metadata), id: row.id, sourceId: row.source_id, product: row.product,
      remoteUrl: row.remote_url, resolutionMeters: row.resolution, collectionId: row.collection_id,
      revision: row.revision, path: row.path, bytes: Number(row.bytes), sha256: row.sha256,
      downloaded: row.status === 'ready', status: row.status, downloadedAt: row.downloaded_at };
  }

  asset(id) { return this.decodeAsset(this.db.prepare('SELECT * FROM assets WHERE id=?').get(id)); }

  markDownloaded(id, result) {
    this.db.prepare('UPDATE assets SET path=?,bytes=?,sha256=?,status=?,downloaded_at=? WHERE id=?')
      .run(result.path, result.bytes, result.sha256, 'ready', now(), id);
    return this.asset(id);
  }

  queryAssets(input = {}) {
    const clauses = [];
    const parameters = [];
    let query;
    let join = '';
    if (input.bbox || input.boundary) {
      query = normalizeBoundary(input);
      join = ' JOIN asset_bounds bounds ON bounds.rowid=assets.rowid';
      clauses.push('bounds.west<=? AND bounds.east>=? AND bounds.south<=? AND bounds.north>=?');
      parameters.push(query.bbox[2], query.bbox[0], query.bbox[3], query.bbox[1]);
    }
    if (input.sourceIds?.length) {
      clauses.push(`source_id IN (${input.sourceIds.map(() => '?').join(',')})`);
      parameters.push(...input.sourceIds);
    }
    if (input.localOnly !== false) clauses.push("assets.status='ready'");
    if (input.courseId) {
      clauses.push('assets.id IN (SELECT asset_id FROM course_assets WHERE course_id=?)');
      parameters.push(input.courseId);
    }
    const rows = this.db.prepare(`SELECT assets.* FROM assets${join}${clauses.length ? ' WHERE ' + clauses.join(' AND ') : ''} ORDER BY assets.rowid`).all(...parameters);
    const assets = rows.map((row) => this.decodeAsset(row));
    const selection = query || { queryBoundary: { type: 'Feature', properties: {}, geometry: { type: 'Polygon', coordinates: [[[-180,-90],[180,-90],[180,90],[-180,90],[-180,-90]]] } } };
    return selectAssets(assets, selection, input);
  }

  saveCourse(input) {
    if (!input.name || typeof input.name !== 'string' || input.name.length > 300) throw new HttpError(400, 'Course name is required (maximum 300 characters).');
    if (!['CA', 'US'].includes(input.country)) throw new HttpError(400, 'country must be CA or US.');
    const id = safeSegment(input.id || input.name).toLowerCase();
    const existing = this.course(id);
    const query = normalizeBoundary(input.boundary || input.bbox ? input : existing || input);
    const latitude = (query.bbox[1] + query.bbox[3]) / 2;
    const longitude = (query.bbox[0] + query.bbox[2]) / 2;
    const course = { ...existing, ...input, id, boundary: query.boundary, bbox: query.bbox, latitude, longitude, bufferMeters: input.bufferMeters ?? existing?.bufferMeters ?? 500 };
    this.db.prepare('INSERT INTO courses VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,country=excluded.country,province=excluded.province,latitude=excluded.latitude,longitude=excluded.longitude,metadata=excluded.metadata,updated_at=excluded.updated_at')
      .run(id, input.name, input.country, input.province || input.region || null, latitude, longitude, JSON.stringify(course), now());
    return this.course(id);
  }

  course(id) {
    const row = this.db.prepare('SELECT metadata FROM courses WHERE id=?').get(id);
    if (!row) return null;
    const counts = this.db.prepare("SELECT COUNT(*) count FROM course_assets JOIN assets ON assets.id=asset_id WHERE course_id=? AND status='ready'").get(id);
    return { ...JSON.parse(row.metadata), downloaded: Number(counts.count) > 0, assetCount: Number(counts.count) };
  }

  courses(search = '') {
    const escaped = search.replaceAll('\\', '\\\\').replaceAll('%', '\\%').replaceAll('_', '\\_');
    return this.db.prepare("SELECT id FROM courses WHERE name LIKE ? ESCAPE '\\' OR id LIKE ? ESCAPE '\\' ORDER BY name")
      .all(`%${escaped}%`, `%${escaped}%`).map((row) => this.course(row.id));
  }

  linkAsset(courseId, id) {
    if (courseId) this.db.prepare('INSERT OR IGNORE INTO course_assets VALUES (?,?)').run(courseId, id);
  }

  savePlan(plan) {
    const id = randomUUID();
    this.db.prepare('INSERT INTO discovery_plans VALUES (?,?,?)').run(id, JSON.stringify(plan), now());
    return { ...plan, id };
  }

  plan(id) { const row = this.db.prepare('SELECT metadata FROM discovery_plans WHERE id=?').get(id); return row ? { ...JSON.parse(row.metadata), id } : null; }

  createJob(type, payload) {
    const id = randomUUID();
    const time = now();
    this.db.prepare('INSERT INTO jobs VALUES (?,?,?,?,?,?,?,?,?)').run(id, type, 'queued', JSON.stringify(payload), JSON.stringify({ completed: 0, total: 0, bytes: 0 }), null, time, time);
    return this.job(id);
  }

  job(id) {
    const row = this.db.prepare('SELECT * FROM jobs WHERE id=?').get(id);
    return row && { ...row, payload: JSON.parse(row.payload), progress: JSON.parse(row.progress), createdAt: row.created_at, updatedAt: row.updated_at };
  }

  jobs(limit = 100) { return this.db.prepare('SELECT id FROM jobs ORDER BY created_at DESC LIMIT ?').all(limit).map((row) => this.job(row.id)); }

  updateJob(id, changes) {
    const current = this.job(id);
    if (!current) throw new HttpError(404, 'Job not found.');
    this.db.prepare('UPDATE jobs SET status=?,progress=?,error=?,updated_at=? WHERE id=?')
      .run(changes.status ?? current.status, JSON.stringify(changes.progress ?? current.progress), changes.error ?? null, now(), id);
    return this.job(id);
  }

  event(id, message, level = 'info') {
    this.db.prepare('INSERT INTO job_events(job_id,time,level,message) VALUES (?,?,?,?)').run(id, now(), level, String(message).slice(0, 8000));
  }

  events(id, after = 0) { return this.db.prepare('SELECT * FROM job_events WHERE job_id=? AND id>? ORDER BY id LIMIT 1000').all(id, after); }

  stats() {
    const totals = this.db.prepare("SELECT COUNT(*) assets,COALESCE(SUM(bytes),0) bytes FROM assets WHERE status='ready'").get();
    return { assets: Number(totals.assets), bytes: Number(totals.bytes), courses: Number(this.db.prepare('SELECT COUNT(*) count FROM courses').get().count),
      remoteAssets: Number(this.db.prepare("SELECT COUNT(*) count FROM assets WHERE status='remote'").get().count),
      activeJobs: Number(this.db.prepare("SELECT COUNT(*) count FROM jobs WHERE status IN ('queued','running')").get().count) };
  }
}

import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { mkdir, readFile, writeFile, rename } from 'node:fs/promises';
import dotenv from 'dotenv';
import { HttpError } from './spatial.js';

export const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

export function loadConfig(overrides = {}) {
  dotenv.config({ path: path.join(projectRoot, '.env'), quiet: true });
  const number = (key, fallback, minimum = 1, maximum = Number.MAX_SAFE_INTEGER) => {
    const value = Number(process.env[key] || fallback);
    if (!Number.isFinite(value) || value < minimum || value > maximum) throw new Error(`Invalid ${key} in .env.`);
    return value;
  };
  const config = {
    host: process.env.HOST || '127.0.0.1',
    port: number('PORT', 3123, 1, 65535),
    storageRoot: path.resolve(process.env.STORAGE_ROOT || path.join(projectRoot, 'terrain-data')),
    catalogPath: path.resolve(process.env.CATALOG_PATH || path.join(projectRoot, 'data', 'catalog.sqlite')),
    downloadConcurrency: number('DOWNLOAD_CONCURRENCY', 2, 1, 16),
    downloadRetries: number('DOWNLOAD_RETRIES', 3, 0, 10),
    requestTimeoutMs: number('REQUEST_TIMEOUT_MS', 60000),
    downloadIdleTimeoutMs: number('DOWNLOAD_IDLE_TIMEOUT_MS', 120000),
    maxDiscoveryAssets: number('MAX_DISCOVERY_ASSETS', 100000),
    minFreeDiskGb: number('MIN_FREE_DISK_GB', 1, 0),
    defaultBufferMeters: number('DEFAULT_BUFFER_METERS', 500, 0, 10000),
    maxExportPixels: number('MAX_EXPORT_PIXELS', 4096, 64, 16384),
    maxProcessingPixels: number('MAX_PROCESSING_PIXELS', 100000000),
    updateCheckDays: number('UPDATE_CHECK_DAYS', 30, 0, 3650),
    apiKey: process.env.API_KEY || '',
    corsOrigins: (process.env.CORS_ORIGINS || 'http://localhost:3123,http://127.0.0.1:3123').split(',').map((value) => value.trim()).filter(Boolean),
    allowPrivateDownloadHosts: process.env.ALLOW_PRIVATE_DOWNLOAD_HOSTS === 'true',
    extraDownloadHosts: (process.env.DOWNLOAD_ALLOWED_HOSTS || '').split(',').map((value) => value.trim()).filter(Boolean),
    gisEnvRoot: process.env.GIS_ENV_ROOT || '',
    tools: {
      pdal: process.env.PDAL_BIN || 'pdal',
      gdalinfo: process.env.GDALINFO_BIN || 'gdalinfo',
      gdalwarp: process.env.GDALWARP_BIN || 'gdalwarp',
      gdal_translate: process.env.GDAL_TRANSLATE_BIN || 'gdal_translate',
      gdal_contour: process.env.GDAL_CONTOUR_BIN || 'gdal_contour',
      gdaldem: process.env.GDALDEM_BIN || 'gdaldem',
      ogr2ogr: process.env.OGR2OGR_BIN || 'ogr2ogr'
    },
    envPath: path.join(projectRoot, '.env'),
    ...overrides
  };
  if (!['localhost', '127.0.0.1', '::1'].includes(config.host) && !config.apiKey) {
    throw new Error('Set API_KEY before binding HOST to a non-loopback address.');
  }
  return config;
}

export async function persistStorageRoot(config, root) {
  if (typeof root !== 'string' || !root.trim() || !path.isAbsolute(root) || root.includes('\0')) {
    throw new HttpError(400, 'storageRoot must be an absolute filesystem path.');
  }
  const resolved = path.resolve(root);
  await mkdir(resolved, { recursive: true });
  const probe = path.join(resolved, `.terrainserver-write-${crypto.randomUUID()}`);
  await writeFile(probe, '');
  const { unlink } = await import('node:fs/promises');
  await unlink(probe);
  const original = await readFile(config.envPath, 'utf8').catch((error) => { if (error.code === 'ENOENT') return ''; throw error; });
  const values = dotenv.parse(original);
  values.STORAGE_ROOT = resolved.replaceAll('\\', '/');
  const content = Object.entries(values).map(([key, value]) => `${key}=${JSON.stringify(value)}`).join('\n') + '\n';
  const temporary = `${config.envPath}.tmp`;
  await writeFile(temporary, content, { mode: 0o600 });
  await rename(temporary, config.envPath);
  config.storageRoot = resolved;
  process.env.STORAGE_ROOT = resolved;
  return resolved;
}

export function safeSegment(value) {
  const segment = String(value || '').normalize('NFKD').replace(/[^a-zA-Z0-9_-]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 100);
  if (!segment) throw new HttpError(400, 'Identifier must contain letters or numbers.');
  return segment;
}

export function courseDirectory(root, course) {
  const country = course?.country === 'US' ? 'usa' : 'canada';
  return path.join(root, country, safeSegment(course?.province || course?.region || 'national').toLowerCase(), safeSegment(course?.id || '_repository'));
}

export function isContained(root, filename) {
  const relative = path.relative(path.resolve(root), path.resolve(filename));
  return relative !== '..' && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative);
}

import assert from 'node:assert/strict';
import test from 'node:test';
import path from 'node:path';
import os from 'node:os';
import { mkdtemp, rm, readFile, writeFile } from 'node:fs/promises';
import { Catalog } from '../src/catalog.js';
import { isContained, persistStorageRoot } from '../src/config.js';

test('SQLite catalog indexes local boundaries and keeps immutable source revisions', () => {
  const catalog = new Catalog(':memory:');
  try {
    const input = { sourceId: 'ontario', product: 'dtm', url: 'https://example.gov/a.tif', bbox: [-80, 43, -79, 44], resolutionMeters: 1 };
    const original = catalog.saveAsset(input);
    assert.equal(catalog.queryAssets({ bbox: [-79.5, 43.5, -79.4, 43.6] }).length, 0);
    catalog.markDownloaded(original.id, { path: path.resolve('test.tif'), bytes: 25000000000000, sha256: 'hash' });
    assert.equal(catalog.queryAssets({ bbox: [-79.5, 43.5, -79.4, 43.6] }).length, 1);
    assert.equal(catalog.queryAssets({ bbox: [-75, 43, -74, 44] }).length, 0);
    const rediscovered = catalog.saveAsset({ ...input, title: 'new metadata' });
    assert.equal(rediscovered.downloaded, true);
    const changed = catalog.saveAsset({ ...input, revision: 'v2' });
    assert.notEqual(changed.id, original.id);
    assert.equal(catalog.stats().bytes, 25000000000000);
  } finally { catalog.close(); }
});

test('courses, durable jobs, discovery plans, and asset links survive catalog operations', () => {
  const catalog = new Catalog(':memory:');
  try {
    const course = catalog.saveCourse({ id: 'heron-point', name: 'Heron Point', country: 'CA', province: 'ON', bbox: [-80, 43, -79, 44] });
    const asset = catalog.saveAsset({ sourceId: 'ontario', product: 'dtm', url: 'https://example.gov/a.tif', bbox: course.bbox, path: path.resolve('a.tif'), bytes: 123 });
    catalog.linkAsset(course.id, asset.id);
    assert.equal(catalog.courses('Heron')[0].assetCount, 1);
    assert.equal(catalog.courses('%').length, 0);
    const job = catalog.createJob('download', { assetIds: [asset.id] });
    catalog.updateJob(job.id, { status: 'running', progress: { completed: 1, total: 1, bytes: 123 } });
    catalog.event(job.id, 'Saved tile');
    assert.equal(catalog.job(job.id).status, 'running');
    assert.equal(catalog.events(job.id).length, 1);
    const plan = catalog.savePlan({ assetIds: [asset.id] });
    assert.deepEqual(catalog.plan(plan.id).assetIds, [asset.id]);
  } finally { catalog.close(); }
});

test('storage configuration persists in .env without removing unrelated settings', async () => {
  const directory = await mkdtemp(path.join(os.tmpdir(), 'terrain-config-'));
  try {
    const config = { envPath: path.join(directory, '.env') };
    await writeFile(config.envPath, 'PORT=3123\nAPI_KEY="example#value"\n');
    const root = path.join(directory, 'new storage');
    await persistStorageRoot(config, root);
    const text = await readFile(config.envPath, 'utf8');
    assert.match(text, /PORT="3123"/);
    assert.match(text, /API_KEY="example#value"/);
    assert.equal(config.storageRoot, root);
    assert.ok(isContained(root, path.join(root, 'a.tif')));
    assert.equal(isContained(root, path.join(root, '..', 'escape.tif')), false);
    await assert.rejects(persistStorageRoot(config, 'relative'), /absolute/);
  } finally { await rm(directory, { recursive: true, force: true }); }
});

import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { normalizeBoundary, parseBbox, selectAssets, HttpError } from './spatial.js';
import { safeSegment } from './config.js';

const now = () => new Date().toISOString();
export const assetId = (sourceId, url, revision = '') => createHash('sha256').update(`${sourceId}\n${url}\n${revision}`).digest('hex').slice(0, 32);

export class Catalog {
  constructor(filename) {
    if (filename !== ':memory:') mkdirSync(path.dirname(filename), { recursive: true });
    this.db = new DatabaseSync(filename);
    this.db.exec(`
      PRAGMA journal_mode=WAL;
      PRAGMA foreign_keys=ON;
      PRAGMA busy_timeout=5000;
      CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, metadata TEXT NOT NULL, refreshed_at TEXT);
      CREATE TABLE IF NOT EXISTS storage_roots (path TEXT PRIMARY KEY, created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS courses (id TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL, province TEXT, latitude REAL, longitude REAL, metadata TEXT NOT NULL, updated_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS assets (
        rowid INTEGER PRIMARY KEY, id TEXT UNIQUE NOT NULL, source_id TEXT NOT NULL, product TEXT NOT NULL,
        resolution REAL, collection_id TEXT, remote_url TEXT, revision TEXT, path TEXT, bytes INTEGER DEFAULT 0,
        sha256 TEXT, status TEXT NOT NULL DEFAULT 'remote', metadata TEXT NOT NULL, created_at TEXT NOT NULL, downloaded_at TEXT
      );
      CREATE INDEX IF NOT EXISTS assets_source ON assets(source_id, product, status, resolution);
      CREATE INDEX IF NOT EXISTS assets_remote ON assets(remote_url);
      CREATE VIRTUAL TABLE IF NOT EXISTS asset_bounds USING rtree(rowid, west, east, south, north);
      CREATE TABLE IF NOT EXISTS course_assets (course_id TEXT NOT NULL REFERENCES courses(id), asset_id TEXT NOT NULL REFERENCES assets(id), PRIMARY KEY(course_id,asset_id));
      CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, type TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL, progress TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS job_events (id INTEGER PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), time TEXT NOT NULL, level TEXT NOT NULL, message TEXT NOT NULL);
      CREATE INDEX IF NOT EXISTS job_events_job ON job_events(job_id, id);
      CREATE TABLE IF NOT EXISTS discovery_plans (id TEXT PRIMARY KEY, metadata TEXT NOT NULL, created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS packages (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), metadata TEXT NOT NULL, created_at TEXT NOT NULL);
    `);
  }

  close() { this.db.close(); }

  registerRoot(root) {
    this.db.prepare('INSERT OR IGNORE INTO storage_roots VALUES (?,?)').run(path.resolve(root), now());
  }

  roots() { return this.db.prepare('SELECT path FROM storage_roots ORDER BY created_at').all().map((row) => row.path); }

  saveSource(source) {
    this.db.prepare('INSERT INTO sources VALUES (?,?,?) ON CONFLICT(id) DO UPDATE SET metadata=excluded.metadata,refreshed_at=excluded.refreshed_at')
      .run(source.id, JSON.stringify(source), source.refreshedAt || null);
  }

  sources() { return this.db.prepare('SELECT metadata FROM sources ORDER BY id').all().map((row) => JSON.parse(row.metadata)); }
  source(id) { const row = this.db.prepare('SELECT metadata FROM sources WHERE id=?').get(id); return row ? JSON.parse(row.metadata) : null; }

  saveAsset(input) {
    const asset = { ...input, id: input.id || assetId(input.sourceId, input.remoteUrl || input.url || input.path, input.revision) };
    const extent = parseBbox(asset.bbox);
    this.db.prepare(`INSERT INTO assets (id,source_id,product,resolution,collection_id,remote_url,revision,path,bytes,sha256,status,metadata,created_at,downloaded_at)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET metadata=excluded.metadata,
      resolution=excluded.resolution,collection_id=excluded.collection_id,
      path=COALESCE(excluded.path,assets.path),bytes=CASE WHEN excluded.path IS NOT NULL THEN excluded.bytes ELSE assets.bytes END,
      sha256=COALESCE(excluded.sha256,assets.sha256),status=CASE WHEN excluded.path IS NOT NULL THEN excluded.status ELSE assets.status END,
      downloaded_at=COALESCE(excluded.downloaded_at,assets.downloaded_at)`)
      .run(asset.id, asset.sourceId, asset.product, asset.resolutionMeters || null, asset.collectionId || null,
        asset.remoteUrl || asset.url || null, asset.revision || '', asset.path || null, asset.bytes || 0, asset.sha256 || null,
        asset.path ? 'ready' : 'remote', JSON.stringify(asset), now(), asset.path ? now() : null);
    const row = this.db.prepare('SELECT rowid FROM assets WHERE id=?').get(asset.id);
    this.db.prepare('INSERT OR REPLACE INTO asset_bounds VALUES (?,?,?,?,?)').run(row.rowid, extent[0], extent[2], extent[1], extent[3]);
    return this.asset(asset.id);
  }

  decodeAsset(row) {
    return row && { ...JSON.parse(row.metadata), id: row.id, sourceId: row.source_id, product: row.product,
      remoteUrl: row.remote_url, resolutionMeters: row.resolution, collectionId: row.collection_id,
      revision: row.revision, path: row.path, bytes: Number(row.bytes), sha256: row.sha256,
      downloaded: row.status === 'ready', status: row.status, downloadedAt: row.downloaded_at };
  }

  asset(id) { return this.decodeAsset(this.db.prepare('SELECT * FROM assets WHERE id=?').get(id)); }

  markDownloaded(id, result) {
    this.db.prepare('UPDATE assets SET path=?,bytes=?,sha256=?,status=?,downloaded_at=? WHERE id=?')
      .run(result.path, result.bytes, result.sha256, 'ready', now(), id);
    return this.asset(id);
  }

  queryAssets(input = {}) {
    const clauses = [];
    const parameters = [];
    let query;
    let join = '';
    if (input.bbox || input.boundary) {
      query = normalizeBoundary(input);
      join = ' JOIN asset_bounds bounds ON bounds.rowid=assets.rowid';
      clauses.push('bounds.west<=? AND bounds.east>=? AND bounds.south<=? AND bounds.north>=?');
      parameters.push(query.bbox[2], query.bbox[0], query.bbox[3], query.bbox[1]);
    }
    if (input.sourceIds?.length) {
      clauses.push(`source_id IN (${input.sourceIds.map(() => '?').join(',')})`);
      parameters.push(...input.sourceIds);
    }
    if (input.localOnly !== false) clauses.push("assets.status='ready'");
    if (input.courseId) {
      clauses.push('assets.id IN (SELECT asset_id FROM course_assets WHERE course_id=?)');
      parameters.push(input.courseId);
    }
    const rows = this.db.prepare(`SELECT assets.* FROM assets${join}${clauses.length ? ' WHERE ' + clauses.join(' AND ') : ''} ORDER BY assets.rowid`).all(...parameters);
    const assets = rows.map((row) => this.decodeAsset(row));
    const selection = query || { queryBoundary: { type: 'Feature', properties: {}, geometry: { type: 'Polygon', coordinates: [[[-180,-90],[180,-90],[180,90],[-180,90],[-180,-90]]] } } };
    return selectAssets(assets, selection, input);
  }

  saveCourse(input) {
    if (!input.name || typeof input.name !== 'string' || input.name.length > 300) throw new HttpError(400, 'Course name is required (maximum 300 characters).');
    if (!['CA', 'US'].includes(input.country)) throw new HttpError(400, 'country must be CA or US.');
    const id = safeSegment(input.id || input.name).toLowerCase();
    const existing = this.course(id);
    const query = normalizeBoundary(input.boundary || input.bbox ? input : existing || input);
    const latitude = (query.bbox[1] + query.bbox[3]) / 2;
    const longitude = (query.bbox[0] + query.bbox[2]) / 2;
    const course = { ...existing, ...input, id, boundary: query.boundary, bbox: query.bbox, latitude, longitude, bufferMeters: input.bufferMeters ?? existing?.bufferMeters ?? 500 };
    this.db.prepare('INSERT INTO courses VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,country=excluded.country,province=excluded.province,latitude=excluded.latitude,longitude=excluded.longitude,metadata=excluded.metadata,updated_at=excluded.updated_at')
      .run(id, input.name, input.country, input.province || input.region || null, latitude, longitude, JSON.stringify(course), now());
    return this.course(id);
  }

  course(id) {
    const row = this.db.prepare('SELECT metadata FROM courses WHERE id=?').get(id);
    if (!row) return null;
    const counts = this.db.prepare("SELECT COUNT(*) count FROM course_assets JOIN assets ON assets.id=asset_id WHERE course_id=? AND status='ready'").get(id);
    return { ...JSON.parse(row.metadata), downloaded: Number(counts.count) > 0, assetCount: Number(counts.count) };
  }

  courses(search = '') {
    const escaped = search.replaceAll('\\', '\\\\').replaceAll('%', '\\%').replaceAll('_', '\\_');
    return this.db.prepare("SELECT id FROM courses WHERE name LIKE ? ESCAPE '\\' OR id LIKE ? ESCAPE '\\' ORDER BY name")
      .all(`%${escaped}%`, `%${escaped}%`).map((row) => this.course(row.id));
  }

  linkAsset(courseId, id) {
    if (courseId) this.db.prepare('INSERT OR IGNORE INTO course_assets VALUES (?,?)').run(courseId, id);
  }

  savePlan(plan) {
    const id = randomUUID();
    this.db.prepare('INSERT INTO discovery_plans VALUES (?,?,?)').run(id, JSON.stringify(plan), now());
    return { ...plan, id };
  }

  plan(id) { const row = this.db.prepare('SELECT metadata FROM discovery_plans WHERE id=?').get(id); return row ? { ...JSON.parse(row.metadata), id } : null; }

  createJob(type, payload) {
    const id = randomUUID();
    const time = now();
    this.db.prepare('INSERT INTO jobs VALUES (?,?,?,?,?,?,?,?)').run(id, type, 'queued', JSON.stringify(payload), JSON.stringify({ completed: 0, total: 0, bytes: 0 }), null, time, time);
    return this.job(id);
  }

  job(id) {
    const row = this.db.prepare('SELECT * FROM jobs WHERE id=?').get(id);
    return row && { ...row, payload: JSON.parse(row.payload), progress: JSON.parse(row.progress), createdAt: row.created_at, updatedAt: row.updated_at };
  }

  jobs(limit = 100) { return this.db.prepare('SELECT id FROM jobs ORDER BY created_at DESC LIMIT ?').all(limit).map((row) => this.job(row.id)); }

  updateJob(id, changes) {
    const current = this.job(id);
    if (!current) throw new HttpError(404, 'Job not found.');
    this.db.prepare('UPDATE jobs SET status=?,progress=?,error=?,updated_at=? WHERE id=?')
      .run(changes.status ?? current.status, JSON.stringify(changes.progress ?? current.progress), changes.error ?? null, now(), id);
    return this.job(id);
  }

  event(id, message, level = 'info') {
    this.db.prepare('INSERT INTO job_events(job_id,time,level,message) VALUES (?,?,?,?)').run(id, now(), level, String(message).slice(0, 8000));
  }

  events(id, after = 0) { return this.db.prepare('SELECT * FROM job_events WHERE job_id=? AND id>? ORDER BY id LIMIT 1000').all(id, after); }

  stats() {
    const totals = this.db.prepare("SELECT COUNT(*) assets,COALESCE(SUM(bytes),0) bytes FROM assets WHERE status='ready'").get();
    return { assets: Number(totals.assets), bytes: Number(totals.bytes), courses: Number(this.db.prepare('SELECT COUNT(*) count FROM courses').get().count),
      remoteAssets: Number(this.db.prepare("SELECT COUNT(*) count FROM assets WHERE status='remote'").get().count),
      activeJobs: Number(this.db.prepare("SELECT COUNT(*) count FROM jobs WHERE status IN ('queued','running')").get().count) };
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { mkdtemp, writeFile, readFile, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { Network, publicAddress } from '../src/network.js';

test('download security rejects private hosts, credentials, and unsupported protocols', () => {
  const network = new Network({ allowPrivateDownloadHosts: false, extraDownloadHosts: [] });
  try {
    assert.throws(() => network.validateUrl('http://127.0.0.1/file'), /Private/);
    assert.throws(() => network.validateUrl('https://user:password@example.gov/file'), /credentials/);
    assert.throws(() => network.validateUrl('file:///C:/Windows/test'), /HTTP/);
    assert.throws(() => network.validateUrl('https://untrusted.example/file'), /not allowed/);
    assert.equal(publicAddress('::ffff:127.0.0.1'), false);
    assert.equal(publicAddress('169.254.169.254'), false);
    assert.equal(publicAddress('8.8.8.8'), true);
  } finally { network.close(); }
});

test('streams downloads, resumes with If-Range, checks signatures, and never overwrites raw data', async () => {
  const content = Buffer.concat([Buffer.from([73,73,42,0,8,0,0,0]), Buffer.alloc(65536, 7)]);
  let rangeSeen;
  const server = createServer((request, response) => {
    if (request.url === '/redirect') { response.writeHead(302, { Location: '/tile.tif' }); response.end(); return; }
    if (request.url === '/html') { response.writeHead(200, { 'Content-Type': 'text/html' }); response.end('<html>Error</html>'); return; }
    const offset = Number(/^bytes=(\d+)-$/.exec(request.headers.range || '')?.[1] || 0);
    if (offset) rangeSeen = { offset, validator: request.headers['if-range'] };
    response.writeHead(offset ? 206 : 200, { 'Content-Type': 'image/tiff', ETag: '"v1"', 'Content-Length': content.length - offset,
      ...(offset ? { 'Content-Range': `bytes ${offset}-${content.length - 1}/${content.length}` } : {}) });
    response.end(content.subarray(offset));
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const root = await mkdtemp(path.join(os.tmpdir(), 'terrain-download-'));
  const network = new Network({ allowPrivateDownloadHosts: true, downloadRetries: 0, requestTimeoutMs: 5000, downloadIdleTimeoutMs: 5000, minFreeDiskGb: 0 });
  const url = `http://127.0.0.1:${server.address().port}/tile.tif`;
  try {
    const destination = path.join(root, 'tile.tif');
    await writeFile(`${destination}.part`, content.subarray(0, 1024));
    await writeFile(`${destination}.part.json`, JSON.stringify({ url, etag: '"v1"' }));
    const result = await network.download(url, destination, { extension: 'tif' });
    assert.deepEqual(rangeSeen, { offset: 1024, validator: '"v1"' });
    assert.equal(result.bytes, content.length);
    assert.equal(result.sha256, createHash('sha256').update(content).digest('hex'));
    assert.deepEqual(await readFile(destination), content);
    assert.equal((await network.download(url, destination)).reused, true);
    const redirect = await network.download(url.replace('/tile.tif', '/redirect'), path.join(root, 'redirect.tif'), { extension: 'tif' });
    assert.equal(redirect.bytes, content.length);
    await assert.rejects(network.download(url.replace('/tile.tif', '/html'), path.join(root, 'bad.tif'), { extension: 'tif' }), /HTML/);
  } finally { await network.close(); await new Promise((resolve) => server.close(resolve)); await rm(root, { recursive: true, force: true }); }
});

import { lookup } from 'node:dns';
import { createReadStream, createWriteStream, constants } from 'node:fs';
import { stat, mkdir, readFile, writeFile, unlink, link, copyFile, open, statfs } from 'node:fs/promises';
import path from 'node:path';
import { Readable, Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { createHash } from 'node:crypto';
import { setTimeout as delay } from 'node:timers/promises';
import ipaddr from 'ipaddr.js';
import { Agent, fetch } from 'undici';
import { HttpError } from './spatial.js';

const governmentDomains = ['gov', 'gc.ca', 'canada.ca', 'geo.ca', 'ontario.ca', 'gov.on.ca', 'arcgis.com', 'amazonaws.com',
  'gov.bc.ca', 'gouv.qc.ca', 'donneesquebec.ca', 'novascotia.ca', 'alberta.ca', 'saskatchewan.ca', 'gov.sk.ca',
  'princeedwardisland.ca', 'gov.pe.ca', 'open.canada.ca', 'data.gov.bc.ca', 'snb.ca'];

export function publicAddress(address) {
  try {
    const parsed = ipaddr.process(address);
    return parsed.range() === 'unicast';
  } catch { return false; }
}

export async function fileHash(filename) {
  const hash = createHash('sha256');
  for await (const chunk of createReadStream(filename)) hash.update(chunk);
  return hash.digest('hex');
}

export async function publishFile(temporary, destination) {
  try { await link(temporary, destination); }
  catch (error) {
    if (error.code === 'EEXIST') throw new HttpError(409, 'Refusing to overwrite an existing raw source file.');
    if (!['EPERM', 'EOPNOTSUPP', 'ENOTSUP', 'EXDEV', 'ENOSYS'].includes(error.code)) throw error;
    await copyFile(temporary, destination, constants.COPYFILE_EXCL);
  }
  await unlink(temporary);
}

export class Network {
  constructor(config) {
    this.config = config;
    this.agent = new Agent({ connect: { lookup: (hostname, options, callback) => {
      lookup(hostname, { ...options, all: true }, (error, records) => {
        if (error) return callback(error);
        const allowed = records.filter((record) => config.allowPrivateDownloadHosts || publicAddress(record.address));
        if (!allowed.length) return callback(new Error('Download hostname resolves to a private or reserved address.'));
        if (options.all) callback(null, allowed);
        else callback(null, allowed[0].address, allowed[0].family);
      });
    } } });
  }

  validateUrl(input) {
    let url;
    try { url = new URL(input); } catch { throw new HttpError(400, 'Invalid download URL.'); }
    if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) {
      throw new HttpError(400, 'Only HTTP(S) URLs without embedded credentials are supported.');
    }
    const host = url.hostname.replace(/^\[|\]$/g, '').toLowerCase();
    if (!this.config.allowPrivateDownloadHosts) {
      if (ipaddr.isValid(host) && !publicAddress(host)) throw new HttpError(400, 'Private and reserved download addresses are blocked.');
      const domains = [...governmentDomains, ...(this.config.extraDownloadHosts || [])];
      if (!domains.some((domain) => host === domain || host.endsWith(`.${domain}`))) {
        throw new HttpError(400, `Download host ${host} is not allowed. Configure DOWNLOAD_ALLOWED_HOSTS in .env for a trusted public provider.`);
      }
      if (url.port && !['80', '443'].includes(url.port)) throw new HttpError(400, 'Nonstandard provider ports are blocked.');
    }
    return url;
  }

  async response(input, options = {}) {
    let url = this.validateUrl(input);
    const signals = [options.signal].filter(Boolean);
    const timeoutMs = options.timeoutMs ?? this.config.requestTimeoutMs;
    if (timeoutMs) signals.push(AbortSignal.timeout(timeoutMs));
    const signal = signals.length ? AbortSignal.any(signals) : undefined;
    for (let redirects = 0; redirects <= 5; redirects++) {
      const response = await fetch(url, { ...options, signal, dispatcher: this.agent, redirect: 'manual',
        headers: { 'User-Agent': 'TerrainServer/1.0 government-terrain-offline-cache', ...options.headers } });
      if ([301, 302, 303, 307, 308].includes(response.status)) {
        const location = response.headers.get('location');
        await response.body?.cancel();
        if (!location) throw new HttpError(502, 'Provider returned a redirect without a location.');
        url = this.validateUrl(new URL(location, url).href);
        if (response.status === 303) options = { ...options, method: 'GET', body: undefined };
        continue;
      }
      return response;
    }
    throw new HttpError(502, 'Provider exceeded five redirects.');
  }

  async json(url, options = {}) {
    const response = await this.response(url, options);
    if (!response.ok) { await response.body?.cancel(); throw new HttpError(502, `Provider returned HTTP ${response.status}.`, { url: String(url) }); }
    const body = await response.json();
    if (body.error) throw new HttpError(502, body.error.message || body.error.description || 'Provider returned an error.', body.error);
    return body;
  }

  async text(url, options = {}) {
    const response = await this.response(url, options);
    if (!response.ok) { await response.body?.cancel(); throw new HttpError(502, `Provider returned HTTP ${response.status}.`); }
    return response.text();
  }

  async download(url, destination, options = {}) {
    this.validateUrl(url);
    await mkdir(path.dirname(destination), { recursive: true });
    const existing = await stat(destination).catch((error) => { if (error.code === 'ENOENT') return null; throw error; });
    if (existing) return { path: destination, bytes: existing.size, sha256: await fileHash(destination), reused: true };
    for (let attempt = 0; attempt <= this.config.downloadRetries; attempt++) {
      options.signal?.throwIfAborted();
      try { return await this.downloadAttempt(url, destination, options); }
      catch (error) {
        if (options.signal?.aborted || attempt >= this.config.downloadRetries || error.status === 400 || error.status === 409) throw error;
        options.onRetry?.(attempt + 1, error);
        await delay(Math.min(1000 * 2 ** attempt, 8000), undefined, { signal: options.signal });
      }
    }
  }

  async downloadAttempt(url, destination, options) {
    const partial = `${destination}.part`;
    const metadataFile = `${partial}.json`;
    const previous = await readFile(metadataFile, 'utf8').then(JSON.parse).catch((error) => { if (error.code === 'ENOENT' || error instanceof SyntaxError) return null; throw error; });
    let offset = previous?.url === String(url) && (previous.etag || previous.lastModified)
      ? await stat(partial).then((info) => info.size).catch((error) => { if (error.code === 'ENOENT') return 0; throw error; }) : 0;
    const controller = new AbortController();
    const signal = options.signal ? AbortSignal.any([options.signal, controller.signal]) : controller.signal;
    let timer;
    const touch = () => { clearTimeout(timer); timer = setTimeout(() => controller.abort(new Error('Download stalled: idle timeout.')), this.config.downloadIdleTimeoutMs); timer.unref?.(); };
    touch();
    try {
      const headers = offset ? { Range: `bytes=${offset}-`, 'If-Range': previous.etag || previous.lastModified } : {};
      let response = await this.response(url, { signal, timeoutMs: 0, headers });
      if (response.status === 416) {
        await response.body?.cancel();
        offset = 0;
        response = await this.response(url, { signal, timeoutMs: 0 });
      }
      if (!response.ok) { await response.body?.cancel(); throw new HttpError(502, `Download returned HTTP ${response.status}.`); }
      const contentType = response.headers.get('content-type') || '';
      if (/text\/html|application\/(?:problem\+)?json/i.test(contentType) && options.extension !== 'geojson') {
        await response.body?.cancel();
        throw new HttpError(502, 'Provider returned HTML/JSON instead of a terrain file. There may be no coverage for this area.');
      }
      if (response.status === 206) {
        const range = /^bytes (\d+)-(\d+)\/(\d+)$/.exec(response.headers.get('content-range') || '');
        if (!range || Number(range[1]) !== offset) { await response.body?.cancel(); throw new HttpError(502, 'Provider returned an invalid Content-Range.'); }
      } else { offset = 0; }
      const length = Number(response.headers.get('content-length')) || 0;
      const total = length ? length + offset : options.expectedBytes || null;
      const hash = createHash('sha256');
      if (offset) for await (const chunk of createReadStream(partial)) { signal.throwIfAborted(); hash.update(chunk); touch(); }
      await writeFile(metadataFile, JSON.stringify({ url: String(url), etag: response.headers.get('etag'), lastModified: response.headers.get('last-modified'), total }));
      let bytes = offset;
      let lastDiskCheck = 0;
      const measure = new Transform({ transform: (chunk, encoding, callback) => {
        bytes += chunk.length;
        hash.update(chunk);
        touch();
        options.onProgress?.({ bytes, total, resumedBytes: offset });
        if (options.diskRoot && bytes - lastDiskCheck > 64 * 1024 * 1024) {
          lastDiskCheck = bytes;
          statfs(options.diskRoot).then((info) => {
            if (Number(info.bavail) * Number(info.bsize) < this.config.minFreeDiskGb * 1024 ** 3) {
              callback(new HttpError(507, 'Storage reserve reached; partial download is retained for resume.'));
            } else callback(null, chunk);
          }, callback);
        } else callback(null, chunk);
      } });
      await pipeline(Readable.fromWeb(response.body), measure, createWriteStream(partial, { flags: offset ? 'a' : 'w' }), { signal });
      if (total && bytes !== total) throw new HttpError(502, `Incomplete download: expected ${total} bytes, received ${bytes}.`);
      if (options.expectedBytes && bytes !== options.expectedBytes) throw new HttpError(502, 'Downloaded size differs from provider metadata.');
      const sha256 = hash.digest('hex');
      if (options.sha256 && sha256 !== options.sha256) throw new HttpError(502, 'Provider checksum verification failed.');
      await verifySignature(partial, options.extension);
      await publishFile(partial, destination);
      await unlink(metadataFile).catch((error) => { if (error.code !== 'ENOENT') throw error; });
      return { path: destination, bytes, sha256, resumedBytes: offset, etag: response.headers.get('etag'), lastModified: response.headers.get('last-modified') };
    } finally { clearTimeout(timer); controller.abort(); }
  }

  async close() { await this.agent.close(); }
}

async function verifySignature(filename, extension) {
  if (!extension) return;
  const handle = await open(filename, 'r');
  try {
    const bytes = Buffer.alloc(8);
    await handle.read(bytes, 0, 8, 0);
    const tiff = (bytes[0] === 73 && bytes[1] === 73 && [42, 43].includes(bytes[2])) || (bytes[0] === 77 && bytes[1] === 77 && [42, 43].includes(bytes[3]));
    if (['tif', 'tiff'].includes(extension) && !tiff) throw new HttpError(502, 'Download does not have a valid TIFF/BigTIFF signature.');
    if (['las', 'laz', 'copc.laz'].includes(extension) && bytes.subarray(0, 4).toString() !== 'LASF') throw new HttpError(502, 'Download does not have a LAS/LAZ signature.');
    if (extension === 'zip' && bytes.subarray(0, 2).toString() !== 'PK') throw new HttpError(502, 'Download does not have a ZIP signature.');
  } finally { await handle.close(); }
}

import { spawn } from 'node:child_process';
import path from 'node:path';
import proj4 from 'proj4';
import { HttpError, parseBbox, metricCrs } from './spatial.js';

proj4.defs('EPSG:3413', '+proj=stere +lat_0=90 +lat_ts=70 +lon_0=-45 +datum=WGS84 +units=m +no_defs');
proj4.defs('EPSG:3031', '+proj=stere +lat_0=-90 +lat_ts=-71 +lon_0=0 +datum=WGS84 +units=m +no_defs');
for (let zone = 1; zone <= 60; zone++) {
  proj4.defs(`EPSG:${32600 + zone}`, `+proj=utm +zone=${zone} +datum=WGS84 +units=m +no_defs`);
  proj4.defs(`EPSG:${32700 + zone}`, `+proj=utm +zone=${zone} +south +datum=WGS84 +units=m +no_defs`);
}

export function projectExtent(extent, target = metricCrs(extent)) {
  const [west, south, east, north] = parseBbox(extent);
  const points = [];
  for (let step = 0; step <= 16; step++) {
    const fraction = step / 16;
    points.push(proj4('EPSG:4326', target, [west + (east - west) * fraction, south]),
      proj4('EPSG:4326', target, [west + (east - west) * fraction, north]),
      proj4('EPSG:4326', target, [west, south + (north - south) * fraction]),
      proj4('EPSG:4326', target, [east, south + (north - south) * fraction]));
  }
  return { crs: target, bbox: [Math.min(...points.map((point) => point[0])), Math.min(...points.map((point) => point[1])), Math.max(...points.map((point) => point[0])), Math.max(...points.map((point) => point[1]))] };
}

export function geographicExtent(extent, crs) {
  const [west, south, east, north] = extent;
  const points = [[west, south], [east, south], [east, north], [west, north]].map((point) => proj4(crs, 'EPSG:4326', point));
  return [Math.min(...points.map((point) => point[0])), Math.min(...points.map((point) => point[1])), Math.max(...points.map((point) => point[0])), Math.max(...points.map((point) => point[1]))];
}

export class Gis {
  constructor(config) { this.config = config; }

  environment() {
    const root = this.config.gisEnvRoot;
    if (!root) return process.env;
    return { ...process.env, PATH: [path.join(root, 'Library', 'bin'), path.join(root, 'bin'), root, process.env.PATH].join(path.delimiter),
      GDAL_DATA: path.join(root, 'Library', 'share', 'gdal'), PROJ_DATA: path.join(root, 'Library', 'share', 'proj'),
      PROJ_LIB: path.join(root, 'Library', 'share', 'proj'), GDAL_NUM_THREADS: '2', GDAL_CACHEMAX: '256' };
  }

  run(tool, args, options = {}) {
    const executable = this.config.tools[tool];
    if (!executable) throw new HttpError(503, `${tool} is not configured in .env.`);
    options.signal?.throwIfAborted();
    return new Promise((resolve, reject) => {
      const child = spawn(executable, args.map(String), { env: this.environment(), cwd: options.cwd, windowsHide: true, shell: false });
      let stdout = '';
      let stderr = '';
      let settled = false;
      const finish = (error, result) => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        options.signal?.removeEventListener('abort', cancel);
        if (error) reject(error); else resolve(result);
      };
      const cancel = () => { child.kill(); finish(options.signal?.reason || new Error('Processing cancelled.')); };
      options.signal?.addEventListener('abort', cancel, { once: true });
      const timer = setTimeout(() => { child.kill(); finish(new HttpError(504, `${tool} exceeded its processing time limit.`)); }, options.timeoutMs || 6 * 60 * 60 * 1000);
      timer.unref?.();
      child.stdout.on('data', (chunk) => {
        stdout += chunk.toString();
        options.onOutput?.(chunk.toString());
        if (stdout.length > (options.maxOutputBytes || 64 * 1024 * 1024)) { child.kill(); finish(new HttpError(413, 'GIS output exceeded its limit; refine the query boundary.')); }
      });
      child.stderr.on('data', (chunk) => { stderr = (stderr + chunk.toString()).slice(-16000); options.onOutput?.(chunk.toString()); });
      child.on('error', (error) => finish(new HttpError(503, `${tool} could not run: ${error.message}. Check its .env path and GIS_ENV_ROOT.`)));
      child.on('close', (code) => finish(code === 0 ? null : new HttpError(502, `${tool} exited with code ${code}: ${stderr.slice(-4000)}`), { stdout, stderr, code }));
    });
  }

  async check() {
    const tools = await Promise.all(Object.keys(this.config.tools).map(async (name) => {
      try { const result = await this.run(name, ['--version'], { timeoutMs: 20000, maxOutputBytes: 100000 });
        return { name, executable: this.config.tools[name], available: true, version: (result.stdout || result.stderr).trim().split(/\r?\n/).find((line) => /\b(?:GDAL|pdal)\s+[\d.]/i.test(line)) || 'Available' };
      } catch (error) { return { name, executable: this.config.tools[name], available: false, error: error.message }; }
    }));
    return { tools, rasterReady: tools.filter((tool) => tool.name !== 'pdal' && tool.name !== 'ogr2ogr').every((tool) => tool.available),
      pointCloudReady: tools.every((tool) => tool.available), vectorIndexReady: tools.find((tool) => tool.name === 'ogr2ogr')?.available };
  }
}

