  app.use('/api',(request,response,next)=>{
    if(!config.apiKey||request.method==='OPTIONS'||/^\/downloads\/[a-f0-9]{48}\//.test(request.path))return next();
    const supplied=(request.get('authorization')||'').replace(/^Bearer\s+/i,'');const expected=Buffer.from(config.apiKey);const actual=Buffer.from(supplied);
    if(actual.length!==expected.length||!timingSafeEqual(actual,expected))return next(new HttpError(401,'API key required. Send Authorization: Bearer <API_KEY>.'));next();
  });
  const base=request=>`${request.protocol}://${request.get('host')}`;
  const urlFor=(request,asset)=>`${base(request)}/api/assets/${asset.id}/download.${asset.extension||'bin'}`;
  const publicAsset=(request,asset)=>{
    if(!asset)return null;const {path:filename,...data}=asset;
    return {...data,url:asset.downloaded?urlFor(request,asset):null,downloadUrl:asset.downloaded?urlFor(request,asset):null,source:asset.sourceId,
      bounds:asset.bbox,bbox:{minLng:asset.bbox[0],minLat:asset.bbox[1],maxLng:asset.bbox[2],maxLat:asset.bbox[3]},cellSizeMeters:asset.effectiveCellSizeMeters||asset.resolutionMeters,
      previewUrl:asset.downloaded&&['tif','tiff'].includes(asset.extension)?`${base(request)}/api/assets/${asset.id}/preview.png`:null};
  };
  const optionsFor=request=>{
    const input=request.method==='GET'?request.query:request.body;const result={...input,sourceIds:list(input.sourceIds||input.sources),products:list(input.products),formats:list(input.formats),collectionIds:list(input.collectionIds),localOnly:true};
