import path from 'node:path';

let count=0;
for(const directory of ['src','public','scripts','tests'])for(const entry of await readdir(directory,{withFileTypes:true})) {
  if(!entry.isFile()||!entry.name.endsWith('.js'))continue;
  const filename=path.join(directory,entry.name);const result=spawnSync(process.execPath,['--check',filename],{encoding:'utf8'});
