}
function run(action,preventDefault=true) { return async event=>{if(preventDefault)event?.preventDefault?.();try{await action(event);}catch(error){if(error.status!==401)toast(error.message,true);}}; }
function selectedSources() { return state.sources.filter(source=>state.sourceIds.has(source.id)); }
