function featureForBbox(extent) { return {type:'Feature',properties:{},geometry:{type:'Polygon',coordinates:[[[extent[0],extent[1]],[extent[2],extent[1]],[extent[2],extent[3]],[extent[0],extent[3]],[extent[0],extent[1]]]]}}; }
function boundaryExtent(boundary) { const coordinates=[];const visit=value=>{if(Array.isArray(value)&&typeof value[0]==='number')coordinates.push(value);else if(Array.isArray(value))value.forEach(visit);};visit(boundary.geometry?.coordinates||boundary.coordinates);if(!coordinates.length)throw new Error('Boundary has no coordinates.');return [Math.min(...coordinates.map(point=>point[0])),Math.min(...coordinates.map(point=>point[1])),Math.max(...coordinates.map(point=>point[0])),Math.max(...coordinates.map(point=>point[1]))]; }
function setBoundary(boundary,fit=true) {
  state.boundary=boundary?.type==='Feature'?boundary:boundary?{type:'Feature',properties:{},geometry:boundary}:null;state.bbox=boundary?boundaryExtent(state.boundary):null;state.drawn.clearLayers();
  if(boundary)L.geoJSON(state.boundary,{style:{color:'#206c5a',weight:2,fillOpacity:.08}}).eachLayer(layer=>state.drawn.addLayer(layer));
  ['west','south','east','north'].forEach((key,index)=>{$(`#bbox-${key}`).value=state.bbox?Number(state.bbox[index].toFixed(7)):'';});
  $('#boundary-label').textContent=boundary?`${state.boundary.geometry.type} boundary`:'No boundary';$('#map-location').textContent=state.bbox?`${state.bbox[0].toFixed(4)}, ${state.bbox[1].toFixed(4)} / ${state.bbox[2].toFixed(4)}, ${state.bbox[3].toFixed(4)}`:'Canada & United States';$('#course-boundary-status').textContent=boundary?`WGS84 ${state.boundary.geometry.type} / ${state.bbox.map(value=>value.toFixed(5)).join(', ')}`:'No boundary selected';
  if(boundary&&fit)state.map.fitBounds([[state.bbox[1],state.bbox[0]],[state.bbox[3],state.bbox[2]]],{padding:[35,35],maxZoom:18});loadFootprints().catch(error=>{if(error.status!==401)toast(error.message,true);});
}
function renderCoverage() { if(!state.coverage)return;state.coverage.clearLayers();selectedSources().forEach(source=>L.geoJSON(featureForBbox(source.coverageBbox),{style:{color:'#bea253',weight:1,dashArray:'5 5',fillOpacity:0},interactive:false}).addTo(state.coverage)); }
