import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { mkdir, readFile, writeFile, rename } from 'node:fs/promises';
import dotenv from 'dotenv';
import { HttpError } from './spatial.js';

export const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

export function loadConfig(overrides = {}) {
  dotenv.config({ path: path.join(projectRoot, '.env'), quiet: true });
  const number = (key, fallback, minimum = 1, maximum = Number.MAX_SAFE_INTEGER) => {
    const value = Number(process.env[key] || fallback);
    if (!Number.isFinite(value) || value < minimum || value > maximum) throw new Error(`Invalid ${key} in .env.`);
    return value;
  };
  const config = {
    host: process.env.HOST || '127.0.0.1',
    port: number('PORT', 3123, 1, 65535),
    storageRoot: path.resolve(process.env.STORAGE_ROOT || path.join(projectRoot, 'terrain-data')),
    catalogPath: path.resolve(process.env.CATALOG_PATH || path.join(projectRoot, 'data', 'catalog.sqlite')),
    downloadConcurrency: number('DOWNLOAD_CONCURRENCY', 2, 1, 16),
    downloadRetries: number('DOWNLOAD_RETRIES', 3, 0, 10),
    requestTimeoutMs: number('REQUEST_TIMEOUT_MS', 60000),
    downloadIdleTimeoutMs: number('DOWNLOAD_IDLE_TIMEOUT_MS', 120000),
    maxDiscoveryAssets: number('MAX_DISCOVERY_ASSETS', 100000),
    minFreeDiskGb: number('MIN_FREE_DISK_GB', 1, 0),
    defaultBufferMeters: number('DEFAULT_BUFFER_METERS', 500, 0, 10000),
    maxExportPixels: number('MAX_EXPORT_PIXELS', 4096, 64, 16384),
    maxProcessingPixels: number('MAX_PROCESSING_PIXELS', 100000000),
    maxArchiveUncompressedGb: number('MAX_ARCHIVE_UNCOMPRESSED_GB', 1024),
    updateCheckDays: number('UPDATE_CHECK_DAYS', 30, 0, 3650),
    apiKey: process.env.API_KEY || '',
    corsOrigins: (process.env.CORS_ORIGINS || 'http://localhost:3123,http://127.0.0.1:3123').split(',').map((value) => value.trim()).filter(Boolean),
    allowPrivateDownloadHosts: process.env.ALLOW_PRIVATE_DOWNLOAD_HOSTS === 'true',
    extraDownloadHosts: (process.env.DOWNLOAD_ALLOWED_HOSTS || '').split(',').map((value) => value.trim()).filter(Boolean),
    gisEnvRoot: process.env.GIS_ENV_ROOT || '',
    tools: {
      pdal: process.env.PDAL_BIN || 'pdal',
      gdalinfo: process.env.GDALINFO_BIN || 'gdalinfo',
      gdalwarp: process.env.GDALWARP_BIN || 'gdalwarp',
      gdal_translate: process.env.GDAL_TRANSLATE_BIN || 'gdal_translate',
      gdal_contour: process.env.GDAL_CONTOUR_BIN || 'gdal_contour',
      gdaldem: process.env.GDALDEM_BIN || 'gdaldem',
      ogr2ogr: process.env.OGR2OGR_BIN || 'ogr2ogr',
      gdalsrsinfo: process.env.GDALSRSINFO_BIN || 'gdalsrsinfo',
      gdallocationinfo: process.env.GDALLOCATIONINFO_BIN || 'gdallocationinfo'
    },
    envPath: path.join(projectRoot, '.env'),
    ...overrides
  };
  if (!['localhost', '127.0.0.1', '::1'].includes(config.host) && !config.apiKey) {
    throw new Error('Set API_KEY before binding HOST to a non-loopback address.');
  }
  return config;
}

export async function persistStorageRoot(config, root) {
  if (typeof root !== 'string' || !root.trim() || !path.isAbsolute(root) || root.includes('\0')) {
    throw new HttpError(400, 'storageRoot must be an absolute filesystem path.');
  }
  const resolved = path.resolve(root);
  await mkdir(resolved, { recursive: true });
  const probe = path.join(resolved, `.terrainserver-write-${crypto.randomUUID()}`);
  await writeFile(probe, '');
  const { unlink } = await import('node:fs/promises');
  await unlink(probe);
  const original = await readFile(config.envPath, 'utf8').catch((error) => { if (error.code === 'ENOENT') return ''; throw error; });
  const values = dotenv.parse(original);
  values.STORAGE_ROOT = resolved.replaceAll('\\', '/');
  const content = Object.entries(values).map(([key, value]) => `${key}=${JSON.stringify(value)}`).join('\n') + '\n';
  const temporary = `${config.envPath}.tmp`;
  await writeFile(temporary, content, { mode: 0o600 });
  await rename(temporary, config.envPath);
  config.storageRoot = resolved;
  process.env.STORAGE_ROOT = resolved;
  return resolved;
}

export function safeSegment(value) {
  const segment = String(value || '').normalize('NFKD').replace(/[^a-zA-Z0-9_-]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 100);
  if (!segment) throw new HttpError(400, 'Identifier must contain letters or numbers.');
  return segment;
}

export function courseDirectory(root, course) {
  const country = course?.country === 'US' ? 'usa' : 'canada';
  return path.join(root, country, safeSegment(course?.province || course?.region || 'national').toLowerCase(), safeSegment(course?.id || '_repository'));
}

export function isContained(root, filename) {
  const relative = path.relative(path.resolve(root), path.resolve(filename));
  return relative !== '..' && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative);
}

import { spawn } from 'node:child_process';
import path from 'node:path';
import proj4 from 'proj4';
import { HttpError, parseBbox, metricCrs } from './spatial.js';

proj4.defs('EPSG:3413', '+proj=stere +lat_0=90 +lat_ts=70 +lon_0=-45 +datum=WGS84 +units=m +no_defs');
proj4.defs('EPSG:3031', '+proj=stere +lat_0=-90 +lat_ts=-71 +lon_0=0 +datum=WGS84 +units=m +no_defs');
for (let zone = 1; zone <= 60; zone++) {
  proj4.defs(`EPSG:${32600 + zone}`, `+proj=utm +zone=${zone} +datum=WGS84 +units=m +no_defs`);
  proj4.defs(`EPSG:${32700 + zone}`, `+proj=utm +zone=${zone} +south +datum=WGS84 +units=m +no_defs`);
  if (zone <= 23) proj4.defs(`EPSG:${26900 + zone}`, `+proj=utm +zone=${zone} +datum=NAD83 +units=m +no_defs`);
}
proj4.defs('EPSG:3979', '+proj=lcc +lat_0=49 +lon_0=-95 +lat_1=49 +lat_2=77 +x_0=0 +y_0=0 +datum=NAD83 +units=m +no_defs');

export function projectExtent(extent, target = metricCrs(extent)) {
  const [west, south, east, north] = parseBbox(extent);
  const points = [];
  for (let step = 0; step <= 16; step++) {
    const fraction = step / 16;
    points.push(proj4('EPSG:4326', target, [west + (east - west) * fraction, south]),
      proj4('EPSG:4326', target, [west + (east - west) * fraction, north]),
      proj4('EPSG:4326', target, [west, south + (north - south) * fraction]),
      proj4('EPSG:4326', target, [east, south + (north - south) * fraction]));
  }
  return { crs: target, bbox: [Math.min(...points.map((point) => point[0])), Math.min(...points.map((point) => point[1])), Math.max(...points.map((point) => point[0])), Math.max(...points.map((point) => point[1]))] };
}

export function geographicExtent(extent, crs) {
  const [west, south, east, north] = extent;
  const points = [[west, south], [east, south], [east, north], [west, north]].map((point) => proj4(crs, 'EPSG:4326', point));
  return [Math.min(...points.map((point) => point[0])), Math.min(...points.map((point) => point[1])), Math.max(...points.map((point) => point[0])), Math.max(...points.map((point) => point[1]))];
}

export class Gis {
  constructor(config) { this.config = config; }

  environment() {
    const root = this.config.gisEnvRoot;
    if (!root) return process.env;
    return { ...process.env, PATH: [path.join(root, 'Library', 'bin'), path.join(root, 'bin'), root, process.env.PATH].join(path.delimiter),
      GDAL_DATA: path.join(root, 'Library', 'share', 'gdal'), PROJ_DATA: path.join(root, 'Library', 'share', 'proj'),
      PROJ_LIB: path.join(root, 'Library', 'share', 'proj'), PROJ_NETWORK: 'OFF', GDAL_NUM_THREADS: '2', GDAL_CACHEMAX: '256' };
  }

  run(tool, args, options = {}) {
    const executable = this.config.tools[tool];
    if (!executable) throw new HttpError(503, `${tool} is not configured in .env.`);
    options.signal?.throwIfAborted();
    return new Promise((resolve, reject) => {
      const child = spawn(executable, args.map(String), { env: this.environment(), cwd: options.cwd, windowsHide: true, shell: false });
      let stdout = '';
      let stderr = '';
      let settled = false;
      const finish = (error, result) => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        options.signal?.removeEventListener('abort', cancel);
        if (error) reject(error); else resolve(result);
      };
      const cancel = () => { child.kill(); finish(options.signal?.reason || new Error('Processing cancelled.')); };
      options.signal?.addEventListener('abort', cancel, { once: true });
      const timer = setTimeout(() => { child.kill(); finish(new HttpError(504, `${tool} exceeded its processing time limit.`)); }, options.timeoutMs || 6 * 60 * 60 * 1000);
      timer.unref?.();
      child.stdout.on('data', (chunk) => {
        stdout += chunk.toString();
        options.onOutput?.(chunk.toString());
        if (stdout.length > (options.maxOutputBytes || 64 * 1024 * 1024)) { child.kill(); finish(new HttpError(413, 'GIS output exceeded its limit; refine the query boundary.')); }
      });
      child.stderr.on('data', (chunk) => { stderr = (stderr + chunk.toString()).slice(-16000); options.onOutput?.(chunk.toString()); });
      child.on('error', (error) => finish(new HttpError(503, `${tool} could not run: ${error.message}. Check its .env path and GIS_ENV_ROOT.`)));
      child.stdin.on('error',error=>{if(error.code!=='EPIPE')finish(new HttpError(503,`${tool} input failed: ${error.message}`));});
      child.stdin.end(options.input||'');
      child.on('close', (code) => finish(code === 0 ? null : new HttpError(502, `${tool} exited with code ${code}: ${stderr.slice(-4000)}`, { stdout,stderr,code }), { stdout, stderr, code }));
    });
  }

  async check() {
    const tools = await Promise.all(Object.keys(this.config.tools).map(async (name) => {
      try { const result = await this.run(name, ['--version'], { timeoutMs: 20000, maxOutputBytes: 100000 });
        return { name, executable: this.config.tools[name], available: true, version: (result.stdout || result.stderr).trim().split(/\r?\n/).find((line) => /\b(?:GDAL|pdal)\s+[\d.]/i.test(line)) || 'Available' };
      } catch (error) {
        const version = (error.details?.stdout || '').split(/\r?\n/).find((line) => /\b(?:GDAL|pdal)\s+[\d.]/i.test(line));
        if (version) return { name, executable: this.config.tools[name], available: true, version, versionCheckExitCode: error.details.code };
        return { name, executable: this.config.tools[name], available: false, error: error.message };
      }
    }));
    return { tools, rasterReady: tools.filter((tool) => tool.name !== 'pdal' && tool.name !== 'ogr2ogr').every((tool) => tool.available),
      pointCloudReady: tools.every((tool) => tool.available), vectorIndexReady: tools.find((tool) => tool.name === 'ogr2ogr')?.available };
  }
}

