export function windowsServiceXml(appDir,stateDir){
  return `<service>
  <id>TerrainServer</id>
  <name>TerrainServer</name>
  <description>Local LiDAR acquisition, storage, and terrain API.</description>
  <executable>%BASE%\\runtime\\node\\node.exe</executable>
  <arguments>"%BASE%\\src\\server.js"</arguments>
  <workingdirectory>%BASE%</workingdirectory>
  <env name="TERRAIN_CONFIG_PATH" value="${xml(path.join(stateDir,'.env'))}"/>
  <env name="TEMP" value="${xml(path.join(stateDir,'tmp'))}"/>
  <env name="TMP" value="${xml(path.join(stateDir,'tmp'))}"/>
  <startmode>Automatic</startmode>
  <delayedAutoStart/>
  <serviceaccount><domain>NT AUTHORITY</domain><user>LocalService</user></serviceaccount>
  <stoptimeout>60sec</stoptimeout>
  <stopparentprocessfirst>true</stopparentprocessfirst>
  <onfailure action="restart" delay="10sec"/>
  <logpath>${xml(path.join(stateDir,'logs'))}</logpath>
  <log mode="roll-by-size"><sizeThreshold>10240</sizeThreshold><keepFiles>8</keepFiles></log>
</service>
`;
}

export function systemdService(appDir,stateDir){
  return `[Unit]
Description=TerrainServer local LiDAR and terrain API
Wants=network-online.target
After=network-online.target

[Service]
Type=simple
User=terrainserver
Group=terrainserver
WorkingDirectory=${unitQuote(appDir)}
Environment=${unitQuote(`TERRAIN_CONFIG_PATH=${path.posix.join(stateDir,'.env')}`)}
Environment=${unitQuote(`TMPDIR=${path.posix.join(stateDir,'tmp')}`)}
ExecStart=${unitQuote(path.posix.join(appDir,'runtime/node/bin/node'))} ${unitQuote(path.posix.join(appDir,'src/server.js'))}
Restart=on-failure
RestartSec=10
TimeoutStopSec=60
KillMode=mixed
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=full
ProtectHome=true
ReadOnlyPaths=${unitQuote(appDir)}
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
`;
}

export async function configureInstallation(options){
  const platform=options.platform||process.platform;
  if(!['win32','linux'].includes(platform))throw new Error('Installer supports Windows/x64 and Linux/x64.');
  const appDir=path.resolve(options.appDir||'.');
  if(!options.stateDir||!path.isAbsolute(options.stateDir))throw new Error('state-dir must be an absolute directory outside the program directory.');
  const stateDir=path.resolve(options.stateDir);
  const contained=value=>{const relative=path.relative(appDir,path.resolve(value));return relative===''||(!relative.startsWith(`..${path.sep}`)&&relative!=='..'&&!path.isAbsolute(relative));};
  if(contained(stateDir))throw new Error('State and configuration must be outside the program directory.');
  const envPath=path.join(stateDir,'.env');
  await mkdir(stateDir,{recursive:true,mode:0o700});
  const original=await readFile(envPath,'utf8').catch(error=>{if(error.code==='ENOENT')return null;throw error;});
  const values=dotenv.parse(original??await readFile(path.join(appDir,'.env.example'),'utf8'));
  const preserved=original!==null;
  if(!preserved){
    const port=Number(options.port??3123);
    if(!Number.isInteger(port)||port<1||port>65535)throw new Error('Port must be an integer from 1 to 65535.');
    const host=options.host||'127.0.0.1';
    if(!['127.0.0.1','localhost','::1','0.0.0.0','::'].includes(host))throw new Error('Choose a loopback or all-interfaces bind address.');
    const storageRoot=options.storageRoot||path.join(stateDir,'terrain-data');
    if(!path.isAbsolute(storageRoot)||contained(storageRoot))throw new Error('Terrain storage must be an absolute directory outside the program directory.');
    values.HOST=host;values.PORT=String(port);values.STORAGE_ROOT=portablePath(path.resolve(storageRoot));
    values.CATALOG_PATH=portablePath(path.join(stateDir,'catalog','catalog.sqlite'));
    values.CORS_ORIGINS=`http://localhost:${port},http://127.0.0.1:${port}`;
    values.API_KEY=options.requireKey||!['127.0.0.1','localhost','::1'].includes(host)?randomBytes(32).toString('hex'):'';
  }
  if(!['localhost','127.0.0.1','::1'].includes(values.HOST||'127.0.0.1')&&!values.API_KEY)throw new Error('Existing remote configuration requires API_KEY.');
  const storageRoot=path.resolve(stateDir,values.STORAGE_ROOT||'terrain-data');
  const catalogPath=path.resolve(stateDir,values.CATALOG_PATH||'catalog/catalog.sqlite');
  if(contained(storageRoot)||contained(catalogPath))throw new Error('Existing catalog and storage paths must be outside the program directory.');
  for(const directory of [storageRoot,path.dirname(catalogPath),path.join(stateDir,'logs'),path.join(stateDir,'tmp')])await mkdir(directory,{recursive:true,mode:0o700});
  const gisDir=path.join(appDir,'runtime','gis');
  values.GIS_ENV_ROOT=portablePath(gisDir);
  for(const tool of tools)values[`${tool.toUpperCase()}_BIN`]=portablePath(path.join(gisDir,platform==='win32'?'Library/bin':'bin',`${tool}${platform==='win32'?'.exe':''}`));
  const content=Object.entries(values).map(([key,value])=>`${key}=${JSON.stringify(value)}`).join('\n')+'\n';
  if(content!==original){
    if(preserved)await writeFile(path.join(stateDir,`.env.backup-${Date.now()}`),original,{mode:0o600});
    const temporary=envPath+'.tmp';await writeFile(temporary,content,{mode:0o600});await rename(temporary,envPath);
  }
  const serviceFile=path.join(appDir,platform==='win32'?'TerrainServerService.xml':'terrainserver.service');
  await writeFile(serviceFile,platform==='win32'?windowsServiceXml(appDir,stateDir):systemdService(portablePath(appDir),portablePath(stateDir)));
  const bootstrap={stateDir,envPath,storageRoot,catalogPath,host:values.HOST,port:Number(values.PORT||3123),apiKeyRequired:!!values.API_KEY,preserved};
  await writeFile(path.join(appDir,'installation.json'),JSON.stringify(bootstrap,null,2)+'\n');
  await writeFile(path.join(appDir,'launch.cmd'),`@echo off\r\nset "TERRAIN_CONFIG_PATH=${envPath}"\r\n"%~dp0runtime\\node\\node.exe" "%~dp0src\\server.js"\r\n`);
  return bootstrap;
}

async function main(){
  const {values}=parseArgs({options:{'app-dir':{type:'string'},'state-dir':{type:'string'},'storage-root':{type:'string'},port:{type:'string'},host:{type:'string'},'require-key':{type:'boolean',default:false},platform:{type:'string'}}});
  await access(path.join(path.resolve(values['app-dir']||'.'),'src','server.js'));
  const result=await configureInstallation({appDir:values['app-dir'],stateDir:values['state-dir'],storageRoot:values['storage-root'],port:values.port,host:values.host,requireKey:values['require-key'],platform:values.platform});
  console.log(`Configuration: ${result.envPath}\nStorage: ${result.storageRoot}\nPort: ${result.port}\nExisting settings: ${result.preserved?'preserved':'new'}\nAPI key: ${result.apiKeyRequired?'required; read locally from protected .env':'not required (loopback)'}`);
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))main().catch(error=>{console.error(error.message);process.exitCode=1;});

import test from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import os from 'node:os';
import { mkdtemp,mkdir,copyFile,readFile,writeFile,rm } from 'node:fs/promises';
import dotenv from 'dotenv';
import { configureInstallation,windowsServiceXml,systemdService } from '../scripts/configure-service.js';

test('installer initializes separate state, secures remote binding, and preserves user configuration and data on upgrade',async()=>{
  const root=await mkdtemp(path.join(os.tmpdir(),'terrain-installer-'));
  try{
    const appDir=path.join(root,'program'),stateDir=path.join(root,'state'),storageRoot=path.join(root,'storage');
    await mkdir(appDir);await copyFile('.env.example',path.join(appDir,'.env.example'));
    const options={appDir,stateDir,storageRoot,port:3198,host:'0.0.0.0',platform:'win32'};
    const first=await configureInstallation(options);const config=dotenv.parse(await readFile(first.envPath,'utf8'));
    assert.equal(config.PORT,'3198');assert.equal(config.HOST,'0.0.0.0');assert.match(config.API_KEY,/^[a-f0-9]{64}$/);assert.equal(config.STORAGE_ROOT,storageRoot.replaceAll('\\','/'));
    assert.match(config.GDALLOCATIONINFO_BIN,/runtime\/gis\/Library\/bin\/gdallocationinfo.exe$/);
    const raw=path.join(storageRoot,'original.laz');await writeFile(raw,'raw-data');
    const modified=(await readFile(first.envPath,'utf8')).replace('PORT="3198"','PORT="3197"')+'CUSTOM_SETTING="unchanged"\n';await writeFile(first.envPath,modified);
    const second=await configureInstallation({...options,port:3123,host:'127.0.0.1'});assert.equal(second.preserved,true);assert.equal(second.port,3197);const upgraded=dotenv.parse(await readFile(first.envPath,'utf8'));assert.equal(upgraded.API_KEY,config.API_KEY);assert.equal(upgraded.CUSTOM_SETTING,'unchanged');assert.equal(upgraded.HOST,'0.0.0.0');assert.equal(await readFile(raw,'utf8'),'raw-data');
    await assert.rejects(configureInstallation({...options,stateDir:path.join(appDir,'state')}),/outside the program/);
    const service=await readFile(path.join(appDir,'TerrainServerService.xml'),'utf8');assert.match(service,/<user>LocalService<\/user>/);assert.match(service,/TERRAIN_CONFIG_PATH/);assert.ok(!service.includes(config.API_KEY));
    assert.ok(!(await readFile(path.join(appDir,'installation.json'),'utf8')).includes(config.API_KEY));
  }finally{await rm(root,{recursive:true,force:true});}
});

test('service definitions quote installation paths and never require an API key in process arguments',()=>{
  const windows=windowsServiceXml('C:\\Program Files\\TerrainServer','C:\\Data & Terrain');assert.match(windows,/Data &amp; Terrain/);assert.match(windows,/<stoptimeout>60sec/);assert.ok(!windows.includes('API_KEY'));
  const linux=systemdService('/opt/terrain server 100%','/var/lib/terrainserver');assert.match(linux,/User=terrainserver/);assert.match(linux,/ExecStart="\/opt\/terrain server 100%%\/runtime\/node\/bin\/node"/);assert.match(linux,/ProtectSystem=full/);assert.match(linux,/TERRAIN_CONFIG_PATH=\/var\/lib\/terrainserver\/.env/);
});

import path from 'node:path';
import os from 'node:os';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { createReadStream,createWriteStream } from 'node:fs';
import { mkdir,readFile,writeFile,copyFile,cp,readdir,rm,access,rename } from 'node:fs/promises';
import { pipeline } from 'node:stream/promises';
import { Readable } from 'node:stream';
import { spawn } from 'node:child_process';
import { parseArgs } from 'node:util';
import unzipper from 'unzipper';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const nativeTools=['pdal','gdalinfo','gdalwarp','gdal_translate','gdal_contour','gdaldem','ogr2ogr','gdalsrsinfo','gdallocationinfo'];
const {values}=parseArgs({options:{'gis-env':{type:'string'},iscc:{type:'string'},'node-version':{type:'string'},platform:{type:'string',default:'win32'}}});
const buildRoot=path.join(root,'build'),cache=path.join(buildRoot,'cache'),output=path.join(root,'dist');

function run(executable,args,options={}){
  return new Promise((resolve,reject)=>{
    const child=spawn(executable,args,{cwd:root,windowsHide:true,stdio:options.capture?'pipe':'inherit',...options});let stdout='',stderr='';
    child.stdout?.on('data',chunk=>{stdout+=chunk;});child.stderr?.on('data',chunk=>{stderr+=chunk;});
    child.once('error',reject);child.once('exit',code=>{if(code!==0&&!options.allowFailure)reject(new Error(`${path.basename(executable)} exited ${code}: ${stderr||stdout}`));else resolve({code,stdout,stderr});});
  });
}
async function hash(filename){const digest=createHash('sha256');for await(const chunk of createReadStream(filename))digest.update(chunk);return digest.digest('hex');}
async function download(url,filename,expected){
  await mkdir(path.dirname(filename),{recursive:true});
  if(await access(filename).then(()=>true,()=>false)){if(!expected||await hash(filename)===expected)return filename;await rm(filename);}
  console.log(`Downloading ${path.basename(filename)}`);
  const response=await fetch(url,{signal:AbortSignal.timeout(180000),headers:{'User-Agent':'TerrainServer-Installer-Builder'}});
  if(!response.ok)throw new Error(`Download ${response.status}: ${url}`);
  await pipeline(Readable.fromWeb(response.body),createWriteStream(filename+'.part'));await rename(filename+'.part',filename);
  if(expected&&await hash(filename)!==expected){await rm(filename);throw new Error(`SHA256 mismatch for ${filename}`);}
  return filename;
}
async function nodeRuntime(stage){
  const releases=await fetch('https://nodejs.org/dist/index.json',{signal:AbortSignal.timeout(60000)}).then(response=>{if(!response.ok)throw new Error('Cannot read official Node.js releases.');return response.json();});
  const version=values['node-version']||releases.find(item=>item.lts&&item.version.startsWith('v24.'))?.version;
  if(!/^v24\.\d+\.\d+$/.test(version||''))throw new Error('Use a published Node.js 24 LTS version (v24.x.y).');
  const basename=`node-${version}-win-x64.zip`;
  const checksums=await fetch(`https://nodejs.org/dist/${version}/SHASUMS256.txt`,{signal:AbortSignal.timeout(60000)}).then(response=>{if(!response.ok)throw new Error('Cannot read official Node.js checksums.');return response.text();});
  const expected=checksums.split('\n').map(line=>line.trim().split(/\s+/)).find(parts=>parts[1]===basename)?.[0];
  if(!expected)throw new Error('Official Node.js release checksum not found.');
  const archive=await download(`https://nodejs.org/dist/${version}/${basename}`,path.join(cache,basename),expected);
  const extracted=path.join(buildRoot,'node-extracted');await rm(extracted,{recursive:true,force:true});await mkdir(extracted,{recursive:true});
  await pipeline(createReadStream(archive),unzipper.Extract({path:extracted}));
  const nodeDir=path.join(stage,'runtime','node');await mkdir(nodeDir,{recursive:true});
  for(const filename of ['node.exe','LICENSE','README.md'])await copyFile(path.join(extracted,`node-${version}-win-x64`,filename),path.join(nodeDir,filename));
  await rm(extracted,{recursive:true,force:true});return {version,archive:basename,sha256:expected};
}
async function gisRuntime(stage,source){
  if(!source)throw new Error('Supply --gis-env pointing to a working Windows conda-forge GDAL/PDAL environment.');
  const records=new Map();for(const filename of await readdir(path.join(source,'conda-meta'))){if(!filename.endsWith('.json'))continue;const record=JSON.parse(await readFile(path.join(source,'conda-meta',filename),'utf8'));records.set(record.name,record);}
  const selected=new Set();
  function visit(name){if(name.startsWith('__')||selected.has(name))return;const record=records.get(name);if(!record)throw new Error(`Missing GIS runtime dependency: ${name}`);selected.add(name);for(const dependency of record.depends||[])visit(dependency.split(/\s+/)[0]);}
  visit('libgdal-core');visit('libpdal-core');
  const destination=path.join(stage,'runtime','gis');await mkdir(path.join(destination,'conda-meta'),{recursive:true});
  const files=new Set();const packages=[];
  for(const name of [...selected].sort()){
    const record=records.get(name);packages.push({name,version:record.version,build:record.build,license:record.license,url:record.url,sha256:record.sha256});
    await writeFile(path.join(destination,'conda-meta',`${name}.json`),JSON.stringify(record,null,2)+'\n');
    for(const filename of record.files||[]){
      if(/^(Library\/bin\/[^/]+\.(dll|exe)|[^/]+\.dll)$/i.test(filename)||/^Library\/share\/(gdal|proj)\//.test(filename)||/^Library\/lib\/(gdalplugins|pdal)\/.*\.dll$/i.test(filename))files.add(filename);
    }
  }
  for(const filename of files){const relative=path.normalize(filename);if(relative.startsWith('..')||path.isAbsolute(relative))throw new Error('Invalid native package member.');await mkdir(path.dirname(path.join(destination,relative)),{recursive:true});await copyFile(path.join(source,relative),path.join(destination,relative));}
  await cp(path.join(source,'Library','share','licenses'),path.join(destination,'Library','share','licenses'),{recursive:true});
  for(const tool of nativeTools)await access(path.join(destination,'Library','bin',`${tool}.exe`));
  await writeFile(path.join(stage,'THIRD-PARTY-GIS.json'),JSON.stringify(packages,null,2)+'\n');
  console.log(`Bundled ${selected.size} GIS runtime packages / ${files.size} native files.`);return packages;
}
async function wrapper(stage){
  const url='https://github.com/winsw/winsw/releases/download/v2.12.0/WinSW.NET461.exe';
  const filename=await download(url,path.join(cache,'WinSW.NET461-2.12.0.exe'));
  const licenseResponse=await fetch('https://api.github.com/repos/winsw/winsw/license?ref=v2.12.0',{headers:{'User-Agent':'TerrainServer-Installer-Builder'},signal:AbortSignal.timeout(60000)});
  if(!licenseResponse.ok)throw new Error('Cannot retrieve WinSW license.');const license=await licenseResponse.json();
  await copyFile(filename,path.join(stage,'TerrainServerService.exe'));await writeFile(path.join(stage,'LICENSE-WinSW.txt'),Buffer.from(license.content,'base64'));
  return {version:'2.12.0',runtime:'.NET Framework 4.6.1+',url,sha256:await hash(filename)};
}
async function compiler(){
  const candidates=[values.iscc,process.env.ISCC_PATH,path.join(process.env.LOCALAPPDATA||os.homedir(),'Programs','Inno Setup 6','ISCC.exe'),path.join(process.env['ProgramFiles(x86)']||'C:/Program Files (x86)','Inno Setup 6','ISCC.exe'),path.join(process.env.LOCALAPPDATA||os.homedir(),'Programs','Inno Setup 7','ISCC.exe')].filter(Boolean);
  for(const candidate of candidates)if(await access(candidate).then(()=>true,()=>false))return candidate;
  throw new Error('Install Inno Setup 6/7 or pass --iscc with the full ISCC.exe path.');
}
async function validate(stage){
  const node=path.join(stage,'runtime','node','node.exe');const gis=path.join(stage,'runtime','gis');
  const env={...process.env,PATH:[path.join(gis,'Library','bin'),gis,path.join(process.env.SystemRoot||'C:/Windows','System32'),process.env.SystemRoot||'C:/Windows'].join(path.delimiter),GDAL_DATA:path.join(gis,'Library/share/gdal'),PROJ_DATA:path.join(gis,'Library/share/proj'),PROJ_LIB:path.join(gis,'Library/share/proj'),PROJ_NETWORK:'OFF'};
  await run(node,['--input-type=module','-e',"import sharp from 'sharp';import {DatabaseSync} from 'node:sqlite';console.log('Packaged Sharp',sharp.versions.sharp);new DatabaseSync(':memory:').close();"],{cwd:stage,env});
  for(const tool of nativeTools){const result=await run(path.join(gis,'Library','bin',`${tool}.exe`),['--version'],{env,capture:true,allowFailure:true});if(!/GDAL \d|PDAL \d|pdal \d/i.test(result.stdout+'\n'+result.stderr))throw new Error(`Bundled ${tool} cannot start: ${result.stderr||result.stdout}`);console.log(`${tool}: ${(result.stdout+' '+result.stderr).match(/(?:GDAL|pdal|PDAL) [^\r\n]+/)?.[0]}`);}
  const parsed=await run('powershell.exe',['-NoProfile','-Command',`$errors=$null;[System.Management.Automation.Language.Parser]::ParseFile('${path.join(stage,'installer/windows/service.ps1').replaceAll("'","''")}',[ref]$null,[ref]$errors)|Out-Null;if($errors.Count){$errors|ForEach-Object{Write-Error $_.Message};exit 1}`],{capture:true});
  if(parsed.code)throw new Error(parsed.stderr);
}
async function main(){
  if(process.platform!=='win32'||values.platform!=='win32')throw new Error('This build currently targets Windows/x64.');
  const packageJson=JSON.parse(await readFile(path.join(root,'package.json'),'utf8'));
  const stage=path.join(buildRoot,'staging','windows-x64');await rm(stage,{recursive:true,force:true});await mkdir(stage,{recursive:true});await mkdir(output,{recursive:true});
  for(const directory of ['src','public','installer'])await cp(path.join(root,directory),path.join(stage,directory),{recursive:true});
  await mkdir(path.join(stage,'scripts'));await copyFile(path.join(root,'scripts/configure-service.js'),path.join(stage,'scripts/configure-service.js'));
  for(const filename of ['package.json','package-lock.json','.env.example','README.md'])await copyFile(path.join(root,filename),path.join(stage,filename));
  const npmCli=process.env.npm_execpath||path.join(path.dirname(process.execPath),'node_modules/npm/bin/npm-cli.js');
  await run(process.execPath,[npmCli,'ci','--omit=dev','--ignore-scripts','--no-audit','--no-fund'],{cwd:stage});
  const node=await nodeRuntime(stage);const packages=await gisRuntime(stage,path.resolve(values['gis-env']||process.env.GIS_ENV_ROOT||''));const serviceWrapper=await wrapper(stage);
  await writeFile(path.join(stage,'BUILD-MANIFEST.json'),JSON.stringify({application:packageJson.name,version:packageJson.version,platform:'windows-x64',created:new Date().toISOString(),node,serviceWrapper,gisPackages:packages,packageLockSha256:await hash(path.join(stage,'package-lock.json'))},null,2)+'\n');
  await validate(stage);
  await run(await compiler(),['/Qp',`/DStageDir=${stage}`,`/DOutputDir=${output}`,`/DAppVersion=${packageJson.version}`,path.join(root,'installer/windows/setup.iss')]);
  const setup=path.join(output,`TerrainServer-${packageJson.version}-windows-x64-setup.exe`);await access(setup);await writeFile(setup+'.sha256',`${await hash(setup)}  ${path.basename(setup)}\n`);
  console.log(`Installer ready: ${setup}`);
}
main().catch(error=>{console.error(error.stack);process.exitCode=1;});

param(
    [ValidateSet('Prepare','Configure','Remove')][string]$Mode = 'Configure',
    [Parameter(Mandatory=$true)][string]$AppDirectory,
    [string]$StateDirectory,
    [string]$StorageRoot,
    [int]$Port = 3123,
    [string]$BindAddress = '127.0.0.1',
    [switch]$RequireApiKey,
    [switch]$InstallService
)
$ErrorActionPreference = 'Stop'
$AppDirectory = [IO.Path]::GetFullPath($AppDirectory).TrimEnd('\')
$Wrapper = Join-Path $AppDirectory 'TerrainServerService.exe'
$Principal = [Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())
$Elevated = $Principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

function Get-OwnedService {
    $Service = Get-CimInstance Win32_Service -Filter "Name='TerrainServer'" -ErrorAction Stop
    if ($Service) {
        $Match = [regex]::Match($Service.PathName, '^(?:"([^"]+)"|(\S+))')
        $Binary = if ($Match.Groups[1].Success) { $Match.Groups[1].Value } else { $Match.Groups[2].Value }
        if (-not [string]::Equals([IO.Path]::GetFullPath($Binary), $Wrapper, [StringComparison]::OrdinalIgnoreCase)) {
            throw 'A TerrainServer service belongs to another installation. Upgrade that installation in place or remove its service explicitly.'
        }
    }
    return $Service
}

function Stop-OwnedService {
    $Service = Get-OwnedService
    if ($Service -and $Service.State -ne 'Stopped') {
        Stop-Service -Name TerrainServer -ErrorAction Stop
        (Get-Service TerrainServer).WaitForStatus('Stopped', [TimeSpan]::FromSeconds(60))
    }
    return $Service
}

function Protect-State([string]$Directory) {
    $Directory = [IO.Path]::GetFullPath($Directory).TrimEnd('\')
    if ($Directory -eq [IO.Path]::GetPathRoot($Directory).TrimEnd('\') -or $Directory -eq $AppDirectory -or $Directory.StartsWith($AppDirectory+'\', [StringComparison]::OrdinalIgnoreCase)) {
        throw 'Choose a dedicated state directory outside the program directory, not a volume root.'
    }
    [IO.Directory]::CreateDirectory($Directory) | Out-Null
    $Acl = Get-Acl -LiteralPath $Directory
    $Acl.SetAccessRuleProtection($true, $false)
    foreach ($Sid in @('S-1-5-18','S-1-5-32-544')) {
        $Rule = [Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new($Sid),'FullControl','ContainerInherit,ObjectInherit','None','Allow')
        $Acl.AddAccessRule($Rule)
    }
    $User = [Security.Principal.WindowsIdentity]::GetCurrent().User
    $Acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($User,'FullControl','ContainerInherit,ObjectInherit','None','Allow'))
    if ($InstallService) {
        $Acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new('S-1-5-19'),'Modify','ContainerInherit,ObjectInherit','None','Allow'))
    }
    Set-Acl -LiteralPath $Directory -AclObject $Acl
}

function Grant-ServiceStorage([string]$Directory) {
    $Acl = Get-Acl -LiteralPath $Directory
    $Acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new('S-1-5-19'),'Modify','ContainerInherit,ObjectInherit','None','Allow'))
    Set-Acl -LiteralPath $Directory -AclObject $Acl
}

try {
    if ($Mode -eq 'Prepare') {
        if (-not $Elevated) { throw 'Service installation requires an administrator.' }
        Stop-OwnedService | Out-Null
        exit 0
    }
    if ($Mode -eq 'Remove') {
        if (-not $Elevated) { throw 'Service removal requires an administrator.' }
        $Service = Stop-OwnedService
        if ($Service) { & $Wrapper uninstall; if ($LASTEXITCODE -ne 0) { throw 'Windows service removal failed.' } }
        exit 0
    }
    if ($InstallService -and -not $Elevated) { throw 'Run Setup as administrator to register the Windows service.' }
    if (-not $StateDirectory) { throw 'StateDirectory is required.' }
    Protect-State $StateDirectory
    $Arguments = @((Join-Path $AppDirectory 'scripts\configure-service.js'),'--app-dir',$AppDirectory,'--state-dir',$StateDirectory,'--port',"$Port",'--host',$BindAddress,'--platform','win32')
    if ($StorageRoot) { $Arguments += @('--storage-root',$StorageRoot) }
    if ($RequireApiKey) { $Arguments += '--require-key' }
    & (Join-Path $AppDirectory 'runtime\node\node.exe') @Arguments
