var
  Locations: TInputDirWizardPage;
  Connection: TInputQueryWizardPage;
  Security: TInputOptionWizardPage;
  ConfigurationFailed: Boolean;

function GetStateDirectory(Param: String): String;
begin
  Result := Locations.Values[0];
end;

function Quote(Value: String): String;
begin
  Result := '"' + Value + '"';
end;

procedure InitializeWizard;
var
  State: String;
begin
  if IsAdminInstallMode then begin
    State := ExpandConstant('{commonappdata}\TerrainServer');
    RegQueryStringValue(HKLM64, '{#RegistryKey}', 'StateDirectory', State);
  end else begin
    State := ExpandConstant('{localappdata}\TerrainServer');
    RegQueryStringValue(HKCU, '{#RegistryKey}', 'StateDirectory', State);
  end;
  Locations := CreateInputDirPage(wpSelectDir, 'Configuration and Terrain Storage', 'Choose persistent directories outside the program folder.', 'Existing configuration, catalog, and terrain files are preserved during upgrades and uninstall.', False, '');
  Locations.Add('Configuration, catalog, and logs:');
  Locations.Add('Default terrain storage:');
  Locations.Values[0] := ExpandConstant('{param:STATEDIR|' + State + '}');
  Locations.Values[1] := ExpandConstant('{param:STORAGEROOT|' + Locations.Values[0] + '\terrain-data}');
  Connection := CreateInputQueryPage(Locations.ID, 'Server Connection', 'Choose the listening port and network binding.', 'Loopback is recommended behind a TLS reverse proxy. Remote bindings always require a generated API key. Existing .env settings take precedence on upgrades.');
  Connection.Add('TCP port:', False);
  Connection.Add('Bind address (127.0.0.1 or 0.0.0.0):', False);
  Connection.Values[0] := ExpandConstant('{param:PORT|3123}');
  Connection.Values[1] := ExpandConstant('{param:BIND|127.0.0.1}');
  Security := CreateInputOptionPage(Connection.ID, 'API Authentication', 'Keep the API key in the protected configuration file.', 'A generated key is stored only in .env, not in service arguments or installer logs. Read that file locally to connect authenticated clients.', False, False);
  Security.Add('Require an API key even when listening only on loopback');
  Security.Values[0] := ExpandConstant('{param:REQUIREKEY|0}') = '1';
end;

function NextButtonClick(CurPageID: Integer): Boolean;
var
  Port: Integer;
begin
  Result := True;
  if CurPageID = Locations.ID then begin
    if (Length(Locations.Values[0]) < 4) or (Length(Locations.Values[1]) < 4) or (ExtractFileDrive(Locations.Values[0]) = '') or (ExtractFileDrive(Locations.Values[1]) = '') then begin
      MsgBox('Choose absolute, dedicated directories, not volume roots.', mbError, MB_OK); Result := False;
    end;
  end;
  if CurPageID = Connection.ID then begin
    Port := StrToIntDef(Connection.Values[0], 0);
    if (Port < 1) or (Port > 65535) then begin MsgBox('Port must be from 1 to 65535.', mbError, MB_OK); Result := False; end;
    if (Connection.Values[1] <> '127.0.0.1') and (Connection.Values[1] <> 'localhost') and (Connection.Values[1] <> '0.0.0.0') and (Connection.Values[1] <> '::1') and (Connection.Values[1] <> '::') then begin MsgBox('Choose 127.0.0.1, localhost, ::1, 0.0.0.0, or ::.', mbError, MB_OK); Result := False; end;
  end;
end;

function PrepareToInstall(var NeedsRestart: Boolean): String;
var
  ExitCode: Integer;
begin
  Result := '';
  if IsAdminInstallMode and WizardIsTaskSelected('service') then begin
    ExtractTemporaryFile('service.ps1');
    if not ExecAndLogOutput(ExpandConstant('{sys}\WindowsPowerShell\v1.0\powershell.exe'), '-NoProfile -ExecutionPolicy Bypass -File ' + Quote(ExpandConstant('{tmp}\service.ps1')) + ' -Mode Prepare -AppDirectory ' + Quote(WizardDirValue), '', SW_SHOWNORMAL, ewWaitUntilTerminated, ExitCode, nil) then ExitCode := -1;
    if ExitCode <> 0 then Result := 'Could not prepare the Windows service. An existing TerrainServer service must belong to this installation. Check administrator rights and the selected program folder.';
  end;
end;

procedure CurStepChanged(CurStep: TSetupStep);
var
  Arguments: String;
  ExitCode: Integer;
begin
  if CurStep = ssPostInstall then begin
    Arguments := '-NoProfile -ExecutionPolicy Bypass -File ' + Quote(ExpandConstant('{app}\installer\windows\service.ps1')) + ' -Mode Configure -AppDirectory ' + Quote(ExpandConstant('{app}')) + ' -StateDirectory ' + Quote(Locations.Values[0]) + ' -StorageRoot ' + Quote(Locations.Values[1]) + ' -Port ' + Connection.Values[0] + ' -BindAddress ' + Quote(Connection.Values[1]);
    if Security.Values[0] then Arguments := Arguments + ' -RequireApiKey';
    if IsAdminInstallMode and WizardIsTaskSelected('service') then Arguments := Arguments + ' -InstallService';
    if not ExecAndLogOutput(ExpandConstant('{sys}\WindowsPowerShell\v1.0\powershell.exe'), Arguments, '', SW_SHOWNORMAL, ewWaitUntilTerminated, ExitCode, nil) then ExitCode := -1;
    Log('Service configuration exit code: ' + IntToStr(ExitCode));
    if ExitCode <> 0 then begin
      ConfigurationFailed := True;
      RaiseException('Configuration or service startup failed. Check the setup log, configuration paths, port availability, and state-directory logs. Existing terrain data has not been removed.');
    end;
  end;
end;

function GetCustomSetupExitCode: Integer;
begin
  if ConfigurationFailed then Result := 17 else Result := 0;
end;

param(
    [ValidateSet('Prepare','Configure','Remove')][string]$Mode = 'Configure',
    [Parameter(Mandatory=$true)][string]$AppDirectory,
    [string]$StateDirectory,
    [string]$StorageRoot,
    [int]$Port = 3123,
    [string]$BindAddress = '127.0.0.1',
    [switch]$RequireApiKey,
    [switch]$InstallService
)
$ErrorActionPreference = 'Stop'
$env:PSModulePath = [IO.Path]::Combine($PSHOME, 'Modules')
$AppDirectory = [IO.Path]::GetFullPath($AppDirectory).TrimEnd('\')
$Wrapper = Join-Path $AppDirectory 'TerrainServerService.exe'
$Principal = [Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())
$Elevated = $Principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

function Get-OwnedService {
    $Service = Get-CimInstance Win32_Service -Filter "Name='TerrainServer'" -ErrorAction Stop
    if ($Service) {
        $Match = [regex]::Match($Service.PathName, '^(?:"([^"]+)"|(\S+))')
        $Binary = if ($Match.Groups[1].Success) { $Match.Groups[1].Value } else { $Match.Groups[2].Value }
        if (-not [string]::Equals([IO.Path]::GetFullPath($Binary), $Wrapper, [StringComparison]::OrdinalIgnoreCase)) {
            throw 'A TerrainServer service belongs to another installation. Upgrade that installation in place or remove its service explicitly.'
        }
    }
    return $Service
}

function Stop-OwnedService {
    $Service = Get-OwnedService
    if ($Service -and $Service.State -ne 'Stopped') {
        Stop-Service -Name TerrainServer -ErrorAction Stop
        (Get-Service TerrainServer).WaitForStatus('Stopped', [TimeSpan]::FromSeconds(60))
    }
    return $Service
}

function Protect-State([string]$Directory) {
    $Directory = [IO.Path]::GetFullPath($Directory).TrimEnd('\')
    if ($Directory -eq [IO.Path]::GetPathRoot($Directory).TrimEnd('\') -or $Directory -eq $AppDirectory -or $Directory.StartsWith($AppDirectory+'\', [StringComparison]::OrdinalIgnoreCase)) {
        throw 'Choose a dedicated state directory outside the program directory, not a volume root.'
    }
    [IO.Directory]::CreateDirectory($Directory) | Out-Null
    $Acl = Get-Acl -LiteralPath $Directory
    $Acl.SetAccessRuleProtection($true, $false)
    foreach ($Sid in @('S-1-5-18','S-1-5-32-544')) {
        $Rule = [Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new($Sid),'FullControl','ContainerInherit,ObjectInherit','None','Allow')
        $Acl.AddAccessRule($Rule)
    }
    $User = [Security.Principal.WindowsIdentity]::GetCurrent().User
    $Acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($User,'FullControl','ContainerInherit,ObjectInherit','None','Allow'))
    if ($InstallService) {
        $Acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new('S-1-5-19'),'Modify','ContainerInherit,ObjectInherit','None','Allow'))
    }
    Set-Acl -LiteralPath $Directory -AclObject $Acl
}

function Grant-ServiceStorage([string]$Directory) {
    $Acl = Get-Acl -LiteralPath $Directory
    $Acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new('S-1-5-19'),'Modify','ContainerInherit,ObjectInherit','None','Allow'))
    Set-Acl -LiteralPath $Directory -AclObject $Acl
}

try {
    if ($Mode -eq 'Prepare') {
        if (-not $Elevated) { throw 'Service installation requires an administrator.' }
        Stop-OwnedService | Out-Null
        exit 0
    }
    if ($Mode -eq 'Remove') {
        if (-not $Elevated) { throw 'Service removal requires an administrator.' }
        $Service = Stop-OwnedService
        if ($Service) { & $Wrapper uninstall; if ($LASTEXITCODE -ne 0) { throw 'Windows service removal failed.' } }
        exit 0
    }
    if ($InstallService -and -not $Elevated) { throw 'Run Setup as administrator to register the Windows service.' }
    if (-not $StateDirectory) { throw 'StateDirectory is required.' }
    Protect-State $StateDirectory
    $Arguments = @((Join-Path $AppDirectory 'scripts\configure-service.js'),'--app-dir',$AppDirectory,'--state-dir',$StateDirectory,'--port',"$Port",'--host',$BindAddress,'--platform','win32')
    if ($StorageRoot) { $Arguments += @('--storage-root',$StorageRoot) }
    if ($RequireApiKey) { $Arguments += '--require-key' }
    & (Join-Path $AppDirectory 'runtime\node\node.exe') @Arguments
    if ($LASTEXITCODE -ne 0) { throw 'Service configuration failed. Check the selected paths and settings.' }
    $Configuration = Get-Content -LiteralPath (Join-Path $AppDirectory 'installation.json') -Raw | ConvertFrom-Json
    if ($InstallService) {
        foreach ($Directory in @($Configuration.storageRoot, (Split-Path $Configuration.catalogPath -Parent))) { Grant-ServiceStorage $Directory }
        $Address = if ($Configuration.host -eq 'localhost') { [Net.IPAddress]::Loopback } else { [Net.IPAddress]::Parse($Configuration.host) }
        $Listener = [Net.Sockets.TcpListener]::new($Address, $Configuration.port)
        try { $Listener.Start() } finally { $Listener.Stop() }
        $Service = Get-OwnedService
        if (-not $Service) { & $Wrapper install; if ($LASTEXITCODE -ne 0) { throw 'Windows service registration failed.' } }
        & $Wrapper start
        if ($LASTEXITCODE -ne 0) { throw 'Windows service startup failed. Inspect the logs in the state directory.' }
    }
    Write-Output 'Installation configured. Configuration, catalog, and terrain files are preserved by uninstall.'
    exit 0
} catch {
    Write-Error $_.Exception.Message -ErrorAction Continue
    exit 1
}

import path from 'node:path';
import net from 'node:net';
import assert from 'node:assert/strict';
import { fileURLToPath,pathToFileURL } from 'node:url';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { randomBytes } from 'node:crypto';
import { parseArgs } from 'node:util';
import { mkdir,mkdtemp,readFile,writeFile,access,rm } from 'node:fs/promises';
import { writeArrayBuffer } from 'geotiff';
import dotenv from 'dotenv';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
function run(executable,args,options={}){return new Promise((resolve,reject)=>{const child=spawn(executable,args,{cwd:root,windowsHide:true,stdio:'pipe',...options});let output='';child.stdout.on('data',data=>{output+=data;});child.stderr.on('data',data=>{output+=data;});child.once('error',reject);child.once('exit',code=>code===0?resolve(output):reject(new Error(`${path.basename(executable)} exited ${code}: ${output}`)));});}
async function freePort(){const server=net.createServer();server.listen(0,'127.0.0.1');await once(server,'listening');const port=server.address().port;await new Promise(resolve=>server.close(resolve));return port;}
async function start(appDir,envPath){
  const child=spawn(path.join(appDir,'runtime/node/node.exe'),[path.join(appDir,'src/server.js')],{cwd:appDir,env:{...process.env,TERRAIN_CONFIG_PATH:envPath},windowsHide:true,stdio:'pipe'});let output='';
  await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(new Error(`Packaged startup timeout: ${output}`)),30000);const consume=data=>{output+=data;if(output.includes('TerrainServer ready at')){clearTimeout(timeout);resolve();}};child.stdout.on('data',consume);child.stderr.on('data',consume);child.once('error',error=>{clearTimeout(timeout);reject(error);});child.once('exit',code=>{clearTimeout(timeout);reject(new Error(`Packaged server exited ${code}: ${output}`));});});return child;
}
async function stop(child){if(!child||child.exitCode!==null)return;const exited=once(child,'exit');child.kill('SIGTERM');await exited;}
async function json(base,pathname,key){const response=await fetch(base+pathname,{headers:key?{Authorization:`Bearer ${key}`}:{},signal:AbortSignal.timeout(30000)});assert.equal(response.status,200,`${pathname}: ${await response.clone().text()}`);return response.json();}

async function main(){
  if(process.platform!=='win32')throw new Error('The Windows setup integration test requires Windows.');
  const {values:argumentsValues}=parseArgs({options:{'gis-env':{type:'string'}}});
  const localConfig=dotenv.parse(await readFile(path.join(root,'.env'),'utf8').catch(()=>''));
  const gisEnv=argumentsValues['gis-env']||process.env.GIS_ENV_ROOT||localConfig.GIS_ENV_ROOT;
  if(!gisEnv)throw new Error('Supply --gis-env or configure GIS_ENV_ROOT for a fresh installer build.');
  console.log('Building a fresh Windows payload before installer integration validation.');
  await run(process.execPath,[path.join(root,'scripts/build-installer.js'),'--gis-env',gisEnv]);
  const stage=path.join(root,'build/staging/windows-x64');await access(path.join(stage,'runtime/node/node.exe'));
  const {version}=JSON.parse(await readFile(path.join(root,'package.json'),'utf8'));
  const testRoot=await mkdtemp(path.join(root,'build/installer-check-'));
  const appDir=path.join(testRoot,'test program'),stateDir=path.join(testRoot,'state'),storageRoot=path.join(testRoot,'terrain files');
  const compiler=process.env.ISCC_PATH||path.join(process.env.LOCALAPPDATA,'Programs/Inno Setup 6/ISCC.exe');
  await run(compiler,['/Qp','/DVerificationBuild',`/DStageDir=${stage}`,`/DOutputDir=${testRoot}`,`/DAppVersion=${version}`,path.join(root,'installer/windows/setup.iss')]);
  const setup=path.join(testRoot,`TerrainServer-InstallerVerification-${version}-windows-x64-setup.exe`);
  const port=await freePort();const args=['/CURRENTUSER','/VERYSILENT','/SUPPRESSMSGBOXES','/NORESTART',`/DIR=${appDir}`,`/STATEDIR=${stateDir}`,`/STORAGEROOT=${storageRoot}`,`/PORT=${port}`,'/BIND=127.0.0.1',`/LOG=${path.join(testRoot,'install.log')}`];
  let child;
  try{
    console.log('Installing an isolated verification build in current-user mode (no Windows service registration).');
    await run(setup,args);
    const installation=JSON.parse(await readFile(path.join(appDir,'installation.json'),'utf8'));assert.equal(installation.port,port);assert.equal(installation.storageRoot,storageRoot);assert.equal(installation.preserved,false);
    const envPath=path.join(stateDir,'.env');const node=path.join(appDir,'runtime/node/node.exe');
    const bytes=Buffer.from(writeArrayBuffer(Array.from({length:100},()=>100),{width:10,height:10,BitsPerSample:[8],SampleFormat:[1],ModelPixelScale:[0.001,0.001,0],ModelTiepoint:[0,0,0,-79.5,43.6,0],GeographicTypeGeoKey:4326,GTModelTypeGeoKey:2,GTRasterTypeGeoKey:1}));
    const filename=path.join(storageRoot,'fixture.tif');await writeFile(filename,bytes);
    const seed=`import {Catalog} from ${JSON.stringify(pathToFileURL(path.join(appDir,'src/catalog.js')).href)};const catalog=new Catalog(${JSON.stringify(installation.catalogPath)});const asset=catalog.saveAsset({sourceId:'ontario',title:'Installer fixture',product:'dtm',extension:'tif',path:${JSON.stringify(filename)},bbox:[-79.5,43.59,-79.49,43.6],resolutionMeters:1,bytes:${bytes.length},sha256:'fixture-hash'});console.log(asset.id);catalog.close();`;
    const seeded=await run(node,['--input-type=module','-e',seed],{cwd:appDir});const assetId=seeded.match(/^[a-f0-9]{32}$/m)?.[0];assert.ok(assetId,seeded);
    child=await start(appDir,envPath);const base=`http://127.0.0.1:${port}`;
    assert.equal((await json(base,'/api/health')).status,'ok');const tools=await json(base,'/api/tools');assert.ok(tools.rasterReady&&tools.pointCloudReady);
    const elevation=await json(base,'/api/terrain/elevation?longitude=-79.4995&latitude=43.5995');assert.equal(elevation.points[0].elevation,100);
    const grid=await json(base,`/api/terrain/grid?assetId=${assetId}&width=16&height=16`);assert.equal(grid.values.length,256);
    const range=await fetch(`${base}/api/assets/${assetId}/download.tif`,{headers:{Range:'bytes=0-7'}});assert.equal(range.status,206);assert.equal((await range.arrayBuffer()).byteLength,8);
    await stop(child);child=null;
    const gis=path.join(appDir,'runtime/gis');const env={...process.env,PATH:[path.join(gis,'Library/bin'),gis,path.join(process.env.SystemRoot,'System32')].join(path.delimiter),GDAL_DATA:path.join(gis,'Library/share/gdal'),PROJ_DATA:path.join(gis,'Library/share/proj'),PROJ_LIB:path.join(gis,'Library/share/proj'),PROJ_NETWORK:'OFF'};
    const csv=path.join(stateDir,'points.csv'),cloud=path.join(storageRoot,'fixture.laz');await writeFile(csv,'X,Y,Z,Classification\n620000,4840000,100,2\n620000.5,4840000,101,2\n620000,4840000.5,102,2\n620000.5,4840000.5,103,2\n620000.25,4840000.25,110,5\n');
    const pipelineFile=path.join(stateDir,'pipeline.json');await writeFile(pipelineFile,JSON.stringify({pipeline:[{type:'readers.text',filename:csv},{type:'writers.las',filename:cloud,compression:'laszip',a_srs:'EPSG:32617',minor_version:4}]}));
    await run(path.join(gis,'Library/bin/pdal.exe'),['pipeline',pipelineFile],{env});await run(path.join(gis,'Library/bin/pdal.exe'),['info','--summary',cloud],{env});
    await run(path.join(gis,'Library/bin/gdal_translate.exe'),['-of','GTiff',filename,path.join(storageRoot,'converted.tif')],{env});
    console.log('Packaged Node/SQLite/Sharp, GDAL/PDAL, LAZ generation, elevation, grids, and Range downloads passed.');
    const customPort=await freePort(),key=randomBytes(32).toString('hex');const values=dotenv.parse(await readFile(envPath,'utf8'));values.PORT=String(customPort);values.API_KEY=key;values.CUSTOM_SETTING='preserve me';
    await writeFile(envPath,Object.entries(values).map(([name,value])=>`${name}=${JSON.stringify(value)}`).join('\n')+'\n');
    await run(setup,[...args.filter(value=>!value.startsWith('/PORT=')&&!value.startsWith('/LOG=')),'/PORT=3123',`/LOG=${path.join(testRoot,'upgrade.log')}`]);
    const upgraded=dotenv.parse(await readFile(envPath,'utf8'));assert.equal(upgraded.PORT,String(customPort));assert.equal(upgraded.API_KEY,key);assert.equal(upgraded.CUSTOM_SETTING,'preserve me');assert.deepEqual(await readFile(filename),bytes);
    child=await start(appDir,envPath);const nextBase=`http://127.0.0.1:${customPort}`;assert.equal((await fetch(nextBase+'/api/settings')).status,401);assert.equal((await json(nextBase,'/api/settings',key)).storageRoot,storageRoot);assert.equal((await json(nextBase,'/api/terrain/elevation?longitude=-79.4995&latitude=43.5995',key)).points[0].elevation,100);await stop(child);child=null;
    await run(path.join(appDir,'unins000.exe'),['/VERYSILENT','/SUPPRESSMSGBOXES','/NORESTART',`/LOG=${path.join(testRoot,'uninstall.log')}`]);
    assert.equal(await access(path.join(appDir,'src/server.js')).then(()=>true,()=>false),false);assert.equal(await access(envPath).then(()=>true,()=>false),true);assert.deepEqual(await readFile(filename),bytes);await access(installation.catalogPath);
    console.log('Real setup upgrade preserves port, API key, custom settings, catalog, and raw files; uninstall preserves persistent state and terrain data.');
    const registry="HKCU:\\Software\\TerrainServerInstallerVerification";
    await run('powershell.exe',['-NoProfile','-Command',`$key='${registry}';if((Get-ItemPropertyValue -LiteralPath $key -Name StateDirectory -ErrorAction SilentlyContinue) -eq '${stateDir.replaceAll("'","''")}'){Remove-ItemProperty -LiteralPath $key -Name StateDirectory -ErrorAction SilentlyContinue}`]);
    await rm(testRoot,{recursive:true,force:true});
  }catch(error){console.error(`Installer test artifacts retained for diagnosis: ${testRoot}`);throw error;}finally{await stop(child);}
}
main().catch(error=>{console.error(error.stack);process.exitCode=1;});

param(
    [ValidateSet('Prepare','Configure','Remove')][string]$Mode = 'Configure',
    [Parameter(Mandatory=$true)][string]$AppDirectory,
    [string]$StateDirectory,
    [string]$StorageRoot,
    [int]$Port = 3123,
    [string]$BindAddress = '127.0.0.1',
    [switch]$RequireApiKey,
    [switch]$InstallService
)
$ErrorActionPreference = 'Stop'
$env:PSModulePath = [IO.Path]::Combine($PSHOME, 'Modules')
$AppDirectory = [IO.Path]::GetFullPath($AppDirectory).TrimEnd('\')
$Wrapper = Join-Path $AppDirectory 'TerrainServerService.exe'
$Principal = [Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())
$Elevated = $Principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

function Get-OwnedService {
    $Service = Get-CimInstance Win32_Service -Filter "Name='TerrainServer'" -ErrorAction Stop
    if ($Service) {
        $Match = [regex]::Match($Service.PathName, '^(?:"([^"]+)"|(\S+))')
        $Binary = if ($Match.Groups[1].Success) { $Match.Groups[1].Value } else { $Match.Groups[2].Value }
        if (-not [string]::Equals([IO.Path]::GetFullPath($Binary), $Wrapper, [StringComparison]::OrdinalIgnoreCase)) {
            throw 'A TerrainServer service belongs to another installation. Upgrade that installation in place or remove its service explicitly.'
        }
    }
    return $Service
}

function Stop-OwnedService {
    $Service = Get-OwnedService
    if ($Service -and $Service.State -ne 'Stopped') {
        Stop-Service -Name TerrainServer -ErrorAction Stop
        (Get-Service TerrainServer).WaitForStatus('Stopped', [TimeSpan]::FromSeconds(60))
    }
    return $Service
}

function Protect-State([string]$Directory) {
    $Directory = [IO.Path]::GetFullPath($Directory).TrimEnd('\')
    if ($Directory -eq [IO.Path]::GetPathRoot($Directory).TrimEnd('\') -or $Directory -eq $AppDirectory -or $Directory.StartsWith($AppDirectory+'\', [StringComparison]::OrdinalIgnoreCase)) {
        throw 'Choose a dedicated state directory outside the program directory, not a volume root.'
    }
    [IO.Directory]::CreateDirectory($Directory) | Out-Null
    $Acl = [Security.AccessControl.DirectorySecurity]::new($Directory, [Security.AccessControl.AccessControlSections]::Access)
    $Acl.SetAccessRuleProtection($true, $false)
    foreach ($Sid in @('S-1-5-18','S-1-5-32-544')) {
        $Rule = [Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new($Sid),'FullControl','ContainerInherit,ObjectInherit','None','Allow')
        $Acl.AddAccessRule($Rule)
    }
    $User = [Security.Principal.WindowsIdentity]::GetCurrent().User
    $Acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($User,'FullControl','ContainerInherit,ObjectInherit','None','Allow'))
    if ($InstallService) {
        $Acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new('S-1-5-19'),'Modify','ContainerInherit,ObjectInherit','None','Allow'))
    }
    [IO.Directory]::SetAccessControl($Directory, $Acl)
