  for(const tool of nativeTools){const result=await run(path.join(gis,windows?'Library/bin':'bin',`${tool}${windows?'.exe':''}`),['--version'],{env,capture:true,allowFailure:true});if(!/GDAL \d|PDAL \d|pdal \d/i.test(result.stdout+'\n'+result.stderr))throw new Error(`Bundled ${tool} cannot start: ${result.stderr||result.stdout}`);console.log(`${tool}: ${(result.stdout+' '+result.stderr).match(/(?:GDAL|pdal|PDAL) [^\r\n]+/)?.[0]}`);}
  if(windows){const parsed=await run('powershell.exe',['-NoProfile','-Command',`$errors=$null;[System.Management.Automation.Language.Parser]::ParseFile('${path.join(stage,'installer/windows/service.ps1').replaceAll("'","''")}',[ref]$null,[ref]$errors)|Out-Null;if($errors.Count){$errors|ForEach-Object{Write-Error $_.Message};exit 1}`],{capture:true});if(parsed.code)throw new Error(parsed.stderr);}
  else for(const filename of ['install.sh','uninstall.sh','setup-header.sh'])await run('bash',['-n',path.join(stage,'installer/linux',filename)],{capture:true});
