async function main(){
  if(!['win32','linux'].includes(values.platform)||process.platform!==values.platform||process.arch!=='x64')throw new Error('Build Windows/x64 on Windows, or Linux/x64 on Linux.');
  const packageJson=JSON.parse(await readFile(path.join(root,'package.json'),'utf8'));
  const stage=path.join(buildRoot,'staging',targetLabel);await rm(stage,{recursive:true,force:true});await mkdir(stage,{recursive:true});await mkdir(output,{recursive:true});
  for(const directory of ['src','public','installer'])await cp(path.join(root,directory),path.join(stage,directory),{recursive:true});
  await mkdir(path.join(stage,'scripts'));await copyFile(path.join(root,'scripts/configure-service.js'),path.join(stage,'scripts/configure-service.js'));
  for(const filename of ['package.json','package-lock.json','.env.example','README.md'])await copyFile(path.join(root,filename),path.join(stage,filename));
  const npmCli=process.env.npm_execpath||(windows?path.join(path.dirname(process.execPath),'node_modules/npm/bin/npm-cli.js'):path.resolve(path.dirname(process.execPath),'../lib/node_modules/npm/bin/npm-cli.js'));
