  else{
    const payload=path.join(buildRoot,`terrainserver-${packageJson.version}-payload.tar.gz`);await run('tar',['-czf',payload,'-C',stage,'.']);setup=path.join(output,`TerrainServer-${packageJson.version}-linux-x64-setup.run`);
    await writeFile(setup,(await readFile(path.join(root,'installer/linux/setup-header.sh'),'utf8')).replaceAll('\r\n','\n').trimEnd()+'\n');await pipeline(createReadStream(payload),createWriteStream(setup,{flags:'a',mode:0o755}));
