  if(action==='course-map'){setView('acquire');$('#area-course').value=id;return chooseArea(id);}if(action==='course-assets'){$('#local-course').value=id;state.localOffset=0;return setView('repository');}if(action==='course-process')return openProcessing(id);if(action==='course-package')return exportPackage(id);
