  $('#auth-button').addEventListener('click',()=>openDialog('#auth-dialog'));$('#auth-form').addEventListener('submit',run(async()=>{state.apiKey=$('#api-key').value;await initializeData();$('#api-key').value='';closeDialog('#auth-dialog');}));
  $('#save-course-button').addEventListener('click',openCourse);$('#new-course').addEventListener('click',openCourse);$('#course-form').addEventListener('submit',run(saveCourse));$('#processing-form').addEventListener('submit',run(processTerrain));
  $('#asset-json-button').addEventListener('click',()=>{$('#asset-json').hidden=!$('#asset-json').hidden;});$('#asset-download-button').addEventListener('click',run(()=>downloadAsset(state.asset.id)));$('#asset-map-button').addEventListener('click',run(()=>mapAsset(state.asset.id)));
  $('#register-source').addEventListener('click',()=>{$('#source-json').value=JSON.stringify({id:'government-index',name:'Government terrain index',adapter:'arcgis',country:'CA',coverageBbox:[-141,41.5,-52,84],license:{title:'Provider open licence',url:'https://open.canada.ca/en/open-government-licence-canada'},collections:[{id:'terrain-tiles',name:'Terrain tiles',products:['dtm'],formats:['tif'],endpoint:'https://services.arcgis.com/ORG/arcgis/rest/services/Terrain/FeatureServer/0',urlFields:['downloadUrl']}]},null,2);openDialog('#source-dialog');});$('#source-form').addEventListener('submit',run(async()=>{await api('/api/sources',{method:'POST',body:JSON.parse($('#source-json').value)});await loadSources();closeDialog('#source-dialog');toast('Source registered');}));
