async function initializeData() { await refreshSettings();await loadSources();await loadCourses();await loadLand();await loadFootprints();await pollJobs();const id=localStorage.getItem('terrain.lastPlan');if(id&&!state.plan)try{await loadPlan(id);}catch(error){if(error.status===404)localStorage.removeItem('terrain.lastPlan');else throw error;} }
