  const manifest=(request,response)=>{const options=optionsFor(request);const result=page(catalog.queryAssets({...options,resolution:options.resolution||'best'}).filter(elevationInput),request.query);response.json({...result,assets:result.assets.map(asset=>publicAsset(request,asset)),localOnly:true});};
  app.get('/api/scorecarder/manifest',manifest);app.post('/api/scorecarder/manifest',manifest);
  app.get('/api/scorecarder/query',(request,response)=>{
    let extent;if(request.query.geometry){let geometry;try{geometry=JSON.parse(request.query.geometry);}catch{throw new HttpError(400,'geometry must be an ArcGIS envelope JSON.');}extent=parseBbox({minX:geometry.xmin,minY:geometry.ymin,maxX:geometry.xmax,maxY:geometry.ymax});}else if(request.query.bbox)extent=parseBbox(request.query.bbox);
