  const network=new Network(config);const gis=new Gis(config);const indexes=new VectorIndexes(config,network,gis);const registry=new SourceRegistry(config,catalog,network,indexes);
  const processor=new TerrainProcessor(config,catalog,gis);const jobs=new JobManager(config,catalog,network,registry,processor);const reader=new TerrainReader(catalog,gis);
  const app=express();const tickets=new Map();
  app.disable('x-powered-by');
  app.use(helmet({contentSecurityPolicy:{directives:{'default-src':["'self'"],'script-src':["'self'"],'style-src':["'self'","'unsafe-inline'"],'font-src':["'self'"],'img-src':["'self'",'data:','blob:','https://*.tile.openstreetmap.org'],
    'connect-src':["'self'"],'object-src':["'none'"],'upgrade-insecure-requests':null}},crossOriginResourcePolicy:{policy:'cross-origin'}}));
  app.use((request,response,next)=>{
    if(['localhost','127.0.0.1','::1'].includes(config.host)&&!['localhost','127.0.0.1','::1','[::1]'].includes(request.hostname))return next(new HttpError(403,'Untrusted Host header.'));
    const origin=request.get('origin');if(origin&&!config.corsOrigins.includes(origin))return next(new HttpError(403,'Origin is not allowed. Add the consumer origin to CORS_ORIGINS in .env.'));next();
  });
  app.use(cors({origin:config.corsOrigins,exposedHeaders:['Content-Length','Content-Range','ETag','Accept-Ranges']}));
  app.use(express.json({limit:'5mb'}));
  app.get('/api/health',(request,response)=>response.json({status:'ok',service:'TerrainServer',version:'1.0.0',port:config.port,localTerrainOnly:true}));
  app.use('/api',(request,response,next)=>{
    if(!config.apiKey||request.method==='OPTIONS'||request.path==='/openapi.json'||/^\/downloads\/[a-f0-9]{48}\//.test(request.path))return next();
    const supplied=(request.get('authorization')||'').replace(/^Bearer\s+/i,'');const expected=Buffer.from(config.apiKey);const actual=Buffer.from(supplied);
    if(actual.length!==expected.length||!timingSafeEqual(actual,expected))return next(new HttpError(401,'API key required. Send Authorization: Bearer <API_KEY>.'));next();
  });
  const base=request=>`${request.protocol}://${request.get('host')}`;
  const urlFor=(request,asset)=>`${base(request)}/api/assets/${asset.id}/download.${asset.extension||'bin'}`;
  const publicAsset=(request,asset)=>{
    if(!asset)return null;const {path:filename,...data}=asset;
