      bounds:asset.bbox,bbox:{minLng:asset.bbox[0],minLat:asset.bbox[1],maxLng:asset.bbox[2],maxLat:asset.bbox[3]},cellSizeMeters:asset.effectiveCellSizeMeters||asset.resolutionMeters,
      previewUrl:asset.downloaded&&['tif','tiff'].includes(asset.extension)?`${base(request)}/api/assets/${asset.id}/preview.png`:null};
  };
  const optionsFor=request=>{
    const input=request.method==='GET'?request.query:request.body;const result={...input,sourceIds:list(input.sourceIds||input.sources),products:list(input.products),formats:list(input.formats),collectionIds:list(input.collectionIds),localOnly:true};
    if(result.sourceIds)result.sourceIds=result.sourceIds.map(id=>registry.get(id).id);
    if(input.bufferMeters!=null)result.bufferMeters=Number(input.bufferMeters);
    if(input.boundary||input.bbox)normalizeBoundary(result);
    return result;
  };
  const page=(assets,input={})=>{const offset=Number(input.offset||input.token||0);const limit=Number(input.limit||100);
    if(!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1||limit>1000)throw new HttpError(400,'offset must be nonnegative and limit must be between 1 and 1000.');
    return {total:assets.length,offset,limit,nextOffset:offset+limit<assets.length?offset+limit:null,assets:assets.slice(offset,offset+limit)};};
  const queue=(type,request,response,payload=request.body)=>{const parsed=bodySchema.parse(payload||{});if(parsed.sourceIds)parsed.sourceIds=parsed.sourceIds.map(id=>registry.get(id).id);const job=jobs.enqueue(type,parsed);response.status(202).json({...job,statusUrl:`${base(request)}/api/jobs/${job.id}`});};
  const courseFor=id=>{const course=catalog.course(id);if(!course)throw new HttpError(404,'Course not found.');return course;};
  const terrainFor=(request,id)=>{
    const course=courseFor(id);const assets=catalog.queryAssets({courseId:id,localOnly:true,resolution:'all'}).sort((left,right)=>(left.sourceId==='derived'?0:1)-(right.sourceId==='derived'?0:1)||String(right.generatedAt||right.downloadedAt||'').localeCompare(String(left.generatedAt||left.downloadedAt||'')));
    const first=product=>assets.find(asset=>asset.product===product);const dem=first('dtm')||first('dem');const contours=assets.find(asset=>asset.product==='contours'&&asset.contourIntervalMeters===1)||first('contours');
    return {course,dem:dem?urlFor(request,dem):null,dtm:first('dtm')?urlFor(request,first('dtm')):null,dsm:first('dsm')?urlFor(request,first('dsm')):null,
      contours:contours?urlFor(request,contours):null,hillshade:first('hillshade')?urlFor(request,first('hillshade')):null,slope:first('slope')?urlFor(request,first('slope')):null,
