    stats:catalog.stats(),disk:disk?{freeBytes:Number(disk.bavail)*Number(disk.bsize),totalBytes:Number(disk.blocks)*Number(disk.bsize)}:null,
    limits:{maxDiscoveryAssets:config.maxDiscoveryAssets,maxProcessingPixels:config.maxProcessingPixels,maxExportPixels:config.maxExportPixels},downloadConcurrency:config.downloadConcurrency,defaultBufferMeters:config.defaultBufferMeters,updateCheckDays:config.updateCheckDays,lastUpdateCheck:catalog.setting('lastUpdateCheck')||null,apiKeyRequired:!!config.apiKey});});
  app.patch('/api/settings',async(request,response)=>{if(jobs.active)throw new HttpError(409,'Wait for the active job to finish or cancel it before changing the default storage root.');const root=await persistStorageRoot(config,request.body.storageRoot);catalog.registerRoot(root);response.json({storageRoot:root,previousFilesPreserved:true});});
  app.get('/api/storage/directories',async(request,response)=>{const directory=request.query.path?path.resolve(String(request.query.path)):config.storageRoot;const entries=await readdir(directory,{withFileTypes:true});
    const drives=process.platform==='win32'?(await Promise.all('CDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(async letter=>await stat(`${letter}:/`).then(()=>`${letter}:/`).catch(()=>null)))).filter(Boolean):['/'];
    response.json({path:directory,parent:path.dirname(directory),drives,directories:entries.filter(entry=>entry.isDirectory()).map(entry=>({name:entry.name,path:path.join(directory,entry.name)})).sort((left,right)=>left.name.localeCompare(right.name))});});
  app.get('/api/tools',async(request,response)=>response.json(await gis.check()));
  app.get('/api/sources',(request,response)=>response.json({sources:registry.list(),localOnly:true}));
  app.get('/api/sources/:id',(request,response)=>{const source=registry.get(request.params.id);response.json({...source,options:registry.options(source)});});
  app.get('/api/sources/:id/options',(request,response)=>response.json(registry.options(registry.get(request.params.id))));
  app.post('/api/sources',(request,response)=>response.status(201).json(registry.register(request.body)));
  const queryAssets=(request,response,extra={})=>{const options={...optionsFor(request),...extra};const result=page(catalog.queryAssets(options),request.method==='GET'?request.query:request.body);response.json({...result,assets:result.assets.map(asset=>publicAsset(request,asset)),localOnly:true});};
