    properties:{datetime:asset.providerMetadata?.datetime||asset.generatedAt||asset.downloadedAt,gsd:asset.effectiveCellSizeMeters||asset.resolutionMeters,'terrain:native_resolution_m':asset.nativeResolutionMeters||asset.resolutionMeters,'terrain:product':asset.product,'terrain:vertical_datum':asset.verticalDatum||'As published','proj:epsg':asset.crs?Number(asset.crs.split(':')[1]):null},
    assets:{data:{href:urlFor(request,asset),type:asset.mediaType||(['tif','tiff'].includes(asset.extension)?'image/tiff; application=geotiff':'application/octet-stream'),roles:['data'],'file:size':asset.bytes}},links:[{rel:'self',href:`${base(request)}${stacPrefix(request)}/items/${asset.id}`}]});
  const stacSearch=(request,response)=>{const input=request.method==='GET'?request.query:request.body;const collections=list(input.collections);const sourceIds=collections?.filter(id=>catalog.source(id));const collectionIds=collections?.filter(id=>!catalog.source(id));
    const options={...optionsFor(request),...(sourceIds?.length?{sourceIds}:{}),...(collectionIds?.length?{collectionIds}:{}),...(input.intersects?{boundary:input.intersects}:{}),resolution:input.resolution||'all'};
    const result=page(stacAssets(request,options),input);const next=result.nextOffset!=null?{rel:'next',href:`${base(request)}${stacPrefix(request)}/search`,method:'POST',body:{...input,token:result.nextOffset}}:null;
    response.json({type:'FeatureCollection',features:result.assets.map(asset=>stacItem(request,asset)),numberMatched:result.total,numberReturned:result.assets.length,links:next?[next]:[],context:{matched:result.total,returned:result.assets.length},localOnly:true});};
  app.get(['/api/stac','/api/scorecarder/stac'],(request,response)=>response.json({type:'Catalog',id:'terrainserver',stac_version:'1.0.0',description:stacPrefix(request)==='/api/scorecarder/stac'?'Locally acquired elevation rasters and point clouds':'Locally acquired government terrain',links:[{rel:'self',href:`${base(request)}${stacPrefix(request)}`},{rel:'data',href:`${base(request)}${stacPrefix(request)}/collections`},{rel:'search',href:`${base(request)}${stacPrefix(request)}/search`,method:'POST'}],conformsTo:['https://api.stacspec.org/v1.0.0/core','https://api.stacspec.org/v1.0.0/item-search']}));
