    const grid=await service.reader.grid(asset,{width:16,height:16});assert.equal(grid.min,100);assert.equal(grid.max,100);assert.equal(grid.overviewUsed,true);assert.equal(grid.sourcePixelsRead,256);
    const elevation=await service.reader.sample(asset,[[-79.49,43.59]]);assert.deepEqual(elevation,[100]);
  }finally{await service.close();await rm(root,{recursive:true,force:true});}
});

