function progressBar(job) { return `<span class="progress-label">${escapeHtml(progressLabel(job))}</span><progress max="${job.progress.total||100}" ${job.progress.total||job.status==='completed'?`value="${job.status==='completed'?(job.progress.total||100):(job.progress.completed||0)}"`:''}></progress>`; }
function renderJobs() {
  $('#job-rows').innerHTML=state.jobs.map(job=>`<tr><td><span class="file-title">${escapeHtml(job.type.charAt(0).toUpperCase()+job.type.slice(1))}</span><span class="file-subtitle">${escapeHtml(job.payload.courseId||job.payload.sourceIds?.map(sourceLabel).join(', ')||job.id.slice(0,8))}</span></td><td><span class="badge ${escapeHtml(job.status)}">${escapeHtml(job.status)}</span></td><td>${progressBar(job)}</td><td>${bytes(job.progress.bytes||0)}</td><td><span class="file-subtitle">${date(job.updatedAt)}</span></td><td class="action-cell"><div class="row-actions">${actionButton('job',job.id,'list','Job details')}${['queued','running'].includes(job.status)?actionButton('job-cancel',job.id,'square','Cancel job'):['failed','cancelled'].includes(job.status)?actionButton('job-retry',job.id,'rotate-ccw','Retry job'):job.progress.result?.planId?actionButton('job-plan',job.id,'scan-search','Review acquisition plan'):''}</div></td></tr>`).join('')||emptyRow(6,'No queued or completed jobs','activity');icons();
}
async function pollJobs() {
  if(state.polling||!state.settings)return;state.polling=true;
  try{
    state.jobs=(await api('/api/jobs')).jobs;renderJobs();$('#job-count').textContent=number(state.jobs.filter(job=>['running','queued'].includes(job.status)).length);
    for(const job of state.jobs){if(!state.watchJobs.has(job.id)||state.handledJobs.has(job.id)||!['completed','failed','cancelled'].includes(job.status))continue;state.handledJobs.add(job.id);if(job.progress.result?.planId)await loadPlan(job.progress.result.planId);await refreshSettings();await loadCourses();await loadFootprints();if(state.view==='repository')await loadLocal();if(job.status==='failed')toast(job.error,true);}
    if($('#job-dialog').open&&state.jobId)await renderJobDetails(state.jobId);
  }catch(error){if(error.status!==401){$('#connection-dot').className='status-dot offline';$('#connection-label').textContent='Disconnected';}}
  finally{state.polling=false;}
}
async function showJob(id) { state.jobId=id;$('#job-title').textContent='Loading Job';$('#job-detail').textContent='Loading';$('#job-logs').textContent='';$('#job-dialog-actions').replaceChildren();openDialog('#job-dialog');await renderJobDetails(id); }
async function renderJobDetails(id) {
  const job=state.jobs.find(item=>item.id===id)||await api(`/api/jobs/${id}`);const events=(await api(`/api/jobs/${id}/events`)).events;if(state.jobId!==id)return;$('#job-title').textContent=`${job.type.charAt(0).toUpperCase()+job.type.slice(1)} / ${job.id.slice(0,8)}`;
  $('#job-detail').innerHTML=`<dl class="detail-list"><dt>Status</dt><dd><span class="badge ${escapeHtml(job.status)}">${escapeHtml(job.status)}</span></dd><dt>Progress</dt><dd>${progressBar(job)}</dd><dt>Transferred</dt><dd>${bytes(job.progress.bytes||0)}</dd>${job.progress.reused!=null?`<dt>Reused Packages</dt><dd>${number(job.progress.reused)}</dd><dt>Resumed Packages</dt><dd>${number(job.progress.resumed||0)}</dd><dt>Existing Data Reused</dt><dd>${bytes(job.progress.existingBytes||0)}</dd>`:''}${job.payload.prepareForScorecarder?`<dt>Ready for Scorecarder</dt><dd>${number(job.progress.readyAssets||0)} files</dd>`:''}<dt>Destination</dt><dd>${escapeHtml(job.payload.storageRoot)}</dd></dl>${job.error?`<p class="job-error">${escapeHtml(job.error)}</p>`:''}`;
  const logs=$('#job-logs');const atBottom=logs.scrollTop+logs.clientHeight>=logs.scrollHeight-30;logs.textContent=events.map(event=>`${date(event.time)} [${event.level}] ${event.message}`).join('\n')||'Queued';if(atBottom)logs.scrollTop=logs.scrollHeight;
  $('#job-dialog-actions').innerHTML=`${job.progress.planId||job.progress.result?.planId?`<button type="button" class="button secondary" data-action="job-plan" data-id="${job.id}"><i data-lucide="scan-search"></i>Review Plan</button>`:''}${['queued','running'].includes(job.status)?`<button class="button danger" data-action="job-cancel" data-id="${job.id}"><i data-lucide="square"></i>Cancel Job</button>`:['failed','cancelled'].includes(job.status)?`<button class="button primary" data-action="job-retry" data-id="${job.id}"><i data-lucide="rotate-ccw"></i>Retry Job</button>`:''}`;icons();
}
async function showAsset(id) {
  const asset=state.assets.get(id)||await api(`/api/assets/${id}/metadata`);state.asset=asset;$('#asset-title').textContent=asset.title||asset.id;$('#asset-download-button').hidden=!asset.downloaded;$('#asset-json').hidden=true;$('#asset-json').textContent=JSON.stringify(asset,null,2);
  const values=[['Source',sourceLabel(asset.sourceId)],['Product',productNames[asset.product]||asset.product],['Native grid',asset.nativeResolutionMeters||asset.resolutionMeters?`${asset.nativeResolutionMeters||asset.resolutionMeters} m`:'Unknown'],['Output cell',asset.effectiveCellSizeMeters||asset.requestedResolutionMeters?`${asset.effectiveCellSizeMeters||asset.requestedResolutionMeters} m${asset.resampled?' (resampled)':''}`:'As published'],['Point density',asset.densityPointsPerSquareMeter?`${asset.densityPointsPerSquareMeter} points/m2`:'Not published'],['CRS',asset.crs||'As published'],['Vertical datum',asset.verticalDatum||'As published; no automatic vertical harmonization'],['Size',asset.bytes||asset.expectedBytes?bytes(asset.bytes||asset.expectedBytes):'Unknown'],['Bounds (WGS84)',asset.bounds.join(', ')],['License',asset.license?.title||'See source provenance'],['Local endpoint',asset.url||'Not downloaded']];
  $('#asset-details').innerHTML=values.map(([key,value])=>`<dt>${escapeHtml(key)}</dt><dd>${escapeHtml(value)}</dd>`).join('');const preview=$('#asset-preview');preview.hidden=!asset.previewUrl;preview.innerHTML='<span class="metadata-note">Rendering local raster</span>';openDialog('#asset-dialog');
  if(state.assetBlob){URL.revokeObjectURL(state.assetBlob);state.assetBlob=null;}
  if(asset.previewUrl){try{const blob=await api(`/api/assets/${asset.id}/preview.png?width=384&height=256`,{blob:true});if(state.asset?.id!==id)return;state.assetBlob=URL.createObjectURL(blob);const image=document.createElement('img');image.src=state.assetBlob;image.alt=`${asset.title||'Terrain'} raster preview`;preview.replaceChildren(image);}catch(error){preview.textContent=error.message;}}
}
async function downloadAsset(id) { const result=await api(`/api/assets/${id}/ticket`,{method:'POST',body:{}});const anchor=document.createElement('a');anchor.href=result.url;anchor.download='';document.body.append(anchor);anchor.click();anchor.remove(); }
async function mapAsset(id) {
  const asset=state.assets.get(id)||await api(`/api/assets/${id}/metadata`);closeDialog('#asset-dialog');setView('acquire');setBoundary(asset.geometry||featureForBbox(asset.bounds));if(state.mapPreview){state.mapPreview.remove();URL.revokeObjectURL(state.mapPreviewUrl);state.mapPreview=null;}
  if(asset.previewUrl){const blob=await api(`/api/assets/${id}/preview.png?width=512&height=512`,{blob:true});state.mapPreviewUrl=URL.createObjectURL(blob);state.mapPreview=L.imageOverlay(state.mapPreviewUrl,[[asset.bounds[1],asset.bounds[0]],[asset.bounds[3],asset.bounds[2]]],{pane:'terrain-preview',opacity:.9}).addTo(state.map);}
}
async function browseFolder(directory) {
  $('#folder-path').value=directory;$('#folder-error').textContent='';try{const result=await api(`/api/storage/directories?path=${encodeURIComponent(directory)}`);state.folderParent=result.parent;$('#folder-path').value=result.path;$('#folder-drive').innerHTML=result.drives.map(drive=>`<option value="${escapeHtml(drive)}">${escapeHtml(drive)}</option>`).join('');$('#folder-drive').value=result.drives.find(drive=>result.path.toLowerCase().startsWith(drive.toLowerCase().replaceAll('/','\\'))||result.path.toLowerCase().startsWith(drive.toLowerCase()))||result.drives[0];$('#folder-list').innerHTML=result.directories.map(item=>`<button class="folder-item" data-folder="${escapeHtml(item.path)}"><i data-lucide="folder"></i><span>${escapeHtml(item.name)}</span></button>`).join('')||'<div class="empty-cell">No subfolders</div>';$('#folder-up').disabled=result.path===result.parent;icons();}catch(error){$('#folder-error').textContent=error.message;$('#folder-list').innerHTML='<div class="empty-cell">Directory unavailable</div>';}
}
async function openFolder(target) { state.folderTarget=target;$('#folder-title').textContent=target==='default'?'Default Storage Destination':'Job Destination';openDialog('#folder-dialog');await browseFolder(target==='default'?state.settings.storageRoot:$('#job-destination').value); }
async function showSettings() {
  await refreshSettings();const settings=state.settings;const details=[['Default storage',settings.storageRoot],['Catalog',settings.catalogPath],['Registered roots',settings.storageRoots.join('\n')],['Download workers',settings.downloadConcurrency],['Discovery limit',number(settings.limits.maxDiscoveryAssets)],['Processing limit',`${number(settings.limits.maxProcessingPixels)} pixels`],['Provider update check',settings.updateCheckDays?`${settings.updateCheckDays} days`:'Disabled'],['Last check',date(settings.lastUpdateCheck)],['Authentication',settings.apiKeyRequired?'Bearer API key':'Loopback access']];$('#settings-details').innerHTML=details.map(([key,value])=>`<dt>${escapeHtml(key)}</dt><dd>${escapeHtml(value)}</dd>`).join('');openDialog('#settings-dialog');await checkTools();
}
async function checkTools() { $('#tool-list').textContent='Checking installed tools';const tools=await api('/api/tools');$('#tool-list').innerHTML=tools.tools.map(item=>`<div class="tool-row"><span><strong>${escapeHtml(item.name)}</strong><br>${escapeHtml(item.version||item.error||item.executable||'')}</span><span class="badge ${item.available?'completed':'failed'}">${item.available?'Ready':'Unavailable'}</span></div>`).join(''); }
function openCourse() { $('#course-buffer').value=$('#buffer').value;$('#course-boundary-status').textContent=state.boundary?`WGS84 ${state.boundary.geometry.type}`:'No boundary selected';openDialog('#course-dialog'); }
function openProcessing(courseId) { if(!state.courses.length)throw new Error('Save a course boundary before generating course-scoped terrain.');$('#processing-course').value=courseId||state.courses[0].id;openDialog('#processing-dialog'); }
async function saveCourse() {
  if(!state.boundary)throw new Error('A course requires a WGS84 polygon boundary.');const course=await api('/api/courses',{method:'POST',body:{name:$('#course-name').value,country:$('#course-country').value,province:$('#course-region').value,boundary:state.boundary,bufferMeters:Number($('#course-buffer').value)}});await loadCourses();$('#area-course').value=course.id;$('#buffer').value=course.bufferMeters;closeDialog('#course-dialog');toast(`Saved ${course.name}`);
}
async function processTerrain() {
  const products=$$('input[name="outputs"]:checked').map(input=>input.value);if(!products.length)throw new Error('Select at least one output.');const intervals=$$('input[name="intervals"]:checked').map(input=>Number(input.value));if($('#use-custom-interval').checked)intervals.push(Number($('#custom-interval').value));if(products.includes('contours')&&!intervals.length)throw new Error('Select a contour interval.');
  const payload={courseId:$('#processing-course').value,products,...($('#processing-resolution').value?{resolutionMeters:Number($('#processing-resolution').value)}:{}),...(intervals.length?{contourIntervals:[...new Set(intervals)]}:{}),resampling:$('#processing-resampling').value,groundOnly:$('#ground-only').checked,preferPointCloud:$('#prefer-point-cloud').checked,zScale:Number($('#z-scale').value),hillshadeStyle:$('#hillshade-style').value,slopeUnits:$('#slope-units').value};closeDialog('#processing-dialog');await queueJob('/api/jobs/process',payload);
}
async function exportPackage(courseId) { const document=await api(`/api/course/${courseId}/package`,{method:'POST',body:{}});const blob=new Blob([JSON.stringify(document,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);const anchor=window.document.createElement('a');anchor.href=url;anchor.download=`terrain-package-${courseId}.json`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Local terrain package exported'); }
async function importBoundary(file) { if(!file)return;if(file.size>5*1024*1024)throw new Error('Boundary exceeds the 5 MB request limit.');let document=JSON.parse(await file.text());if(document.type==='FeatureCollection'){const geometries=document.features.map(item=>item.geometry).filter(item=>['Polygon','MultiPolygon'].includes(item?.type));if(!geometries.length)throw new Error('GeoJSON has no Polygon or MultiPolygon.');document={type:'MultiPolygon',coordinates:geometries.flatMap(item=>item.type==='Polygon'?[item.coordinates]:item.coordinates)};}if(!['Polygon','MultiPolygon'].includes(document.geometry?.type||document.type))throw new Error('A Polygon or MultiPolygon GeoJSON boundary is required.');setBoundary(document);$('#area-course').value=''; }
async function handleAction(action,id) {
  if(action==='source-acquire')return confirmSourceAcquisition(id);
  if(action==='asset')return showAsset(id);if(action==='download')return downloadAsset(id);if(action==='asset-map')return mapAsset(id);
  if(action==='job')return showJob(id);if(action==='job-cancel'){await api(`/api/jobs/${id}/cancel`,{method:'POST',body:{}});return pollJobs();}if(action==='job-retry')return queueJob(`/api/jobs/${id}/retry`,{});
  if(action==='job-plan'){const job=state.jobs.find(item=>item.id===id)||await api(`/api/jobs/${id}`);closeDialog('#job-dialog');setView('acquire');return loadPlan(job.progress.planId||job.progress.result?.planId);}
  if(action==='course-map'){setView('acquire');$('#area-course').value=id;return chooseArea(id);}if(action==='course-assets'){$('#local-course').value=id;state.localOffset=0;return setView('repository');}if(action==='course-process')return openProcessing(id);if(action==='course-package')return exportPackage(id);
}
function bindEvents() {
  document.addEventListener('click',run(async event=>{const close=event.target.closest('[data-close]');if(close){close.closest('dialog').close();return;}const tab=event.target.closest('[data-view]');if(tab){setView(tab.dataset.view);return;}const button=event.target.closest('[data-action]');if(button)return handleAction(button.dataset.action,button.dataset.id);const folder=event.target.closest('[data-folder]');if(folder)return browseFolder(folder.dataset.folder);},false));
  $('#source-controls').addEventListener('change',event=>{const id=event.target.dataset.source;event.target.checked?state.sourceIds.add(id):state.sourceIds.delete(id);state.collections=null;renderSourceOptions();});
  $('#product-controls').addEventListener('change',event=>{const id=event.target.dataset.product;event.target.checked?state.products.add(id):state.products.delete(id);state.collections=null;renderSourceOptions();});
  $('#collection-controls').addEventListener('change',event=>{state.collections=new Set($$('[data-collection]:checked:not(:disabled)').map(input=>input.dataset.collection));$('#collection-count').textContent=`${state.collections.size} selected`;});
  $('#reset-collections').addEventListener('click',()=>{state.collections=null;renderSourceOptions();});$('#resolution').addEventListener('change',()=>{$('#custom-resolution-field').hidden=$('#resolution').value!=='custom';});
  $$('input[name="scope"]').forEach(input=>input.addEventListener('change',()=>{const whole=input.value==='source'&&input.checked;$('#boundary-controls').hidden=whole;$('#whole-source-note').hidden=!whole;if(whole){const bounds=L.latLngBounds(selectedSources().flatMap(source=>[[source.coverageBbox[1],source.coverageBbox[0]],[source.coverageBbox[3],source.coverageBbox[2]]]));if(bounds.isValid())state.map.fitBounds(bounds,{padding:[25,25]});}}));
  $('#area-course').addEventListener('change',run(event=>chooseArea(event.target.value)));$('#clear-boundary').addEventListener('click',()=>{setBoundary(null);$('#area-course').value='';});
  $$('.bbox-grid input').forEach(input=>input.addEventListener('change',run(()=>{const inputs=['west','south','east','north'].map(key=>$(`#bbox-${key}`));if(inputs.some(control=>control.value===''))return;const extent=inputs.map(control=>Number(control.value));if(!(extent[0]<extent[2]&&extent[1]<extent[3]))throw new Error('West must be less than east, and south less than north.');setBoundary(featureForBbox(extent));$('#area-course').value='';})));
  $('#fit-map').addEventListener('click',()=>{if(state.bbox)state.map.fitBounds([[state.bbox[1],state.bbox[0]],[state.bbox[3],state.bbox[2]]],{padding:[30,30],maxZoom:18});else if(state.localLayer.getBounds().isValid())state.map.fitBounds(state.localLayer.getBounds(),{padding:[30,30]});else state.map.setView([51,-101],3);});
  $('#basemap').addEventListener('change',()=>{if(state.streets){state.streets.remove();state.streets=null;}if($('#basemap').value==='streets')state.streets=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(state.map);});
  $('#import-boundary').addEventListener('click',()=>$('#boundary-file').click());$('#course-import').addEventListener('click',()=>$('#boundary-file').click());$('#boundary-file').addEventListener('change',run(async event=>{await importBoundary(event.target.files[0]);event.target.value='';}));
  $('#acquisition-form').addEventListener('submit',run(async()=>{const payload=acquisitionPayload();const button=$('#discover-button');button.disabled=true;try{await queueJob('/api/discover',payload);}finally{button.disabled=false;}}));
  $('#select-all-plan').addEventListener('change',event=>{state.selected=event.target.checked?new Set(state.plan?.assetIds||[]):new Set();renderPlanSelection();});$('#plan-rows').addEventListener('change',event=>{const id=event.target.dataset.selectAsset;if(id)setAssetSelection(id,event.target.checked);});
  $('#download-plan').addEventListener('click',run(confirmDownload));$('#confirm-form').addEventListener('submit',run(async()=>{closeDialog('#confirm-dialog');await state.confirm?.();}));
  $('#plan-previous').addEventListener('click',run(()=>loadPlan(state.plan.id,Math.max(0,state.planOffset-50),false)));$('#plan-next').addEventListener('click',run(()=>loadPlan(state.plan.id,state.planOffset+50,false)));
  $('#repository-filter').addEventListener('submit',run(()=>loadLocal(0)));$('#refresh-repository').addEventListener('click',run(async()=>{await refreshSettings();await loadLocal();}));$('#local-previous').addEventListener('click',run(()=>loadLocal(Math.max(0,state.localOffset-50))));$('#local-next').addEventListener('click',run(()=>loadLocal(state.localOffset+50)));
  $('#refresh-jobs').addEventListener('click',run(pollJobs));$('#check-updates').addEventListener('click',run(()=>queueJob('/api/jobs/updates',{})));$('#refresh-sources').addEventListener('click',run(()=>queueJob('/api/jobs/refresh',{sourceIds:[...state.sourceIds]})));
  $('#settings-button').addEventListener('click',run(showSettings));$('#check-tools').addEventListener('click',run(checkTools));$('#settings-folder').addEventListener('click',run(()=>{closeDialog('#settings-dialog');return openFolder('default');}));
  $('#default-folder-button').addEventListener('click',run(()=>openFolder('default')));$('#job-folder-button').addEventListener('click',run(()=>openFolder('job')));$('#folder-path-form').addEventListener('submit',run(()=>browseFolder($('#folder-path').value)));$('#folder-up').addEventListener('click',run(()=>browseFolder(state.folderParent)));$('#folder-drive').addEventListener('change',run(event=>browseFolder(event.target.value)));
  $('#job-destination').addEventListener('change',()=>localStorage.setItem('terrain.jobDestination',$('#job-destination').value));
  $('#use-folder').addEventListener('click',run(async()=>{const root=$('#folder-path').value;if(state.folderTarget==='default'){await api('/api/settings',{method:'PATCH',body:{storageRoot:root}});await refreshSettings();}$('#job-destination').value=root;localStorage.setItem('terrain.jobDestination',root);closeDialog('#folder-dialog');toast('Storage destination selected');}));
  $('#auth-button').addEventListener('click',()=>openDialog('#auth-dialog'));$('#auth-form').addEventListener('submit',run(async()=>{state.apiKey=$('#api-key').value;await initializeData();$('#api-key').value='';closeDialog('#auth-dialog');}));
  $('#save-course-button').addEventListener('click',openCourse);$('#new-course').addEventListener('click',openCourse);$('#course-form').addEventListener('submit',run(saveCourse));$('#processing-form').addEventListener('submit',run(processTerrain));
  $('#asset-json-button').addEventListener('click',()=>{$('#asset-json').hidden=!$('#asset-json').hidden;});$('#asset-download-button').addEventListener('click',run(()=>downloadAsset(state.asset.id)));$('#asset-map-button').addEventListener('click',run(()=>mapAsset(state.asset.id)));
  $('#register-source').addEventListener('click',()=>{$('#source-json').value=JSON.stringify({id:'government-index',name:'Government terrain index',adapter:'arcgis',country:'CA',coverageBbox:[-141,41.5,-52,84],license:{title:'Provider open licence',url:'https://open.canada.ca/en/open-government-licence-canada'},collections:[{id:'terrain-tiles',name:'Terrain tiles',products:['dtm'],formats:['tif'],endpoint:'https://services.arcgis.com/ORG/arcgis/rest/services/Terrain/FeatureServer/0',urlFields:['downloadUrl']}]},null,2);openDialog('#source-dialog');});$('#source-form').addEventListener('submit',run(async()=>{await api('/api/sources',{method:'POST',body:JSON.parse($('#source-json').value)});await loadSources();closeDialog('#source-dialog');toast('Source registered');}));
}
async function initializeData() { await refreshSettings();await loadSources();await loadCourses();await loadLand();await loadFootprints();await pollJobs();const id=localStorage.getItem('terrain.lastPlan');if(id&&!state.plan)try{await loadPlan(id);}catch(error){if(error.status===404)localStorage.removeItem('terrain.lastPlan');else throw error;} }
async function start() { icons();initMap();bindEvents();try{await initializeData();}catch(error){$('#connection-dot').className='status-dot offline';$('#connection-label').textContent=error.status===401?'Authentication required':'Disconnected';if(error.status!==401)toast(error.message,true);}setInterval(()=>pollJobs(),2000); }
start();

@font-face { font-family: 'IBM Plex Sans'; font-style: normal; font-weight: 400; font-display: swap; src: url('/vendor/fonts/files/ibm-plex-sans-latin-400-normal.woff2') format('woff2'); }
@font-face { font-family: 'IBM Plex Sans'; font-style: normal; font-weight: 500; font-display: swap; src: url('/vendor/fonts/files/ibm-plex-sans-latin-500-normal.woff2') format('woff2'); }
@font-face { font-family: 'IBM Plex Sans'; font-style: normal; font-weight: 600; font-display: swap; src: url('/vendor/fonts/files/ibm-plex-sans-latin-600-normal.woff2') format('woff2'); }
:root { --ink: #222d2a; --muted: #6a7672; --line: #dce2de; --paper: #ffffff; --ground: #f5f7f6; --green: #206c5a; --green-hover: #175243; --green-tint: #eaf3ef; --gold: #b58521; --gold-tint: #fbf4df; --red: #a43834; --radius: 5px; }
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body { margin: 0; color: var(--ink); font: 14px/1.45 'IBM Plex Sans', sans-serif; letter-spacing: 0; background: var(--ground); }
button, input, select, textarea { font: inherit; letter-spacing: 0; }
button, a, input, select, textarea { -webkit-tap-highlight-color: transparent; }
button { cursor: pointer; }
button:disabled { cursor: default; opacity: .45; }
a { color: var(--green); text-decoration: none; }
a:hover { text-decoration: underline; }
button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, summary:focus-visible { outline: 2px solid var(--green); outline-offset: 3px; }
h2, h3, p { margin: 0; }
h2 { font-size: 20px; line-height: 1.25; font-weight: 500; }
h3 { font-size: 15px; font-weight: 500; }
svg { width: 18px; height: 18px; stroke-width: 1.7; flex-shrink: 0; }
.header { height: 76px; padding: 0 26px; display: flex; align-items: center; gap: 28px; background: var(--paper); border-bottom: 1px solid var(--line); }
.brand { display: flex; align-items: center; gap: 12px; color: var(--ink); font-size: 22px; font-weight: 500; line-height: 1.2; }
.brand:hover { text-decoration: none; }
.brand-mark { width: 39px; height: 39px; background: var(--green); color: white; display: grid; place-items: center; border-radius: var(--radius); }
.brand-mark svg { width: 25px; height: 25px; }
.brand small { display: block; font-size: 9px; font-weight: 500; color: var(--muted); margin-top: 5px; }
.connection { display: flex; align-items: center; gap: 7px; color: var(--muted); font-size: 12px; margin-left: auto; }
.status-dot { height: 7px; width: 7px; border-radius: 50%; background: var(--gold); display: inline-block; flex-shrink: 0; }
.status-dot.online, .local-dot { background: var(--green); }
.status-dot.offline { background: var(--red); }
