    const simple=service.catalog.jobs().find(job=>job.payload.prepareForScorecarder);assert.deepEqual(simple.payload.sourceIds,['ontario']);assert.equal(simple.payload.scope,'source');assert.equal(simple.payload.courseId,undefined);assert.equal(simple.payload.storageRoot,destination);assert.equal(simple.progress.result.scorecarder.readyAssets,1);
    assert.match(await page.locator('#job-detail').textContent(),/Ready for Scorecarder1 files/);await page.locator('#job-dialog [data-close]').click();
    const previousJob=await page.locator('#job-title').textContent();await page.getByRole('button',{name:'Download Ontario for Scorecarder',exact:true}).click();await page.locator('#confirm-submit').click();await page.waitForFunction(previous=>document.querySelector('#job-title').textContent.startsWith('Acquire')&&document.querySelector('#job-title').textContent!==previous&&document.querySelector('#job-detail .badge')?.textContent.trim()==='completed',previousJob);
    assert.match(await page.locator('#job-detail').textContent(),/Reused Packages1/);assert.match(await page.locator('#job-detail').textContent(),/Transferred0 B/);await page.locator('#job-dialog [data-close]').click();
    assert.equal(await page.evaluate(()=>localStorage.getItem('terrain.jobDestination')),destination);
