const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const icons = () => window.lucide?.createIcons();
const number = value => Number(value).toLocaleString();
const bytes = value => { if (!value) return '0 B'; const units=['B','KB','MB','GB','TB','PB']; const order=Math.min(units.length-1,Math.floor(Math.log(value)/Math.log(1024))); return `${(value/1024**order).toLocaleString(undefined,{maximumFractionDigits:order>1?2:0})} ${units[order]}`; };
const date = value => value ? new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}) : '--';
const productNames = {'point-cloud':'Point cloud',dtm:'DTM',dem:'DEM',dsm:'DSM',contours:'Contours',hillshade:'Hillshade',slope:'Slope'};
const sourceNames = {ontario:'Ontario',nrcan:'NRCan',pei:'PEI',bc:'British Columbia',quebec:'Quebec',alberta:'Alberta','nova-scotia':'Nova Scotia',saskatchewan:'Saskatchewan','usgs-3dep':'USGS 3DEP',derived:'Generated'};
const sampleBbox = [-79.52,43.64,-79.519,43.641];
const state = {sources:[],sourceIds:new Set(['ontario']),products:new Set(['dtm']),collections:null,courses:[],jobs:[],settings:null,apiKey:'',boundary:null,bbox:null,
  plan:null,planOffset:0,selected:new Set(),localOffset:0,localAssets:[],localTotal:0,assets:new Map(),watchJobs:new Set(),handledJobs:new Set(),view:'acquire',polling:false,folderTarget:'default',folderParent:'',asset:null,assetBlob:null,mapPreview:null,jobId:null,confirm:null};

function toast(message,error=false) { const target=$('#toast'); target.textContent=message;target.classList.toggle('error',error);target.hidden=false;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>{target.hidden=true;},error?9000:4500); }
function openDialog(id) { const dialog=$(id);if(!dialog.open)dialog.showModal();icons(); }
function closeDialog(id) { $(id).close(); }
async function api(url,options={}) {
  const headers={...options.headers};if(state.apiKey)headers.Authorization=`Bearer ${state.apiKey}`;
  if(options.body&&typeof options.body!=='string'){headers['Content-Type']='application/json';options={...options,body:JSON.stringify(options.body)};}
  const response=await fetch(url,{...options,headers});
  if(!response.ok){const data=await response.json().catch(()=>({}));if(response.status===401)openDialog('#auth-dialog');const error=new Error(data.error?.message||`Request failed (${response.status})`);error.status=response.status;throw error;}
  return options.blob?response.blob():response.json();
}
function run(action,preventDefault=true) { return async event=>{if(preventDefault)event?.preventDefault?.();try{await action(event);}catch(error){if(error.status!==401)toast(error.message,true);}}; }
function selectedSources() { return state.sources.filter(source=>state.sourceIds.has(source.id)); }
function gridLabel(asset) { const native=asset.nativeResolutionMeters||asset.resolutionMeters;const output=asset.effectiveCellSizeMeters||asset.requestedResolutionMeters;
  return `<span class="grid-value">${native?`${escapeHtml(native)} m`:asset.angularResolution?`${escapeHtml(asset.angularResolution.toFixed(4))} arc-sec`:'Unknown'}${output&&output!==native?`<small>Output ${escapeHtml(output)} m${asset.resampled?' (resampled)':''}</small>`:asset.densityPointsPerSquareMeter?`<small>${escapeHtml(asset.densityPointsPerSquareMeter)} points/m2</small>`:''}</span>`;
}
function sourceLabel(id) { return sourceNames[id]||state.sources.find(source=>source.id===id)?.name||id; }
function actionButton(action,id,icon,title,disabled=false) { return `<button type="button" class="icon-button small" data-action="${action}" data-id="${escapeHtml(id)}" title="${escapeHtml(title)}" aria-label="${escapeHtml(title)}" ${disabled?'disabled':''}><i data-lucide="${icon}"></i></button>`; }
function assetRow(asset,plan=false) { state.assets.set(asset.id,asset);return `<tr>${plan?`<td><input type="checkbox" data-select-asset="${escapeHtml(asset.id)}" aria-label="Select ${escapeHtml(asset.title||asset.id)}" ${state.selected.has(asset.id)?'checked':''}></td>`:''}<td><span class="file-title">${escapeHtml(asset.title||asset.id)}</span><span class="file-subtitle">${escapeHtml(sourceLabel(asset.sourceId))} / ${escapeHtml(asset.extension?.toUpperCase()||'FILE')}</span></td><td><span class="product-tag">${escapeHtml(productNames[asset.product]||asset.product)}</span></td><td>${gridLabel(asset)}</td><td>${asset.bytes||asset.expectedBytes?bytes(asset.bytes||asset.expectedBytes):'Unknown'}</td>${!plan?`<td><span class="file-subtitle">${date(asset.downloadedAt||asset.generatedAt)}</span></td>`:''}<td class="action-cell"><div class="row-actions">${actionButton('asset',asset.id,'info','Asset details')}${asset.downloaded?actionButton('download',asset.id,'download','Download local file'):actionButton('asset-map',asset.id,'locate-fixed','View footprint')}</div></td></tr>`; }
function emptyRow(columns,message,icon='database') { return `<tr><td colspan="${columns}" class="empty-cell"><i data-lucide="${icon}"></i><span>${escapeHtml(message)}</span></td></tr>`; }
function safeLink(value) { try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?url.href:'#';}catch{return '#';} }

function renderSources() {
  const sources=state.sources.filter(source=>source.adapter!=='local');
  $('#source-controls').innerHTML=sources.map(source=>`<div class="source-row"><label class="source-choice"><input type="checkbox" data-source="${escapeHtml(source.id)}" ${state.sourceIds.has(source.id)?'checked':''}><span><strong>${escapeHtml(sourceLabel(source.id))}</strong><small>${source.options.resolutionsMeters.length?`${source.options.resolutionsMeters.map(value=>`${value}m`).join(' / ')} native`:'Survey-dependent'}</small></span></label>${actionButton('source-acquire',source.id,'download',source.options.scorecarder?`Download ${sourceLabel(source.id)} for Scorecarder`:`No native Scorecarder data for ${sourceLabel(source.id)}`,!source.options.scorecarder)}</div>`).join('');
  const current=$('#local-source').value;$('#local-source').innerHTML='<option value="">All sources</option>'+state.sources.map(source=>`<option value="${escapeHtml(source.id)}">${escapeHtml(sourceLabel(source.id))}</option>`).join('');$('#local-source').value=current;
  renderSourceOptions();icons();
}
function renderSourceOptions() {
  const sources=selectedSources();const products=[...new Set(sources.flatMap(source=>source.options.products))];
  $('#product-controls').innerHTML=products.map(product=>`<label class="check"><input type="checkbox" data-product="${escapeHtml(product)}" ${state.products.has(product)?'checked':''}>${escapeHtml(productNames[product]||product)}</label>`).join('')||'<span class="metadata-note">No sources selected</span>';
  const populate=(id,values,initial)=>{const control=$(id),current=control.value;control.innerHTML=`<option value="">${initial}</option>`+values.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value.toUpperCase()==='TIF'?'GeoTIFF':value.charAt(0).toUpperCase()+value.slice(1))}</option>`).join('');control.value=values.includes(current)?current:'';};
  populate('#delivery',[...new Set(sources.flatMap(source=>source.options.delivery))],'Automatic');
  populate('#format',[...new Set(sources.flatMap(source=>source.options.formats))],'All published');
  const ontario=sources.find(source=>source.id==='ontario');$('#export-options').hidden=!ontario;
  populate('#raster-function',(ontario?.imageService?.rasterFunctions||[]).map(item=>item.name).filter(name=>name&&name!=='None'),'Default elevation');
  $('#native-precision').textContent=sources.flatMap(source=>source.options.resolutionsMeters).length?`Published raster grids: ${[...new Set(sources.flatMap(source=>source.options.resolutionsMeters))].join(', ')} m. Finer export cells are resampled.`:'Native precision varies by survey. Point-cloud spacing is not a raster cell size.';
  const relevant=sources.flatMap(source=>source.collections.filter(collection=>collection.products.some(product=>state.products.has(product))));
  $('#collection-count').textContent=state.collections?`${state.collections.size} selected`:`${relevant.length} available`;
  $('#collection-controls').innerHTML=sources.map(source=>`<div class="collection-group"><h3>${escapeHtml(sourceLabel(source.id))}</h3>${source.collections.map(collection=>{const enabled=collection.products.some(product=>state.products.has(product));return `<label class="collection-choice ${enabled?'':'disabled'}"><input type="checkbox" data-collection="${escapeHtml(collection.id)}" ${(state.collections?state.collections.has(collection.id):enabled)?'checked':''} ${enabled?'':'disabled'}><span>${escapeHtml(collection.name)}<small>${escapeHtml(collection.resolutionMeters?`${collection.resolutionMeters} m`:'Survey-dependent')} / ${escapeHtml(collection.delivery||'tiles')} / ${escapeHtml((collection.formats||[]).join(', '))}</small></span></label>`;}).join('')}</div>`).join('');
  $('#source-note').innerHTML=sources.map(source=>`<p><a href="${escapeHtml(safeLink(source.license.url))}" target="_blank" rel="noopener">${escapeHtml(source.license.title)}</a>${source.note?`<br>${escapeHtml(source.note)}`:''}</p>`).join('');
  renderCoverage();
}
function renderCourses() {
  const previous=$('#area-course').value;const options=state.courses.map(course=>`<option value="${escapeHtml(course.id)}">${escapeHtml(course.name)}</option>`).join('');
  $('#area-course').innerHTML='<option value="">Unassigned area</option><option value="__sample">Ontario sample area</option>'+options;$('#area-course').value=previous;
  const local=$('#local-course').value;$('#local-course').innerHTML='<option value="">All courses</option>'+options;$('#local-course').value=local;$('#processing-course').innerHTML=options;
  $('#course-rows').innerHTML=state.courses.map(course=>`<tr><td><span class="file-title">${escapeHtml(course.name)}</span><span class="file-subtitle">${escapeHtml(course.id)}</span></td><td>${escapeHtml(course.province||course.region||'National')} / ${escapeHtml(course.country)}</td><td>${escapeHtml(course.boundary?.geometry?.type||course.boundary?.type||'Polygon')}</td><td>${number(course.bufferMeters||0)} m</td><td class="action-cell"><div class="row-actions">${actionButton('course-map',course.id,'map','Acquire for course')}${actionButton('course-assets',course.id,'database','Course files')}${actionButton('course-process',course.id,'mountain','Generate terrain')}${actionButton('course-package',course.id,'package','Export terrain package')}</div></td></tr>`).join('')||emptyRow(5,'No saved courses','flag');icons();
