  $('#connection-port').textContent=`:${settings.port||location.port||(location.protocol==='https:'?443:80)}`;
  $('#storage-short').textContent=settings.storageRoot;$('#default-folder-button').title=settings.storageRoot;$('#asset-count').textContent=number(settings.stats.assets);$('#job-count').textContent=number(settings.stats.activeJobs);
  $('#stat-files').textContent=number(settings.stats.assets);$('#stat-bytes').textContent=bytes(settings.stats.bytes);$('#stat-courses').textContent=number(settings.stats.courses);$('#stat-free').textContent=settings.disk?bytes(settings.disk.freeBytes):'Unknown';
  $('#free-space').textContent=settings.disk?`${bytes(settings.disk.freeBytes)} free at default destination`:'';$('#footer-status').textContent=`${number(settings.stats.assets)} local files / ${bytes(settings.stats.bytes)} / ${number(settings.stats.courses)} courses`;
