async function loadSources() { state.sources=(await api('/api/sources')).sources;renderSources(); }
async function loadCourses() { state.courses=(await api('/api/courses')).courses;renderCourses(); }
function setView(view) { state.view=view;$$('.view').forEach(element=>{element.hidden=element.id!==`view-${view}`;});$$('[data-view]').forEach(button=>{button.classList.toggle('active',button.dataset.view===view);button.toggleAttribute('aria-current',button.dataset.view===view);if(button.dataset.view===view)button.setAttribute('aria-current','page');});if(view==='acquire')requestAnimationFrame(()=>state.map.invalidateSize());if(view==='repository')loadLocal().catch(error=>toast(error.message,true)); }

function featureForBbox(extent) { return {type:'Feature',properties:{},geometry:{type:'Polygon',coordinates:[[[extent[0],extent[1]],[extent[2],extent[1]],[extent[2],extent[3]],[extent[0],extent[3]],[extent[0],extent[1]]]]}}; }
function boundaryExtent(boundary) { const coordinates=[];const visit=value=>{if(Array.isArray(value)&&typeof value[0]==='number')coordinates.push(value);else if(Array.isArray(value))value.forEach(visit);};visit(boundary.geometry?.coordinates||boundary.coordinates);if(!coordinates.length)throw new Error('Boundary has no coordinates.');return [Math.min(...coordinates.map(point=>point[0])),Math.min(...coordinates.map(point=>point[1])),Math.max(...coordinates.map(point=>point[0])),Math.max(...coordinates.map(point=>point[1]))]; }
function clearMapPreview() { if(state.mapPreview){state.mapPreview.remove();URL.revokeObjectURL(state.mapPreviewUrl);state.mapPreview=null;}state.planLayer?.addTo(state.map);state.mapSelection?.addTo(state.map); }
function setBoundary(boundary,fit=true) {
  clearMapPreview();
  state.boundary=boundary?.type==='Feature'?boundary:boundary?{type:'Feature',properties:{},geometry:boundary}:null;state.bbox=boundary?boundaryExtent(state.boundary):null;state.drawn.clearLayers();
  if(boundary)L.geoJSON(state.boundary,{style:{color:'#206c5a',weight:2,fillOpacity:.08}}).eachLayer(layer=>state.drawn.addLayer(layer));
  ['west','south','east','north'].forEach((key,index)=>{$(`#bbox-${key}`).value=state.bbox?Number(state.bbox[index].toFixed(7)):'';});
  $('#boundary-label').textContent=boundary?`${state.boundary.geometry.type} boundary`:'No boundary';$('#map-location').textContent=state.bbox?`${state.bbox[0].toFixed(4)}, ${state.bbox[1].toFixed(4)} / ${state.bbox[2].toFixed(4)}, ${state.bbox[3].toFixed(4)}`:'Canada & United States';$('#course-boundary-status').textContent=boundary?`WGS84 ${state.boundary.geometry.type} / ${state.bbox.map(value=>value.toFixed(5)).join(', ')}`:'No boundary selected';
  if(boundary&&fit)state.map.fitBounds([[state.bbox[1],state.bbox[0]],[state.bbox[3],state.bbox[2]]],{padding:[35,35],maxZoom:18});loadFootprints().catch(error=>{if(error.status!==401)toast(error.message,true);});
}
function renderCoverage() { if(!state.coverage)return;state.coverage.clearLayers();selectedSources().forEach(source=>L.geoJSON(featureForBbox(source.coverageBbox),{style:{color:'#bea253',weight:1,dashArray:'5 5',fillOpacity:0},interactive:false}).addTo(state.coverage)); }
function setAssetSelection(id,selected) { if(!state.plan?.assetIds.includes(id))return;selected?state.selected.add(id):state.selected.delete(id);renderPlanSelection(); }
function planStyle(feature) { return state.selected.has(feature.properties.assetId)?{color:'#206c5a',weight:2,fillColor:'#206c5a',fillOpacity:.2}:{color:'#c49631',weight:1.4,fillColor:'#c49631',fillOpacity:.08}; }
function bindPlanFeature(feature,layer) {
  const id=feature.properties.assetId;const title=feature.properties.title||id;
  layer.bindTooltip(escapeHtml(title),{sticky:true});layer.on('click',()=>setAssetSelection(id,!state.selected.has(id)));
  layer.on('add',()=>{const element=layer.getElement();element.setAttribute('data-map-asset',id);element.setAttribute('tabindex','0');element.setAttribute('role','checkbox');element.setAttribute('aria-label',`Select ${title}`);element.setAttribute('aria-checked',String(state.selected.has(id)));element.onkeydown=event=>{if(event.key===' '||event.key==='Enter'){event.preventDefault();event.stopPropagation();setAssetSelection(id,!state.selected.has(id));}};});
}
function renderMapSelection() {
  if(!state.planLayer)return;state.mapSelection.clearLayers();
  state.planLayer.eachLayer(layer=>{
    const id=layer.feature.properties.assetId;const selected=state.selected.has(id);layer.setStyle(planStyle(layer.feature));layer.getElement()?.setAttribute('aria-checked',String(selected));
    if(!selected)return;const title=layer.feature.properties.title||id;
    const marker=L.marker(layer.getBounds().getCenter(),{icon:L.divIcon({className:'map-selection-marker',iconSize:[28,28],iconAnchor:[14,14],html:`<label title="${escapeHtml(`Remove ${title} from download selection`)}"><input type="checkbox" checked data-select-map-asset="${escapeHtml(id)}" aria-label="${escapeHtml(`Select ${title}`)}"></label>`}),bubblingMouseEvents:false});
    marker.on('add',()=>{const element=marker.getElement();L.DomEvent.disableClickPropagation(element);element.querySelector('input').addEventListener('change',event=>setAssetSelection(id,event.target.checked));});marker.addTo(state.mapSelection);
  });
}
function initMap() {
  state.map=L.map('map',{zoomControl:true,preferCanvas:true,minZoom:2,maxZoom:20,worldCopyJump:false}).setView([51,-101],3);L.control.scale({imperial:false}).addTo(state.map);
  state.map.createPane('terrain-preview');state.map.getPane('terrain-preview').style.zIndex=350;
  state.map.createPane('plan-assets');state.map.getPane('plan-assets').style.zIndex=430;
  state.land=L.geoJSON(null,{style:{color:'#b9c6bf',weight:1,fillColor:'#e9eee4',fillOpacity:1},interactive:false}).addTo(state.map);state.coverage=L.featureGroup().addTo(state.map);state.localLayer=L.geoJSON(null,{style:{color:'#536863',weight:1,fillOpacity:.09}}).addTo(state.map);state.planLayer=L.geoJSON(null,{renderer:L.svg({pane:'plan-assets'}),pane:'plan-assets',style:planStyle,onEachFeature:bindPlanFeature,bubblingMouseEvents:false}).addTo(state.map);state.mapSelection=L.featureGroup().addTo(state.map);state.drawn=L.featureGroup().addTo(state.map);
  state.map.addControl(new L.Control.Draw({position:'topleft',draw:{polyline:false,marker:false,circle:false,circlemarker:false,polygon:{allowIntersection:false,showArea:true,shapeOptions:{color:'#206c5a'}},rectangle:{shapeOptions:{color:'#206c5a'}}},edit:{featureGroup:state.drawn,edit:false,remove:true}}));
  state.map.on(L.Draw.Event.CREATED,event=>{$('#area-course').value='';setBoundary(event.layer.toGeoJSON(),false);});state.map.on(L.Draw.Event.DELETED,()=>{if(!state.drawn.getLayers().length)setBoundary(null,false);});
  state.map.on('click',run(async event=>{if(!state.bbox||!state.localFeatures?.length)return;const result=await api(`/api/terrain/elevation?lng=${event.latlng.lng}&lat=${event.latlng.lat}`);const value=result.points[0];if(value.elevation!=null)L.popup().setLatLng(event.latlng).setContent(`${escapeHtml(value.elevation.toFixed(3))} ${escapeHtml(value.units==='meters'?'m':value.units==='feet'?'ft':value.units)}<br><small>${escapeHtml(sourceLabel(value.sourceId))}</small>`).openOn(state.map);}));
}
async function loadLand() { state.land.clearLayers();state.land.addData(await api('/api/map/land'));renderCoverage(); }
async function loadFootprints() { if(!state.map||!state.settings)return;const query=new URLSearchParams({resolution:'all'});if(state.bbox)query.set('bbox',state.bbox.join(','));const result=await api(`/api/terrain/footprints?${query}`);state.localFeatures=result.features;state.localLayer.clearLayers();state.localLayer.addData(result);$('#map-file-count').textContent=`${number(result.features.length)} local files`; }
async function chooseArea(id) { if(id==='__sample'){$('#buffer').value=0;setBoundary(featureForBbox(sampleBbox));return;}if(id){const course=state.courses.find(item=>item.id===id);$('#buffer').value=course.bufferMeters??500;setBoundary(course.boundary);} }
function requestExtent() { const scope=$('input[name="scope"]:checked').value;if(scope==='source')return {scope};if(!state.boundary)throw new Error('Select a boundary, enter a bounding box, or choose the Ontario sample area.');return {scope,boundary:state.boundary,bufferMeters:Number($('#buffer').value)}; }
function acquisitionPayload() {
  if(!state.sourceIds.size)throw new Error('Select at least one source.');const available=selectedSources().flatMap(source=>source.options.products);const products=[...state.products].filter(product=>available.includes(product));if(!products.length)throw new Error('Select at least one available product.');
  if(state.collections&&!state.collections.size)throw new Error('Select a collection or return to automatic collection selection.');
  const resolution=$('#resolution').value;const courseId=$('#area-course').value;return {...requestExtent(),sourceIds:[...state.sourceIds],products,resolution:resolution==='custom'?Number($('#custom-resolution').value):resolution,
    ...($('#delivery').value?{delivery:$('#delivery').value}:{}),...($('#format').value?{formats:[$('#format').value]}:{}),...(state.collections?{collectionIds:[...state.collections]}:{}),interpolation:$('#interpolation').value,
    ...($('#raster-function').value?{rasterFunction:$('#raster-function').value}:{}),...(courseId&&courseId!=='__sample'?{courseId}:{}),storageRoot:$('#job-destination').value};
}
async function queueJob(url,payload,show=true) { const job=await api(url,{method:'POST',body:payload});state.watchJobs.add(job.id);await pollJobs();toast(`${job.type.charAt(0).toUpperCase()+job.type.slice(1)} job queued`);if(show)await showJob(job.id);return job; }
async function loadPlan(id,offset=0,reset=true) {
  clearMapPreview();
  const plan=await api(`/api/discovery/${id}?offset=${offset}&limit=50`);state.plan=plan;state.planOffset=offset;if(reset)state.selected=new Set(plan.assetIds);localStorage.setItem('terrain.lastPlan',id);
  $('#plan-heading').textContent=`${number(plan.total)} discovered files`;$('#plan-summary').textContent=`${plan.complete?'Complete enumeration':'Incomplete enumeration'} / ${number(state.selected.size)} selected`;
  const warnings=[...(plan.errors||[]).map(item=>`${item.sourceId||item.collectionId||'Provider'}: ${item.message||item.error||item}`),...(plan.warnings||[]).map(item=>typeof item==='string'?item:item.message||JSON.stringify(item))];$('#plan-warnings').hidden=!warnings.length;$('#plan-warnings').innerHTML=warnings.map(message=>`<div class="warning-note">${escapeHtml(message)}</div>`).join('');
  $('#plan-rows').innerHTML=plan.assets.map(asset=>assetRow(asset,true)).join('')||emptyRow(6,'No coverage found for the selected products','map-pin-off');$('#plan-page-label').textContent=plan.total?`${number(offset+1)} - ${number(offset+plan.assets.length)} of ${number(plan.total)} files`:'0 files';$('#plan-previous').disabled=offset===0;$('#plan-next').disabled=plan.nextOffset==null;
  state.planLayer.clearLayers();plan.assets.forEach(asset=>{const feature=asset.geometry?{type:'Feature',properties:{},geometry:asset.geometry}:featureForBbox(asset.bounds);feature.properties={assetId:asset.id,title:asset.title};state.planLayer.addData(feature);});
  renderPlanSelection();icons();
}
function renderPlanSelection() { $('#download-plan').disabled=!state.plan||!state.selected.size;$('#download-plan span').textContent=`Download ${number(state.selected.size)}`;$('#select-all-plan').checked=!!state.plan&&state.selected.size===state.plan.assetIds.length;$('#select-all-plan').indeterminate=!!state.plan&&state.selected.size>0&&state.selected.size<state.plan.assetIds.length;$$('[data-select-asset]').forEach(input=>{input.checked=state.selected.has(input.dataset.selectAsset);});if(state.plan)$('#plan-summary').textContent=`${state.plan.complete?'Complete enumeration':'Incomplete enumeration'} / ${number(state.selected.size)} selected`;renderMapSelection(); }
function confirmDownload() {
  if(!state.plan||!state.selected.size)return;
  const destination=$('#job-destination').value;const plan=state.plan;$('#confirm-title').textContent=plan.complete?'Confirm Download':'Download Partial Plan';$('#confirm-message').textContent=`${number(state.selected.size)} files to ${destination}.${plan.complete?'':' Provider discovery is incomplete; only the listed files will be downloaded.'}${$('#process-after').checked?' Terrain processing will follow.':''}`;
  state.confirm=async()=>{const courseId=$('#area-course').value;await queueJob('/api/downloads',{planId:plan.id,...(state.selected.size===plan.assetIds.length?{}:{assetIds:[...state.selected]}),storageRoot:destination,
    allowPartial:!plan.complete,...(courseId&&courseId!=='__sample'?{courseId}:{}),...(state.boundary?{boundary:state.boundary,bufferMeters:Number($('#buffer').value)}:{}),processAfterDownload:$('#process-after').checked});};openDialog('#confirm-dialog');
}
function confirmSourceAcquisition(id) {
  const source=state.sources.find(item=>item.id===id);const preset=source?.options.scorecarder;
  if(!preset)throw new Error('This source has no native Scorecarder data.');
  const destination=$('#job-destination').value.trim()||state.settings.storageRoot;
  localStorage.setItem('terrain.jobDestination',destination);
  $('#confirm-title').textContent=`Download ${sourceLabel(id)} for Scorecarder`;
  $('#confirm-message').textContent=`Whole source / ${preset.products.map(product=>productNames[product]||product).join(' + ')} / native grids. Destination: ${destination}. Originals and extracted files are retained; allow disk space for both. Provider failures stop the job without discarding completed files.`;
  state.confirm=()=>queueJob(`/api/sources/${encodeURIComponent(id)}/acquire`,{storageRoot:destination});openDialog('#confirm-dialog');
}
async function loadLocal(offset=state.localOffset) {
  const query=new URLSearchParams({limit:'50',offset:String(offset),resolution:$('#local-resolution').value});for(const[id,key]of [['#local-source','sourceIds'],['#local-product','products'],['#local-course','courseId'],['#local-search','q']])if($(id).value)query.set(key,$(id).value);
  const result=await api(`/api/terrain/query?${query}`);state.localAssets=result.assets;state.localOffset=offset;state.localTotal=result.total;$('#local-rows').innerHTML=result.assets.map(asset=>assetRow(asset)).join('')||emptyRow(6,'No local files match this selection');$('#local-page-label').textContent=result.total?`${number(offset+1)} - ${number(offset+result.assets.length)} of ${number(result.total)} files`:'0 files';$('#local-previous').disabled=offset===0;$('#local-next').disabled=result.nextOffset==null;icons();
}
function progressLabel(job) { const progress=job.progress;return `${progress.message||`${progress.stage||job.type}${progress.total?` / ${number(progress.completed||0)} of ${number(progress.total)}`:''}`}${progress.reused?` / ${number(progress.reused)} reused`:''}${progress.resumed?` / ${number(progress.resumed)} resumed`:''}`; }
function progressBar(job) { return `<span class="progress-label">${escapeHtml(progressLabel(job))}</span><progress max="${job.progress.total||100}" ${job.progress.total||job.status==='completed'?`value="${job.status==='completed'?(job.progress.total||100):(job.progress.completed||0)}"`:''}></progress>`; }
function renderJobs() {
  $('#job-rows').innerHTML=state.jobs.map(job=>`<tr><td><span class="file-title">${escapeHtml(job.type.charAt(0).toUpperCase()+job.type.slice(1))}</span><span class="file-subtitle">${escapeHtml(job.payload.courseId||job.payload.sourceIds?.map(sourceLabel).join(', ')||job.id.slice(0,8))}</span></td><td><span class="badge ${escapeHtml(job.status)}">${escapeHtml(job.status)}</span></td><td>${progressBar(job)}</td><td>${bytes(job.progress.bytes||0)}</td><td><span class="file-subtitle">${date(job.updatedAt)}</span></td><td class="action-cell"><div class="row-actions">${actionButton('job',job.id,'list','Job details')}${['queued','running'].includes(job.status)?actionButton('job-cancel',job.id,'square','Cancel job'):['failed','cancelled'].includes(job.status)?actionButton('job-retry',job.id,'rotate-ccw','Retry job'):job.progress.result?.planId?actionButton('job-plan',job.id,'scan-search','Review acquisition plan'):''}</div></td></tr>`).join('')||emptyRow(6,'No queued or completed jobs','activity');icons();
}
async function pollJobs() {
  if(state.polling||!state.settings)return;state.polling=true;
  try{
    state.jobs=(await api('/api/jobs')).jobs;renderJobs();$('#job-count').textContent=number(state.jobs.filter(job=>['running','queued'].includes(job.status)).length);
    for(const job of state.jobs){if(!state.watchJobs.has(job.id)||state.handledJobs.has(job.id)||!['completed','failed','cancelled'].includes(job.status))continue;state.handledJobs.add(job.id);if(job.progress.result?.planId)await loadPlan(job.progress.result.planId);await refreshSettings();await loadCourses();await loadFootprints();if(state.view==='repository')await loadLocal();if(job.status==='failed')toast(job.error,true);}
    if($('#job-dialog').open&&state.jobId)await renderJobDetails(state.jobId);
  }catch(error){if(error.status!==401){$('#connection-dot').className='status-dot offline';$('#connection-label').textContent='Disconnected';}}
